# ═════════ التحقق من صحة أرقام الهواتف (مكتبة phonenumbers) ═════════
import re

try:
    import phonenumbers
    from phonenumbers import geocoder, PhoneMetadata
    _HAS_PN = True
except Exception:
    phonenumbers = None
    _HAS_PN = False

_AR_DIGITS = str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789")


def validate_phone_number(raw, default_region="EG"):
    """يرجع (ok, message, info). الأرقام اللي بتبدأ بـ 0 تُعتبر مصرية، واللي بـ + أو 00 دولية."""
    s = str(raw or "").strip().translate(_AR_DIGITS)
    s = re.sub(r"[\s\-\.\(\)]", "", s)
    if not s:
        return True, "", {}
    if s.startswith("00"):
        s = "+" + s[2:]
    if not re.fullmatch(r"\+?\d+", s):
        return False, "الرقم يحتوي على رموز أو حروف غير مسموحة", {}

    # ---------- بدون المكتبة: فحص أساسي ----------
    if not _HAS_PN:
        if s.startswith("+"):
            ok = 8 <= len(s) - 1 <= 15
            return ok, ("" if ok else "الرقم الدولي يجب أن يكون بين 8 و15 رقماً"), {}
        ok = re.fullmatch(r"01[0125]\d{8}", s) is not None
        return ok, ("" if ok else "الرقم المصري يجب أن يبدأ بـ 010 أو 011 أو 012 أو 015 ويتكون من 11 رقماً"), {}

    # ---------- بالمكتبة ----------
    no_prefix = False
    if s.startswith("+"):
        candidate, region_hint = s, None
    elif s.startswith("0"):
        candidate, region_hint = s, default_region      # محلي مصري
    else:
        candidate, region_hint = "+" + s, None          # كود دولة بدون +
        no_prefix = True
    try:
        num = phonenumbers.parse(candidate, region_hint)
    except phonenumbers.NumberParseException:
        return False, "الرقم غير مفهوم، تأكد من كتابته", {}

    region = phonenumbers.region_code_for_number(num) or \
        phonenumbers.region_code_for_country_code(num.country_code)
    country = geocoder.country_name_for_number(num, "ar") or \
        geocoder.description_for_number(num, "ar") or (region or "")
    info = {"region": region, "country": country, "e164": phonenumbers.format_number(
        num, phonenumbers.PhoneNumberFormat.E164)}

    if phonenumbers.is_valid_number(num):
        return True, "", info

    # سبب الخطأ + عدد الأرقام المطلوب
    reason = phonenumbers.is_possible_number_with_reason(num)
    lens = ""
    try:
        md = PhoneMetadata.metadata_for_region(region)
        pl = sorted(set(md.mobile.possible_length or md.general_desc.possible_length))
        pl = [p for p in pl if p > 0]
        if pl:
            lens = " أو ".join(str(p) for p in pl)
    except Exception:
        pass
    if reason == phonenumbers.ValidationResult.TOO_SHORT:
        why = "عدد الأرقام أقل من المطلوب"
    elif reason == phonenumbers.ValidationResult.TOO_LONG:
        why = "عدد الأرقام أكثر من المطلوب"
    else:
        why = "بداية الرقم أو شكله غير صحيح"
    if region == default_region and not s.startswith("+") and not no_prefix:
        return False, "الرقم المصري يجب أن يبدأ بـ 010 أو 011 أو 012 أو 015 ويتكون من 11 رقماً", info
    if no_prefix:
        return False, ("الرقم غير صحيح. الرقم المصري يبدأ بـ 0 (مثل 01012345678)، "
                       "والرقم الدولي يبدأ بـ + وكود الدولة (مثل +966501234567)"), info
    msg = f"{why}" + (f" لدولة {country}" if country else "")
    if lens:
        msg += f" (المطلوب بعد كود الدولة: {lens} أرقام)"
    return False, msg, info


def normalize_msisdn(phone_number):
    """تحويل الرقم لصيغة MSISDN. يرجع None لو غير صالح."""
    if not phone_number:
        return None
    p = str(phone_number).strip().replace(" ", "").replace("-", "")
    if p.startswith("0020"):
        p = p[4:]
    elif p.startswith("+20"):
        p = p[3:]
    elif p.startswith("20") and len(p) >= 12:
        p = p[2:]
    elif p.startswith("0") and len(p) == 11:
        p = p[1:]
    if p.isdigit() and len(p) == 10 and p[:2] in ("10", "11", "12", "15"):
        return "20" + p
    raw = str(phone_number).strip().replace(" ", "").replace("-", "").lstrip("+")
    if raw.startswith("00"):
        raw = raw[2:]
    if raw.isdigit() and 8 <= len(raw) <= 15:
        return raw
    return None


def first_name(full_name):
    """الاسم الأول فقط."""
    parts = str(full_name or "").strip().split()
    return parts[0] if parts else ""


def build_review_message(template, name, store, link):
    """يملأ القالب مع تنظيف المسافات الزائدة."""
    template = (template or DEFAULT_REVIEW_TEMPLATE)
    name = first_name(name)
    msg = template.replace("{name}", name).replace("{store}", (store or "").strip()) \
                  .replace("{link}", (link or "").strip())
    msg = msg.replace("أهلاً ،", "أهلاً،").replace(" ،", "،").replace("  ", " ").strip()
    return msg


def sms_length_info(text):
    """يرجع (عدد الأحرف, عدد الرسائل المحسوبة)."""
    n = len(text or "")
    if n == 0:
        return 0, 0
    if any(ord(c) > 127 for c in text):
        return n, 1 if n <= 70 else math.ceil(n / 67)
    return n, 1 if n <= 160 else math.ceil(n / 153)


