from datetime import date as _date_cls

DEFAULT_BOOKING_CONFIRM_TEMPLATE = (
    "أهلاً {name}، تم تأكيد حجزك في {store} يوم {day} {date} الساعة {time}. "
    "بانتظارك."
)
DEFAULT_BOOKING_REMINDER_TEMPLATE = (
    "أهلاً {name}، نذكّرك بموعدك في {store} اليوم الساعة {time}. "
    "نرجو الحضور قبل الموعد بـ 10 دقائق."
)
_AR_WEEKDAYS = ["الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد"]


def _booking_when(res_date, res_time):
    """يحوّل تاريخ/وقت الحجز (str / date / timedelta) إلى (تاريخ نصي, وقت 12 ساعة, اسم اليوم, datetime)."""
    d = None
    if isinstance(res_date, datetime):
        d = res_date.date()
    elif isinstance(res_date, _date_cls):
        d = res_date
    else:
        try:
            d = datetime.strptime(str(res_date or "")[:10], "%Y-%m-%d").date()
        except ValueError:
            d = None
    if isinstance(res_time, timedelta):
        secs = int(res_time.total_seconds())
        hh, mm = (secs // 3600) % 24, (secs % 3600) // 60
    else:
        try:
            p = str(res_time or "").split(":")
            hh, mm = int(p[0]), int(p[1])
        except (ValueError, IndexError):
            hh, mm = 0, 0
    time_s = f"{(hh % 12) or 12}:{mm:02d} {'م' if hh >= 12 else 'ص'}"
    date_s = d.strftime("%Y-%m-%d") if d else str(res_date or "")
    day_s = _AR_WEEKDAYS[d.weekday()] if d else ""
    appt = datetime(d.year, d.month, d.day, hh, mm) if d else None
    return date_s, time_s, day_s, appt


def build_booking_message(template, name, store, res_date, res_time, employees="", services=""):
    """يملأ قالب رسالة الحجز. المتغيرات: {name} {store} {date} {day} {time} {employee} {services}"""
    date_s, time_s, day_s, _appt = _booking_when(res_date, res_time)
    msg = template or ""
    for k, v in (("{name}", first_name(name)), ("{store}", (store or "").strip()),
                 ("{date}", date_s), ("{day}", day_s), ("{time}", time_s),
                 ("{employee}", employees or ""), ("{services}", services or "")):
        msg = msg.replace(k, v)
    msg = msg.replace("أهلاً ،", "أهلاً،").replace(" ،", "،")
    while "  " in msg:
        msg = msg.replace("  ", " ")
    return msg.strip()


def process_booking_sms(db_config, reservation_id, kind):
    """يرسل رسالة حجز ('confirm' تأكيد | 'reminder' تذكير) في اتصال DB مستقل ويسجّل النتيجة.
    أعلام customer_reservations: 0 لم يُرسل | 9 قيد المعالجة (حجز آمن لمنع التكرار بين الأجهزة)
    | 1 تم الإرسال | 2 تخطّي/فشل. يرجع (status, reason)."""
    is_confirm = (kind == 'confirm')
    flag_col = 'confirm_sms_sent' if is_confirm else 'reminder_sms_sent'
    conn = None
    cur = None
    try:
        conn = pymysql.connect(**db_config, cursorclass=pymysql.cursors.DictCursor)
        cur = conn.cursor()
        cur.execute("SELECT * FROM booking_sms_settings WHERE id = 1")
        st = cur.fetchone() or {}
        if not st.get('confirm_enabled' if is_confirm else 'reminder_enabled'):
            return 'disabled', ''

        # حجز الحجز للمعالجة (مرة واحدة فقط حتى لو فيه أكثر من جهاز)
        cur.execute(f"UPDATE customer_reservations SET {flag_col} = 9 "
                    f"WHERE id = %s AND send_sms = 1 AND {flag_col} = 0", (reservation_id,))
        conn.commit()
        if cur.rowcount != 1:
            return 'skipped', 'تمت المعالجة مسبقاً أو الإرسال غير مفعّل لهذا الحجز'

        res = {}

        def _finish(code, status, phone, message, reason):
            try:
                cur.execute(f"UPDATE customer_reservations SET {flag_col} = %s WHERE id = %s",
                            (code, reservation_id))
                cur.execute(
                    "INSERT INTO booking_sms_log "
                    "(reservation_id, customer_id, phone, kind, status, message, reason, sent_at) "
                    "VALUES (%s, %s, %s, %s, %s, %s, %s, NOW())",
                    (reservation_id, res.get('customer_id'), phone, kind, status, message, reason))
                conn.commit()
            except Exception as _e:
                print(f"[SMS-حجز] تعذر تسجيل النتيجة: {_e}")
            return status, reason or ''

        cur.execute("SELECT customer_id, customer_name, customer_phone, reservation_date, reservation_time "
                    "FROM customer_reservations WHERE id = %s", (reservation_id,))
        res = cur.fetchone() or {}
        if not res:
            return _finish(2, 'skipped', '', None, 'الحجز غير موجود')

        name = res.get('customer_name') or ''
        phone = (res.get('customer_phone') or '').strip()
        if not phone and res.get('customer_id'):
            cur.execute("SELECT phone FROM customers WHERE id = %s", (res['customer_id'],))
            _c = cur.fetchone() or {}
            phone = (_c.get('phone') or '').strip()
        if not phone:
            return _finish(2, 'skipped', '', None, 'رقم الهاتف غير مسجل')
        if not normalize_msisdn(phone):
            return _finish(2, 'skipped', phone, None, 'رقم هاتف غير صالح')

        _d, _t, _day, appt = _booking_when(res.get('reservation_date'), res.get('reservation_time'))
        if (not is_confirm) and appt and appt <= datetime.now():
            return _finish(2, 'skipped', phone, None, 'انتهى موعد الحجز قبل إرسال التذكير')

        cur.execute("SELECT store_name FROM invoice_settings WHERE id = 1")
        store = ((cur.fetchone() or {}).get('store_name') or '').strip()

        cur.execute(
            "SELECT DISTINCT e.name AS emp, rii.product_name AS svc "
            "FROM reserved_invoices ri "
            "JOIN reserved_invoice_items rii ON rii.reserved_invoice_id = ri.id "
            "LEFT JOIN employees e ON e.id = rii.employee_id "
            "WHERE ri.reservation_id = %s", (reservation_id,))
        rows = cur.fetchall() or []
        employees = "، ".join(dict.fromkeys(r['emp'] for r in rows if r.get('emp')))
        services = "، ".join(dict.fromkeys(r['svc'] for r in rows if r.get('svc')))

        template = (st.get('confirm_template') if is_confirm else st.get('reminder_template')) or \
                   (DEFAULT_BOOKING_CONFIRM_TEMPLATE if is_confirm else DEFAULT_BOOKING_REMINDER_TEMPLATE)
        message = build_booking_message(template, name, store, res.get('reservation_date'),
                                        res.get('reservation_time'), employees, services)

        api_cfg = load_sms_api_settings(cur)
        if not api_cfg:
            return _finish(2, 'skipped', phone, message, 'إعدادات SMS API غير مكتملة')

        ok, details = send_sms(api_cfg, phone, message)
        if ok:
            print(f"[SMS-حجز] ✅ {kind} → {name} ({phone})")
        else:
            print(f"[SMS-حجز] ❌ فشل {kind} → {phone}: {details}")
        return _finish(1 if ok else 2, 'sent' if ok else 'failed', phone, message, None if ok else details)
    except Exception as _e:
        print(f"[SMS-حجز] خطأ غير متوقع: {_e}")
        try:
            if cur is not None:
                cur.execute(f"UPDATE customer_reservations SET {flag_col} = 2 "
                            f"WHERE id = %s AND {flag_col} = 9", (reservation_id,))
                conn.commit()
        except Exception:
            pass
        return 'failed', str(_e)
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def _booking_reminder_loop(db_config):
    """حلقة خلفية: كل دقيقة تُرسل التذكيرات التي حان وقتها (طالما البرنامج مفتوح)."""
    import time as _time
    _time.sleep(20)
    while True:
        ids = []
        conn = None
        try:
            conn = pymysql.connect(**db_config, cursorclass=pymysql.cursors.DictCursor)
            cur = conn.cursor()
            cur.execute("SELECT reminder_enabled FROM booking_sms_settings WHERE id = 1")
            s = cur.fetchone() or {}
            if s.get('reminder_enabled'):
                cur.execute(
                    "SELECT id FROM customer_reservations "
                    "WHERE send_sms = 1 AND reminder_sms_sent = 0 "
                    "AND reminder_time IS NOT NULL AND reminder_time <= NOW() "
                    "ORDER BY reminder_time LIMIT 20")
                ids = [r['id'] for r in cur.fetchall()]
        except Exception as _e:
            print(f"[SMS-حجز] تعذر فحص التذكيرات: {_e}")
        finally:
            if conn:
                try:
                    conn.close()
                except Exception:
                    pass
        for _rid in ids:
            try:
                process_booking_sms(db_config, _rid, 'reminder')
            except Exception as _e:
                print(f"[SMS-حجز] خطأ في التذكير: {_e}")
        _time.sleep(60)


def load_sms_api_settings(cursor):
    """قراءة إعدادات SMS API من جدول sms_settings."""
    try:
        cursor.execute("SELECT * FROM sms_settings WHERE id = 1")
        r = cursor.fetchone()
    except Exception:
        return None
    if not r:
        return None
    verify = r.get('api_verify_ssl')
    cfg = {
        'account_id': (r.get('api_account_id') or '').strip(),
        'password': (r.get('api_password') or '').strip(),
        'hash_key': (r.get('api_secure_hash_key') or '').strip(),
        'sender': (r.get('api_sender_name') or '').strip(),
        'base_url': (r.get('api_base_url') or '').strip().rstrip('/'),
        'mode': (r.get('api_mode') or 'notification').strip() or 'notification',
        'verify_ssl': True if verify is None else bool(verify),
    }
    if not all(cfg[k] for k in ('account_id', 'password', 'hash_key', 'sender', 'base_url')):
        return None
    return cfg


def _sms_submit_once(cfg, phone_number, message, external_trx_id, hash_mode):
    """محاولة إرسال واحدة."""
    try:
        receiver = normalize_msisdn(phone_number)
        if not receiver:
            return False, f"رقم هاتف غير صالح: {phone_number}", None

        params = [("AccountId", cfg['account_id']), ("Password", cfg['password']),
                  ("SenderName", cfg['sender']), ("ReceiverMSISDN", receiver), ("SMSText", message)]
        if external_trx_id:
            params.append(("ExternalTrxId", external_trx_id))

        key = bytes.fromhex(cfg['hash_key']) if hash_mode == 'hex' else cfg['hash_key'].encode('utf-8')
        secure_hash = hmac.new(key, "&".join(f"{k}={v}" for k, v in params).encode('utf-8'),
                               hashlib.sha256).hexdigest().upper()

        trx_xml = f"<ExternalTrxId>{_xml_escape(external_trx_id)}</ExternalTrxId>" if external_trx_id else ""
        xml_body = (
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<SubmitSMSRequest xmlns="http://www.edafa.com/web2sms/sms/model/">'
            f'<AccountId>{_xml_escape(cfg["account_id"])}</AccountId>'
            f'<Password>{_xml_escape(cfg["password"])}</Password>'
            f'<SecureHash>{secure_hash}</SecureHash>'
            '<SMSList>'
            f'<SenderName>{_xml_escape(cfg["sender"])}</SenderName>'
            f'<ReceiverMSISDN>{receiver}</ReceiverMSISDN>'
            f'<SMSText>{_xml_escape(message)}</SMSText>'
            '</SMSList>'
            f'{trx_xml}'
            '</SubmitSMSRequest>')

        endpoint = "/web2sms/sms/submit/Notification" if cfg['mode'] == "notification" else "/web2sms/sms/submit"

        if not cfg['verify_ssl']:
            try:
                import urllib3
                urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
            except Exception:
                pass

        resp = requests.post(cfg['base_url'] + endpoint, data=xml_body.encode('utf-8'),
                             headers={"Content-Type": "application/xml"},
                             timeout=30, verify=cfg['verify_ssl'])

        try:
            root = ET.fromstring(resp.text)
        except ET.ParseError:
            return False, f"استجابة غير متوقعة من الخادم (HTTP {resp.status_code})", None
        ns = root.tag.split('}')[0] + '}' if root.tag.startswith('{') else ''

        def text_of(tag):
            """يستخرج نص عنصر XML محدد من رد خدمة SMS (أو None لو غير موجود)"""
            el = root.find(f'{ns}{tag}')
            return el.text.strip() if el is not None and el.text else None

        result = text_of('ResultStatus')
        desc = text_of('Description')
        statuses = [el.text.strip() for el in root.findall(f'{ns}SMSStatus') if el.text]

        if result == "SUCCESS" and (not statuses or statuses[0] == "SUBMITTED"):
            return True, "تم الإرسال بنجاح", None

        details = " - ".join(filter(None, [result, statuses[0] if statuses else None,
                                           SMS_ERROR_CODES.get(desc, desc)]))
        return False, details or f"استجابة غير متوقعة من الخادم (HTTP {resp.status_code})", desc

    except requests.exceptions.SSLError as e:
        return False, f"خطأ SSL: تحقق من إعداد 'التحقق من شهادة SSL' - {e}", None
    except requests.exceptions.RequestException as e:
        return False, f"تعذر الاتصال بخادم SMS API: {e}", None
    except Exception as e:
        return False, str(e), None


def send_sms(cfg, phone_number, message, external_trx_id=None):
    """يرسل رسالة واحدة مع إعادة محاولة تلقائية لو فشل الـ hash."""
    global _SMS_HASH_MODE
    ok, details, code = _sms_submit_once(cfg, phone_number, message, external_trx_id, _SMS_HASH_MODE)
    if not ok and code == '9021':
        other = 'ascii' if _SMS_HASH_MODE == 'hex' else 'hex'
        ok2, details2, _c = _sms_submit_once(cfg, phone_number, message, external_trx_id, other)
        if ok2:
            _SMS_HASH_MODE = other
        return ok2, details2
    return ok, details

# ── هوية موحّدة لكل النوافذ المنبثقة: أي Toplevel بدون خلفية صريحة يأخذ خلفية الصفحة الرئيسية ──
_THEME_WINDOW_BG = "#F4F6F9"
_orig_toplevel_init = tk.Toplevel.__init__


def _themed_toplevel_init(self, master=None, cnf={}, **kw):
    """يُطبّق لون خلفية النوافذ الموحد على أي Toplevel جديدة ما لم يُحدَّد لون صراحةً"""
    if not cnf and "bg" not in kw and "background" not in kw:
        kw["bg"] = _THEME_WINDOW_BG
    _orig_toplevel_init(self, master, cnf, **kw)


tk.Toplevel.__init__ = _themed_toplevel_init


def serialize_for_json(obj):
    """محوّل JSON مخصص: يحوّل Decimal إلى float و bytes إلى base64 ويرفض ما عداها"""
    if isinstance(obj, Decimal):
        return float(obj)
    if isinstance(obj, bytes):
        return base64.b64encode(obj).decode('utf-8')
    raise TypeError(f"Object of type {obj.__class__.__name__} is not JSON serializable")


# تعيين مجلد العمل إلى مجلد البرنامج
if getattr(sys, 'frozen', False):
    app_dir = os.path.dirname(sys.executable)
    os.chdir(app_dir)


# ═══════════════════════════════════════════════════════════════════════════════
#  محرّك تكبير/تصغير الواجهة (Zoom) — لكل جهاز على حدة
#  ─ يُضبط من: الإعدادات ← «حجم الواجهة». يُحفظ محلياً في ui_settings.json (وليس في قاعدة البيانات).
#  ─ يُطبَّق عند تشغيل شاشة المبيعات ويشمل كل النوافذ المفتوحة بعدها. يقيس معاً:
#      • الخطوط (tk scaling)               • الإطارات والأزرار والحشوات (padx/pady/width/height/wraplength)
#      • الأيقونات والصور (FontAwesome/PIL) • صفوف الجداول وأعمدتها (Treeview)
#      • أحجام النوافذ (geometry/minsize)   • المكوّنات المخصّصة (RoundedFrame/RoundedButton/ModernButton/...)
#  ─ عند 100% تبقى كل التعديلات معطّلة تماماً (سلوك البرنامج الأصلي دون أي تغيير).
#  ─ ملاحظة: الـ Canvas الخام (مثل مفاتيح التشغيل المرسومة يدوياً) لا يُقاس لأن رسمه بإحداثيات ثابتة.
# ═══════════════════════════════════════════════════════════════════════════════
_BASE_DIR = os.path.dirname(os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__))
UI_PREFS_FILE = os.path.join(_BASE_DIR, "ui_settings.json")   # مسار مطلق: لا يتأثر بمجلد العمل
UI_SCALE_MIN, UI_SCALE_MAX = 50, 150          # حدود النسبة (%)
UI_AUTO_REF_W, UI_AUTO_REF_H = 1366, 768      # الدقة التي صُمّمت عليها الواجهة (= 100%)
_UI_SCALE = 1.0                               # المقياس المطبّق حالياً
_BASE_TK_SCALING = None                       # قيمة tk scaling الأصلية (تُقرأ مرة واحدة فقط في كل تشغيل)
_ZOOM_STATE = {"place": False, "raw": False, "installed": False}
_ZOOM_ORIG = {}
_RawPhotoImage = ImageTk.PhotoImage           # الأصلية (للصور المرسومة بالبكسل الفعلي مثل خلفيات البطاقات)


_ZOOM_DEBUG = False   # اجعلها False بعد حل المشكلة (نافذة تشخيص تظهر مرة واحدة)
_ZOOM_DEBUG_SHOWN = {"v": False}


def _ui_prefs_candidates():
    """كل الأماكن المحتملة لملف الإعدادات (بدون تكرار)."""
    c = [UI_PREFS_FILE]
    try:
        c.append(os.path.join(os.getcwd(), "ui_settings.json"))
    except Exception:
        pass
    appdata = os.environ.get("APPDATA")
    if appdata:
        c.append(os.path.join(appdata, "POSApp", "ui_settings.json"))
    seen, out = set(), []
    for p in c:
        p = os.path.abspath(p)
        if p not in seen:
            seen.add(p)
            out.append(p)
    return out


def load_ui_prefs():
    """يقرأ تفضيلات حجم الواجهة من أحدث ملف موجود: {'mode': 'auto'|'manual', 'percent': 50..150}"""
    prefs = {"mode": "manual", "percent": 100}
    try:
        existing = [p for p in _ui_prefs_candidates() if os.path.exists(p)]
        if existing:
            path = max(existing, key=os.path.getmtime)
            with open(path, "r", encoding="utf-8") as f:
                d = json.load(f)
            if d.get("mode") in ("auto", "manual"):
                prefs["mode"] = d["mode"]
            prefs["percent"] = max(UI_SCALE_MIN, min(UI_SCALE_MAX, int(d.get("percent", 100))))
    except Exception as e:
        print(f"تعذر قراءة ملف حجم الواجهة: {e}")
    return prefs


def save_ui_prefs(mode, percent):
    """يحفظ تفضيلات حجم الواجهة في كل الأماكن المحتملة. يُرجع True إذا تغيّرت القيمة الفعلية."""
    mode = mode if mode in ("auto", "manual") else "manual"
    try:
        percent = max(UI_SCALE_MIN, min(UI_SCALE_MAX, int(float(percent))))
    except (TypeError, ValueError):
        percent = 100
    old = load_ui_prefs()
    saved_any = False
    for p in _ui_prefs_candidates():
        try:
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "w", encoding="utf-8") as f:
                json.dump({"mode": mode, "percent": percent}, f, ensure_ascii=False, indent=2)
            saved_any = True
        except Exception as e:
            print(f"تعذر حفظ {p}: {e}")
    if not saved_any:
        return False
    return old["mode"] != mode or (mode == "manual" and old["percent"] != percent)


def compute_auto_ui_scale(widget):
    """المقياس التلقائي من دقة الشاشة: الأكبر من المرجع = 100%، والأصغر يُصغَّر (حتى 65%)."""
    try:
        f = min(widget.winfo_screenwidth() / float(UI_AUTO_REF_W), widget.winfo_screenheight() / float(UI_AUTO_REF_H))
    except Exception:
        return 1.0
    return round(max(0.65, min(1.0, f)) * 20) / 20.0


def resolve_ui_scale(widget, prefs=None):
    """يحوّل التفضيلات إلى معامل فعلي (مثلاً 0.75)."""
    prefs = prefs or load_ui_prefs()
    if prefs["mode"] == "auto":
        return compute_auto_ui_scale(widget)
    return prefs["percent"] / 100.0


def ui_px(n):
    """يقيس قيمة بالبكسل حسب مقياس الواجهة الحالي (الصفر يبقى صفراً، والموجب لا ينزل عن 1)."""
    if _UI_SCALE == 1.0 or not isinstance(n, (int, float)) or isinstance(n, bool) or n == 0:
        return n
    v = int(round(n * _UI_SCALE))
    return max(1, v) if n > 0 else v


_ZOOM_NUM_RE = re.compile(r"^\s*-?\d+(\.\d+)?(\s+-?\d+(\.\d+)?)*\s*$")
_ZOOM_PX_KEYS = {"padx", "pady", "ipadx", "ipady", "wraplength", "minsize", "pad", "length", "sliderlength",
                 "padding", "bd", "borderwidth"}
_ZOOM_SIZE_WIDGETS = {"frame", "labelframe", "toplevel", "scale", "scrollbar", "ttk::frame", "ttk::labelframe"}
_ZOOM_IMG_WIDGETS = {"label", "button", "checkbutton", "radiobutton", "menubutton"}


def _zoom_value(v):
    """يقيس رقماً أو tuple أو نصاً رقمياً (مثل '10 5'). النصوص ذات الوحدات (2m) تُترك."""
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return ui_px(v)
    if isinstance(v, (tuple, list)):
        return tuple(ui_px(x) if isinstance(x, (int, float)) and not isinstance(x, bool) else x for x in v)
    if isinstance(v, str) and _ZOOM_NUM_RE.match(v):
        return " ".join(str(ui_px(float(t))) for t in v.split())
    return v


def _zoom_has_image(widget, cnf):
    """هل عنصر النص/الزر يحمل صورة؟ (عندها width/height بالبكسل لا بالأحرف)"""
    if cnf.get("image"):
        return True
    try:
        return bool(str(widget.cget("image")))
    except Exception:
        return False


def _zoom_cnf(widget, cnf):
    """يقيس خيارات البكسل في قاموس خيارات عنصر Tk (يُستدعى من Misc._options)."""
    wn = getattr(widget, "widgetName", "") or ""
    place = _ZOOM_STATE["place"]
    out = {}
    for k, v in cnf.items():
        kk = k[:-1] if isinstance(k, str) and k.endswith("_") else k
        if v is not None and isinstance(kk, str):
            if kk in _ZOOM_PX_KEYS:
                v = _zoom_value(v)
            elif place and kk in ("x", "y", "width", "height"):
                v = _zoom_value(v)
            elif not place and kk in ("width", "height"):
                if wn in _ZOOM_SIZE_WIDGETS or (wn in _ZOOM_IMG_WIDGETS and _zoom_has_image(widget, cnf)):
                    v = _zoom_value(v)
        out[k] = v
    return out


def _zoom_geometry_str(win, g):
    """يقيس عرض/ارتفاع سلسلة geometry، ويبقي النافذة كاملة داخل الشاشة ومتوسّطة (حتى لو كان حجمها الأصلي أكبر من الشاشة)."""
    m = re.fullmatch(r"\s*=?\s*(\d+)x(\d+)(?:([+-])(-?\d+)([+-])(-?\d+))?\s*", g)
    if not m:
        return g
    W, H, s = int(m.group(1)), int(m.group(2)), _UI_SCALE
    try:
        sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
    except Exception:
        sw, sh = 10000, 10000
    try:
        rw, rh = win.winfo_reqwidth(), win.winfo_reqheight()
    except Exception:
        rw = rh = 0
    nw, nh = W, H
    if s != 1.0 and not (abs(W - rw) <= 2 and abs(H - rh) <= 2):   # غير المأخوذ أصلاً من محتوى النافذة
        # البعد الذي يملأ الشاشة (>= 80%) يبقى كما هو لأنه محسوب من الشاشة نفسها لا من التصميم
        nw = W if W >= 0.8 * sw else int(round(W * s))
        nh = H if H >= 0.8 * sh else int(round(H * s))
        if s < 1:                                                    # لا تصغّر أقل مما يحتاجه المحتوى
            nw, nh = max(nw, min(W, rw)), max(nh, min(H, rh))
    nw, nh = min(nw, max(sw - 20, 200)), min(nh, max(sh - 60, 200))
    if m.group(3) is None:
        return f"{nw}x{nh}"
    x, y = int(m.group(4)), int(m.group(6))
    if m.group(3) == "+":
        x = max(0, min(x - (nw - W) // 2, sw - nw))
    if m.group(5) == "+":
        y = max(0, min(y - (nh - H) // 2, sh - nh - 40))
    return f"{nw}x{nh}{m.group(3)}{x}{m.group(5)}{y}"


def raw_configure(widget, **kw):
    """configure بالبكسل الفعلي دون قياس (للقيم المحسوبة من winfo_*)."""
    prev = _ZOOM_STATE["raw"]
    _ZOOM_STATE["raw"] = True
    try:
        return widget.configure(**kw)
    finally:
        _ZOOM_STATE["raw"] = prev


def raw_place(widget, **kw):
    """place بالبكسل الفعلي دون قياس (للإحداثيات المحسوبة من winfo_*)."""
    prev = _ZOOM_STATE["raw"]
    _ZOOM_STATE["raw"] = True
    try:
        return widget.place(**kw)
    finally:
        _ZOOM_STATE["raw"] = prev


def _zoom_postfit(win, orig_geom):
    """بعد بناء النافذة: إن كان محتواها أكبر من حجمها يُوسَّع (حتى حدود الشاشة) ويُبقى داخل الشاشة."""
    try:
        if not win.winfo_exists() or win.master is None or win.state() in ("zoomed", "iconic", "withdrawn"):
            return
        win.update_idletasks()
        w, h = win.winfo_width(), win.winfo_height()
        rw, rh = win.winfo_reqwidth(), win.winfo_reqheight()
        wx, wy, sw, sh = get_work_area(win)
        nw, nh = min(max(w, rw), sw - 20), min(max(h, rh), sh - 45)
        x, y = win.winfo_x(), win.winfo_y()
        nx = max(wx, min(x - (nw - w) // 2, wx + sw - nw))
        ny = max(wy, min(y, wy + sh - nh - 40))
        if nw > w + 3 or nh > h + 3 or nx != x or ny != y:
            orig_geom(win, f"{nw}x{nh}+{nx}+{ny}")
    except Exception:
        pass
    finally:
        try:
            win._zoom_postfit_pending = False
        except Exception:
            pass


def get_work_area(win=None):
    """المساحة المتاحة فعلياً للنوافذ (x, y, w, h) بدون شريط المهام. تعود لأبعاد الشاشة كاملة إن تعذّر."""
    try:
        import ctypes
        from ctypes import wintypes
        r = wintypes.RECT()
        if ctypes.windll.user32.SystemParametersInfoW(48, 0, ctypes.byref(r), 0):   # SPI_GETWORKAREA
            return r.left, r.top, r.right - r.left, r.bottom - r.top
    except Exception:
        pass
    try:
        return 0, 0, win.winfo_screenwidth(), win.winfo_screenheight() - 48
    except Exception:
        return 0, 0, 1366, 720


def raw_geometry(win, g):
    """يضبط geometry بالبكسل الفعلي دون قياس (للقيم المأخوذة من winfo)."""
    orig = _ZOOM_ORIG.get("wm_geometry")
    return orig(win, g) if orig else win.geometry(g)


def _zoom_install():
    """يركّب تعديلات القياس مرة واحدة على tkinter / ttk / PIL / FontAwesome (كلها لا تفعل شيئاً عند 100%)."""
    if _ZOOM_STATE["installed"]:
        return
    _ZOOM_STATE["installed"] = True

    # 1) خيارات البكسل لكل العناصر ولمديري التخطيط (pack/grid/place)
    orig_opts = tk.Misc._options

    def _opts(self, cnf, kw=None):
        if _UI_SCALE != 1.0 and not _ZOOM_STATE["raw"]:
            try:
                merged = tk._cnfmerge((cnf, kw)) if kw else tk._cnfmerge(cnf)
                cnf, kw = _zoom_cnf(self, merged), None
            except Exception:
                pass
        return orig_opts(self, cnf, kw)

    tk.Misc._options = _opts

    orig_place = tk.Place.place_configure

    def _place(self, cnf={}, **kw):
        prev = _ZOOM_STATE["place"]
        _ZOOM_STATE["place"] = True
        try:
            return orig_place(self, cnf, **kw)
        finally:
            _ZOOM_STATE["place"] = prev

    tk.Place.place_configure = _place
    tk.Place.place = _place

    # 2) أحجام النوافذ
    orig_geom = tk.Wm.wm_geometry
    _ZOOM_ORIG["wm_geometry"] = orig_geom

    def _geom(self, newGeometry=None):
        if newGeometry and not _ZOOM_STATE["raw"]:
            try:
                newGeometry = _zoom_geometry_str(self, newGeometry)
            except Exception:
                pass
            if _UI_SCALE != 1.0 and getattr(self, "master", None) is not None \
                    and not getattr(self, "_zoom_postfit_pending", False):
                try:
                    self._zoom_postfit_pending = True
                    self.after(250, lambda w=self: _zoom_postfit(w, orig_geom))
                except Exception:
                    self._zoom_postfit_pending = False
        return orig_geom(self, newGeometry)

    tk.Wm.wm_geometry = _geom
    tk.Wm.geometry = _geom

    orig_min = tk.Wm.wm_minsize

    def _minsize(self, width=None, height=None):
        if _UI_SCALE != 1.0:
            width, height = ui_px(width), ui_px(height)
        return orig_min(self, width, height)

    tk.Wm.wm_minsize = _minsize
    tk.Wm.minsize = _minsize

    # 3) ttk: ارتفاع الصفوف والحشوات + عرض أعمدة الجداول
    orig_cfg = ttk.Style.configure

    def _style_cfg(self, style, query_opt=None, **kw):
        if _UI_SCALE != 1.0:
            if isinstance(kw.get("rowheight"), (int, float)):
                kw["rowheight"] = max(16, ui_px(kw["rowheight"]))
            if "padding" in kw:
                kw["padding"] = _zoom_value(kw["padding"])
        return orig_cfg(self, style, query_opt, **kw)

    ttk.Style.configure = _style_cfg

    orig_col = ttk.Treeview.column

    def _tree_col(self, column, option=None, **kw):
        if _UI_SCALE != 1.0:
            for k in ("width", "minwidth"):
                if isinstance(kw.get(k), (int, float)):
                    kw[k] = ui_px(kw[k])
        return orig_col(self, column, option, **kw)

    ttk.Treeview.column = _tree_col

    # 4) الصور (PIL) والأيقونات (FontAwesome)
    class _ZoomPhotoImage(_RawPhotoImage):
        def __init__(self, image=None, size=None, **kw):
            if _UI_SCALE != 1.0 and image is not None and size is None \
                    and hasattr(image, "resize") and hasattr(image, "size"):
                try:
                    w, h = image.size
                    image = image.resize((max(1, int(round(w * _UI_SCALE))), max(1, int(round(h * _UI_SCALE)))),
                                         Image.LANCZOS)
                except Exception:
                    pass
            super().__init__(image, size, **kw)

    ImageTk.PhotoImage = _ZoomPhotoImage

    orig_icon = tkfa.icon_to_image

    def _icon(name, fill=None, scale_to_width=None, scale_to_height=None, scale=1):
        if _UI_SCALE != 1.0:
            if scale_to_width:
                scale_to_width = max(1, int(round(scale_to_width * _UI_SCALE)))
            if scale_to_height:
                scale_to_height = max(1, int(round(scale_to_height * _UI_SCALE)))
            if not scale_to_width and not scale_to_height:
                scale = scale * _UI_SCALE
        return orig_icon(name, fill, scale_to_width, scale_to_height, scale)

    tkfa.icon_to_image = _icon


def apply_ui_scale(root, factor):
    """يطبّق مقياس الواجهة: الخطوط عبر tk scaling + تفعيل قياس الأبعاد والصور والنوافذ."""
    global _UI_SCALE, _BASE_TK_SCALING
    requested = factor
    factor = max(UI_SCALE_MIN / 100.0, min(UI_SCALE_MAX / 100.0, float(factor)))
    _ZOOM_STATE["raw"] = False
    _ZOOM_STATE["place"] = False
    err = ""
    try:
        if _BASE_TK_SCALING is None:      # مرة واحدة فقط: يمنع تضاعف المقياس عند فتح Toplevel جديد
            _BASE_TK_SCALING = float(root.tk.call("tk", "scaling"))
        root.tk.call("tk", "scaling", _BASE_TK_SCALING * factor)
        _zoom_install()
    except Exception as e:
        import traceback
        traceback.print_exc()
        err = f"\nخطأ: {e}"
        factor = 1.0
    _UI_SCALE = factor

    info = (f"requested={requested}\napplied={factor}\nbase_tk_scaling={_BASE_TK_SCALING}\n"
            f"prefs={load_ui_prefs()}\nfrozen={getattr(sys, 'frozen', False)}\n"
            f"__file__={os.path.abspath(__file__)}\ncwd={os.getcwd()}\n"
            f"files={[(p, os.path.exists(p)) for p in _ui_prefs_candidates()]}{err}")
    print("[ZOOM]", info)
    if _ZOOM_DEBUG and not _ZOOM_DEBUG_SHOWN["v"]:
        _ZOOM_DEBUG_SHOWN["v"] = True
        try:
            import ctypes
            ctypes.windll.user32.MessageBoxW(0, info, "ZOOM DEBUG", 0x40)
        except Exception:
            pass
    return factor

# ═══════════════════════════════════════════════════════════════════════════════
#  مكوّنات واجهة حديثة (Modern Light Flat / Material-like)
#  - RoundedFrame : بطاقة بزوايا مدوّرة وظل ناعم (بدل tk.Frame المربع)
#  - RoundedButton: زر مدوّر مع أيقونة وهوفر
#  - CartList     : قائمة الفاتورة كبطاقات (بأزرار + / − / حذف حقيقية) وبنفس واجهة ttk.Treeview
#                   حتى لا يتغير أي كود يتعامل مع self.product_list
# ═══════════════════════════════════════════════════════════════════════════════
import tkinter.font as _tkfont
from PIL import ImageFilter as _ImageFilter

_UI_IMG_CACHE = {}

# ── مفاتيح التحكم في الشكل ──
# _FLAT_BUTTONS = True  : كل الأزرار والشرائح وأزرار + / − / حذف مسطحة (زوايا حادة، بدون ظل) مثل الصفحة الرئيسية
# _FLAT_CARDS   = False : البطاقات الكبيرة تبقى بزوايا ناعمة وظل خفيف. اجعلها True لتسطيحها هي أيضاً.
_FLAT_BUTTONS = True
_FLAT_CARDS = False


def _hex_rgb(h):
    """يحوّل لوناً بصيغة #RRGGBB إلى tuple من ثلاث قيم (R, G, B)"""
    h = h.lstrip('#')
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def _card_image(w, h, radius=14, fill="#FFFFFF", outline="#E2E8F0", shadow=True, pad=5, ow=1):
    """يرسم بطاقة مدوّرة (مع ظل ناعم اختياري) بجودة عالية (supersampling) ويُرجع PhotoImage مخزّنة."""
    w, h = max(int(w), 4), max(int(h), 4)
    key = ("card", w, h, radius, fill, outline, shadow, pad, ow)
    cached = _UI_IMG_CACHE.get(key)
    if cached is not None:
        return cached
    S = 3
    W, H = w * S, h * S
    layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    bottom_extra = 2 if shadow else 0
    box = (pad * S, pad * S, (w - pad) * S - 1, (h - pad - bottom_extra) * S - 1)
    if box[2] - box[0] < 4 * S or box[3] - box[1] < 4 * S:
        photo = _RawPhotoImage(Image.new("RGBA", (w, h), (0, 0, 0, 0)))
        _UI_IMG_CACHE[key] = photo
        return photo
    r = min(radius * S, (box[2] - box[0]) // 2, (box[3] - box[1]) // 2)
    if shadow:
        sh = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        ImageDraw.Draw(sh).rounded_rectangle((box[0], box[1] + 2 * S, box[2], box[3] + 2 * S), r,
                                             fill=(15, 23, 42, 30))
        sh = sh.filter(_ImageFilter.GaussianBlur(3 * S))
        layer = Image.alpha_composite(layer, sh)
    d = ImageDraw.Draw(layer)
    if outline:
        d.rounded_rectangle(box, r, fill=_hex_rgb(outline) + (255,))
        d.rounded_rectangle((box[0] + ow * S, box[1] + ow * S, box[2] - ow * S, box[3] - ow * S), max(r - ow * S, 1),
                            fill=_hex_rgb(fill) + (255,))
    else:
        d.rounded_rectangle(box, r, fill=_hex_rgb(fill) + (255,))
    photo = _RawPhotoImage(layer.resize((w, h), Image.LANCZOS))
    _UI_IMG_CACHE[key] = photo
    return photo


def _glyph_image(kind, size=30, fg="#3B82F6", bg="#EFF6FF"):
    """أيقونات دائرية صغيرة مرسومة بالكود (+ / − / سلة / مربع منتج) بدون أي اعتماد خارجي."""
    key = ("glyph", kind, size, fg, bg)
    cached = _UI_IMG_CACHE.get(key)
    if cached is not None:
        return cached
    S = 4
    N = size * S
    im = Image.new("RGBA", (N, N), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    if bg:
        if kind in ("box", "grid", "check_on", "check_off"):
            d.rounded_rectangle((0, 0, N - 1, N - 1), int(N * 0.22), fill=_hex_rgb(bg) + (255,))
        elif _FLAT_BUTTONS:
            d.rectangle((0, 0, N - 1, N - 1), fill=_hex_rgb(bg) + (255,))   # زر مسطح مربع
        else:
            d.ellipse((0, 0, N - 1, N - 1), fill=_hex_rgb(bg) + (255,))
    c = _hex_rgb(fg) + (255,)
    m = N // 2
    lw = max(int(N * 0.085), 2)
    a = int(N * 0.26)
    if kind == "plus":
        d.line((m - a, m, m + a, m), fill=c, width=lw)
        d.line((m, m - a, m, m + a), fill=c, width=lw)
    elif kind == "minus":
        d.line((m - a, m, m + a, m), fill=c, width=lw)
    elif kind == "trash":
        top = int(N * 0.30)
        d.line((int(N * 0.27), top, int(N * 0.73), top), fill=c, width=lw)
        d.line((int(N * 0.42), top, int(N * 0.42), int(N * 0.24)), fill=c, width=lw)
        d.line((int(N * 0.58), top, int(N * 0.58), int(N * 0.24)), fill=c, width=lw)
        d.line((int(N * 0.42), int(N * 0.24), int(N * 0.58), int(N * 0.24)), fill=c, width=lw)
        d.rounded_rectangle((int(N * 0.32), top + lw, int(N * 0.68), int(N * 0.74)), int(N * 0.05),
                            outline=c, width=lw)
        d.line((int(N * 0.45), int(N * 0.44), int(N * 0.45), int(N * 0.64)), fill=c, width=max(lw - 2, 2))
        d.line((int(N * 0.55), int(N * 0.44), int(N * 0.55), int(N * 0.64)), fill=c, width=max(lw - 2, 2))
    elif kind == "box":
        # مكعب بسيط كصورة افتراضية للمنتج
        cx, cy, s = m, m, int(N * 0.26)
        top = [(cx, cy - s), (cx + s, cy - s // 2), (cx, cy), (cx - s, cy - s // 2)]
        left = [(cx - s, cy - s // 2), (cx, cy), (cx, cy + s), (cx - s, cy + s // 2)]
        right = [(cx + s, cy - s // 2), (cx, cy), (cx, cy + s), (cx + s, cy + s // 2)]
        d.polygon(top, outline=c, width=lw)
        d.polygon(left, outline=c, width=lw)
        d.polygon(right, outline=c, width=lw)
    elif kind == "move":
        # سهمان متعاكسان (⇄) = نقل
        ya, yb = int(N * 0.38), int(N * 0.62)
        x0, x1 = int(N * 0.24), int(N * 0.76)
        hd = int(N * 0.10)
        d.line((x0, ya, x1, ya), fill=c, width=lw)
        d.polygon([(x1, ya - hd), (x1 + hd, ya), (x1, ya + hd)], fill=c)
        d.line((x0, yb, x1, yb), fill=c, width=lw)
        d.polygon([(x0, yb - hd), (x0 - hd, yb), (x0, yb + hd)], fill=c)
    elif kind == "check_off":
        # مربع تشيك بوكس فارغ (الحد بلون fg)
        d.rounded_rectangle((int(N * 0.04), int(N * 0.04), int(N * 0.96), int(N * 0.96)), int(N * 0.2),
                            outline=c, width=max(int(N * 0.08), 2))
    elif kind == "check_on":
        # تشيك بوكس مفعّل: علامة ✓
        d.line((int(N * 0.24), int(N * 0.52), int(N * 0.43), int(N * 0.70)), fill=c, width=lw + 2)
        d.line((int(N * 0.43), int(N * 0.70), int(N * 0.77), int(N * 0.30)), fill=c, width=lw + 2)
    elif kind == "close":
        a2 = int(N * 0.19)
        d.line((m - a2, m - a2, m + a2, m + a2), fill=c, width=lw)
        d.line((m - a2, m + a2, m + a2, m - a2), fill=c, width=lw)
    elif kind == "grid":
        sq, gp = int(N * 0.15), int(N * 0.05)
        for gx in (-1, 1):
            for gy in (-1, 1):
                x0 = m + gp if gx > 0 else m - gp - sq
                y0 = m + gp if gy > 0 else m - gp - sq
                d.rounded_rectangle((x0, y0, x0 + sq, y0 + sq), int(sq * 0.3), fill=c)
    photo = ImageTk.PhotoImage(im.resize((size, size), Image.LANCZOS))
    _UI_IMG_CACHE[key] = photo
    return photo


class RoundedFrame(tk.Canvas):
    """بطاقة بزوايا مدوّرة وظل ناعم. ضع المحتوى داخل  .inner
    fit=True  : ارتفاع البطاقة يتبع ارتفاع محتواها تلقائياً.
    fit=False : البطاقة تملأ المساحة المعطاة لها (أو الحجم الثابت width/height)."""

    def __init__(self, master, fill="#FFFFFF", outline="#E2E8F0", radius=14, shadow=True, pad=4,
                 padding=(12, 8), fit=True, width=None, height=None, canvas_bg=None, outline_w=1,
                 top_extra=0):
        """ينشئ إطاراً بزوايا مدورة وظل وحد، مع إطار داخلي (inner) يوضع فيه المحتوى"""
        if _FLAT_CARDS:
            shadow, radius = False, 0
        radius, pad, top_extra = ui_px(radius), ui_px(pad), ui_px(top_extra)
        width = ui_px(width) if width is not None else None
        height = ui_px(height) if height is not None else None
        self._ow = outline_w
        self._top_extra = top_extra
        self._legend = None
        try:
            parent_bg = canvas_bg or master.cget("bg")
        except tk.TclError:
            parent_bg = "#F4F6F9"
        kw = {}
        if width is not None:
            kw["width"] = width
        if height is not None:
            kw["height"] = height
        elif fit:
            # الارتفاع المبدئي يجب أن يتجاوز موضع المحتوى الداخلي وإلا لا يظهر ولا يكبر الإطار تلقائياً
            kw["height"] = 2 * (pad + int(radius * 0.3) + 1 + top_extra) + ui_px(14)
        super().__init__(master, bg=parent_bg, highlightthickness=0, bd=0, **kw)
        self._no_scroll = True  # لا يشارك في التمرير بعجلة الماوس
        self._fill, self._outline = fill, outline
        self._radius, self._shadow, self._pad = radius, shadow, pad
        self._ix = pad + int(radius * 0.3) + 2
        self._iy = pad + int(radius * 0.3) + 1 + top_extra
        self._fit = fit and height is None
        self._photo = None
        self._size = (0, 0)
        self.inner = tk.Frame(self, bg=fill, padx=padding[0], pady=padding[1])
        self._img_item = self.create_image(0, 0, anchor="nw")
        self._inner_win = self.create_window(self._ix, self._iy, window=self.inner, anchor="nw")
        self.bind("<Configure>", self._on_resize)
        if self._fit:
            self.inner.bind("<Configure>", self._on_inner)

    def _on_inner(self, e):
        """يضبط ارتفاع الإطار تلقائياً ليناسب محتواه الداخلي"""
        need = e.height + 2 * self._iy - self._top_extra + (2 if self._shadow else 0)
        try:
            if abs(int(float(self.cget("height"))) - need) > 1:
                self.configure(height=need)
        except tk.TclError:
            pass

    def _on_resize(self, e):
        """عند تغيّر الحجم: يعدّل عرض (وارتفاع) الإطار الداخلي ويعيد الرسم"""
        w, h = e.width, e.height
        if w < 8 or h < 8:
            return
        opts = {"width": max(w - 2 * self._ix, 1)}
        if not self._fit:
            opts["height"] = max(h - 2 * self._iy - (2 if self._shadow else 0), 1)
        self.itemconfigure(self._inner_win, **opts)
        self._size = (w, h)
        self._redraw()

    def _redraw(self):
        """يعيد رسم صورة الخلفية المدورة (الظل + الحد + التعبئة) وعنوان الإطار"""
        w, h = self._size
        if w < 8 or h < 8:
            return
        self._photo = _card_image(w, h, self._radius, self._fill, self._outline, self._shadow, self._pad, self._ow)
        self.itemconfigure(self._img_item, image=self._photo)
        self.tag_lower(self._img_item)
        self._draw_legend()

    def set_legend(self, text, color=None, font=None):
        """نص وصفي يُرسم على الحافة العلوية للإطار (يقطع الخط خلفه) بلون الإطار."""
        self._legend = (text, color or self._outline, font or ("Segoe UI", 10, "bold"))
        self._draw_legend()

    def _draw_legend(self):
        """يرسم عنوان الإطار (legend) فوق الحد العلوي بخلفية تخفي الخط خلفه"""
        self.delete("legend")
        lg = self._legend
        if not lg or not lg[0]:
            return
        w, h = self._size
        if w < 60:
            return
        text, color, font = lg
        try:
            tw = _tkfont.Font(font=font).measure(text)
        except tk.TclError:
            return
        cy = self._pad + self._ow / 2.0
        x2 = w - self._pad - self._radius - ui_px(8)
        x1 = x2 - tw - ui_px(18)
        self.create_rectangle(x1, self._pad - 1, x2, self._pad + self._ow + 1,
                              fill=self._fill, outline=self._fill, tags="legend")
        self.create_text(x2 - ui_px(9), cy, text=text, anchor="e", fill=color, font=font, tags="legend")
        self.tag_lower(self._img_item)

    def recolor(self, fill=None, outline=None):
        """تغيير لون البطاقة (للهوفر/التحديد) مع تحويل خلفيات العناصر الداخلية التي تحمل نفس اللون."""
        old = self._fill
        if outline:
            self._outline = outline
        if fill and fill.lower() != old.lower():
            self._fill = fill
            self._recolor_children(self.inner, old, fill)
        self._redraw()

    def _recolor_children(self, widget, old, new):
        """يغيّر لون خلفية كل العناصر الأبناء من اللون القديم إلى الجديد (تكرارياً)"""
        try:
            if str(widget.cget("bg")).lower() == old.lower():
                widget.configure(bg=new)
        except tk.TclError:
            pass
        for ch in widget.winfo_children():
            self._recolor_children(ch, old, new)


class RoundedButton(tk.Canvas):
    """زر مدوّر مسطح: نص + أيقونة اختيارية (على اليمين)، هوفر، وحالة مختارة."""

    def __init__(self, master, text="", command=None, bg="#3B82F6", hover="#2563EB", fg="white",
                 outline=None, hover_outline=None, hover_fg=None, icon=None, height=44, radius=12,
                 padx=18, min_width=0, font=("Segoe UI", 12, "bold"), canvas_bg=None, gap=8):
        """ينشئ زراً مدور الزوايا على Canvas بنص وأيقونة اختيارية وألوان hover"""
        height, radius, padx = ui_px(height), ui_px(radius), ui_px(padx)
        min_width, gap = ui_px(min_width), ui_px(gap)
        try:
            parent_bg = canvas_bg or master.cget("bg")
        except tk.TclError:
            parent_bg = "#FFFFFF"
        self._font = _tkfont.Font(font=font)
        self._text, self._icon, self._gap = text, icon, gap
        self._padx, self._min_w, self._compact = padx, min_width, False
        self._icon_w = icon.width() if icon else 0
        tw = self._font.measure(text) if text else 0
        iw = (icon.width() + (gap if text else 0)) if icon else 0
        self._req_w = max(min_width, padx * 2 + tw + iw)
        super().__init__(master, width=self._req_w, height=height, bg=parent_bg,
                         highlightthickness=0, bd=0, cursor="hand2")
        self._no_scroll = True
        self._cmd = command
        self._radius = 0 if _FLAT_BUTTONS else radius
        self._style = dict(bg=bg, hover=hover, fg=fg, outline=outline, hover_outline=hover_outline or outline,
                           hover_fg=hover_fg or fg)
        self._bhovering = False
        self._tw, self._iw = tw, iw
        self._img_item = self.create_image(0, 0, anchor="nw")
        self._txt_item = self.create_text(0, 0, text=text, font=font, anchor="w", fill=fg)
        self._icon_item = self.create_image(0, 0, anchor="w", image=icon) if icon else None
        # قياس العرض الفعلي للنص كما يرسمه Tk (bbox) بدل Font.measure: يمنع تداخل الأيقونة مع النص
        _rw = self._real_text_w() if text else 0
        if _rw and _rw != tw:
            self._tw = _rw
            self._req_w = max(min_width, padx * 2 + _rw + iw)
            self.configure(width=self._req_w)
        self._tw_full = self._tw      # عرض النص الكامل (يُستعمل لمعرفة العرض عند إرجاع النص)
        self.bind("<Configure>", lambda e: self._draw(e.width, e.height))
        self.bind("<Enter>", lambda e: self._set_hover(True))
        self.bind("<Leave>", lambda e: self._set_hover(False))
        self.bind("<ButtonRelease-1>", self._on_click)
        self._bw, self._bh = self._req_w, height

    def _real_text_w(self):
        """عرض النص الفعلي كما يرسمه Tk (من bbox عنصر النص)؛ يرجع القيمة المحسوبة سابقاً عند الفشل"""
        try:
            bb = self.bbox(self._txt_item)
            if bb and bb[2] > bb[0]:
                return bb[2] - bb[0]
        except tk.TclError:
            pass
        return self._tw

    def full_width(self):
        """العرض المطلوب والنص ظاهر (حتى لو كان الزر حالياً أيقونة فقط)"""
        gap = self._gap if self._text else 0
        return max(self._min_w, self._padx * 2 + self._tw_full + gap + self._icon_w)

    def set_compact(self, flag):
        """True = أيقونة فقط (يُخفى النص ويضيق الزر)، False = يرجع النص والعرض الكامل"""
        flag = bool(flag) and bool(self._icon) and bool(self._text)
        if flag == self._compact:
            return
        self._compact = flag
        self.itemconfigure(self._txt_item, state="hidden" if flag else "normal")
        if flag:
            self._req_w = max(self._bh, self._padx * 2 + self._icon_w)
        else:
            self._req_w = self.full_width()
        self.configure(width=self._req_w)
        self._draw(self._bw, self._bh)

    def _set_hover(self, v):
        """يضبط حالة مرور الماوس على الزر ويعيد رسمه"""
        self._bhovering = v
        self._draw(self._bw, self._bh)

    def _on_click(self, e):
        """ينفّذ أمر الزر عند الضغط إذا كان المؤشر داخل حدوده"""
        if 0 <= e.x <= self.winfo_width() and 0 <= e.y <= self.winfo_height() and self._cmd:
            self._cmd()

    def set_style(self, **kw):
        """يحدّث ألوان/تنسيق الزر ويعيد رسمه"""
        self._style.update(kw)
        self._draw(self._bw, self._bh)

    def set_text(self, text):
        """يغيّر نص الزر"""
        self._text = text
        self.itemconfigure(self._txt_item, text=text)
        self._draw(self._bw, self._bh)

    def _draw(self, w, h):
        """يرسم خلفية الزر والحد والنص والأيقونة حسب حالة الماوس والتنسيق"""
        if w < 6 or h < 6:
            return
        self._bw, self._bh = w, h
        st = self._style
        fill = st["hover"] if self._bhovering else st["bg"]
        outline = (st["hover_outline"] if self._bhovering else st["outline"])
        fg = st["hover_fg"] if self._bhovering else st["fg"]
        self._img = _card_image(w, h, self._radius, fill, outline, shadow=False, pad=0)
        self.itemconfigure(self._img_item, image=self._img)
        show_txt = bool(self._text) and not self._compact
        tw = self._real_text_w() if show_txt else 0         # العرض الفعلي المرسوم (لا المحسوب مسبقاً)
        if show_txt:
            self._tw = self._tw_full = tw
        gap = self._gap if show_txt else 0
        group_w = tw + gap + self._icon_w
        x0 = max((w - group_w) // 2, 4)
        self.coords(self._txt_item, x0, h // 2)
        self.itemconfigure(self._txt_item, fill=fg)
        if self._icon_item:
            self.coords(self._icon_item, x0 + tw + gap, h // 2)
        self.tag_lower(self._img_item)


# ═══════════════════════════════════════════════════════════════════════════════
#  طبقة التصميم الموحّدة للنوافذ (Material / Flutter-like)
#  - ModernButton     : بديل مباشر لـ tk.Button (مدوّر + هوفر + ضغط) بنفس أوامره
#  - ModernLabelFrame : بديل لـ tk.LabelFrame / ttk.LabelFrame (بطاقة بعنوان)
#  - نوافذ الرسائل    : بديل لـ messagebox (أيقونة ملوّنة + أزرار مدوّرة)
# ═══════════════════════════════════════════════════════════════════════════════
_T = dict(bg="#F4F6F9", card="#FFFFFF", accent="#3B82F6", accent_hover="#2563EB", tint="#EFF6FF",
          dark="#1E293B", muted="#64748B", border="#E2E8F0", input="#F1F5F9",
          success="#10B981", warning="#F59E0B", danger="#EF4444", danger_bg="#FEE2E2",
          warning_bg="#FEF3C7", font="Segoe UI")


def _norm_color(widget, c, default="#FFFFFF"):
    """يحوّل أي لون (اسم أو hex) إلى #RRGGBB."""
    if not c:
        return default
    c = str(c)
    if len(c) == 7 and c[0] == "#":
        return c.upper()
    try:
        r, g, b = widget.winfo_rgb(c)
        return "#%02X%02X%02X" % (r >> 8, g >> 8, b >> 8)
    except tk.TclError:
        return default


def _shade(color, f):
    """f<1 أغمق، f>1 أفتح. الألوان الداكنة جداً تُفتَّح قليلاً بدل التغميق."""
    r, g, b = _hex_rgb(color)
    h, l, s = colorsys.rgb_to_hls(r / 255, g / 255, b / 255)
    l = l * f if (f > 1 or l > 0.2) else min(1.0, l + 0.08)
    r, g, b = colorsys.hls_to_rgb(h, max(0.0, min(1.0, l)), s)
    return "#%02X%02X%02X" % (int(r * 255), int(g * 255), int(b * 255))


def _mix(c1, c2, t):
    """يمزج لونين بنسبة t (0 = الأول، 1 = الثاني) ويرجع اللون الناتج"""
    a, b = _hex_rgb(c1), _hex_rgb(c2)
    return "#%02X%02X%02X" % tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


class ModernButton(tk.Canvas):
    """بديل مباشر لـ tk.Button: زر مدوّر مسطح بهوفر وضغط، يقبل نفس الخيارات والأوامر
    (text, command, bg, fg, font, image, compound, width, height, state, activebackground ...)
    و config/cget/invoke، فلا يحتاج الكود القديم لأي تغيير."""

    _IGNORED = {"relief", "bd", "borderwidth", "highlightthickness", "highlightbackground", "highlightcolor",
                "takefocus", "overrelief", "underline", "default", "bitmap", "repeatdelay", "repeatinterval",
                "offrelief", "selectcolor", "indicatoron", "name", "class_"}
    _ALIAS = {"background": "bg", "foreground": "fg"}
    _bound_tk = None

    def __init__(self, master=None, cnf=None, **kw):
        """ينشئ زراً عصرياً مرسوماً على Canvas ويتصرف مثل tk.Button (نفس الخيارات والأحداث)"""
        opts = dict(cnf or {})
        opts.update(kw)
        try:
            parent_bg = master.cget("bg")
        except Exception:
            parent_bg = _T["card"]
        fam = _tkfont.nametofont("TkDefaultFont").actual("family")
        self._o = dict(text="", textvariable=None, command=None, bg=_T["input"], fg=_T["dark"],
                       font=(fam, 10, "bold"), image=None, compound="none", width=0, height=0, state="normal",
                       activebackground=None, activeforeground=None, disabledforeground=None, padx=None,
                       pady=None, anchor="center", wraplength=0, justify="center")
        cursor = opts.pop("cursor", "hand2") or "hand2"
        super().__init__(master, bg=parent_bg, highlightthickness=0, bd=0, width=1, height=1, cursor=cursor)
        self._no_scroll = True
        self._hover = False
        self._pressed = False
        self._var = None
        self._var_id = None
        self._bg_photo = None
        self._font = self._make_font()
        self._bg_item = self.create_image(0, 0, anchor="nw")
        self._img_item = self.create_image(0, 0, anchor="center")
        self._txt_item = self.create_text(0, 0, anchor="center")
        # ربط الأحداث عبر bindtag مستقل حتى لا تلغيها أي bind() يضعها الكود الخارجي
        self.bindtags(tuple(self.bindtags()) + ("ModernButtonTag",))
        if ModernButton._bound_tk is not self.tk:
            ModernButton._bound_tk = self.tk
            b = self.bind_class
            b("ModernButtonTag", "<Enter>", lambda e: e.widget._set_state_flag("_hover", True))
            b("ModernButtonTag", "<Leave>", lambda e: e.widget._set_state_flag("_hover", False))
            b("ModernButtonTag", "<ButtonPress-1>", lambda e: e.widget._set_state_flag("_pressed", True))
            b("ModernButtonTag", "<ButtonRelease-1>", lambda e: e.widget._on_release(e))
            b("ModernButtonTag", "<space>", lambda e: e.widget.invoke())
            b("ModernButtonTag", "<Configure>", lambda e: e.widget._draw(e.width, e.height))
        self.configure(opts)

    # ───────── مساعدات ─────────
    def _make_font(self):
        """ينشئ كائن الخط المستخدم للزر مع خط بديل عند الخطأ"""
        try:
            return _tkfont.Font(font=self._o["font"])
        except tk.TclError:
            return _tkfont.nametofont("TkDefaultFont")

    def _set_state_flag(self, name, value):
        """يضبط علماً داخلياً (مثل الضغط/المرور) ويعيد رسم الزر"""
        setattr(self, name, value)
        if name == "_pressed" and not value:
            pass
        self._draw()

    def _on_release(self, e):
        """عند رفع زر الماوس: ينفّذ الأمر فقط لو ما زال المؤشر داخل الزر"""
        was = self._pressed
        self._pressed = False
        self._draw()
        if was and 0 <= e.x < self.winfo_width() and 0 <= e.y < self.winfo_height():
            self._click()

    def _click(self):
        """ينفّذ أمر الزر ما لم يكن معطّلاً ويرجع نتيجته"""
        if str(self._o["state"]) == "disabled":
            return None
        cmd = self._o["command"]
        return cmd() if cmd else None

    def invoke(self):
        """يشغّل الزر برمجياً (مثل invoke في tk.Button)"""
        return self._click()

    def flash(self):
        """دالة توافق مع tk.Button (لا تفعل شيئاً)"""
        return None

    def _sync_var(self, *a):
        """يزامن نص الزر مع StringVar المرتبط عند تغيّره"""
        try:
            self._o["text"] = self._var.get()
        except Exception:
            return
        self._recalc()
        self._draw()

    def _recalc(self):
        """يحسب أبعاد الزر المطلوبة من النص والصورة والحشوات"""
        o, f = self._o, self._font
        text = "" if o["text"] is None else str(o["text"])
        img = o["image"]
        show_img = bool(img)
        show_txt = bool(text) and not (show_img and o["compound"] in ("none", "", None))
        lines = text.split("\n") if show_txt else []
        tw = max((f.measure(s) for s in lines), default=0)
        if lines:      # العرض الفعلي كما يرسمه Tk (يتفادى اختلاف قياس الخط عن رسمه)
            try:
                self.itemconfigure(self._txt_item, text="\n".join(lines), font=o["font"], width=0)
                _bb = self.bbox(self._txt_item)
                if _bb and _bb[2] > _bb[0]:
                    tw = _bb[2] - _bb[0]
            except tk.TclError:
                pass
        th = f.metrics("linespace") * len(lines) if lines else 0
        iw = ih = 0
        if show_img:
            try:
                iw, ih = img.width(), img.height()
            except Exception:
                iw = ih = 0
        gap = ui_px(6)
        comp = o["compound"]
        if show_img and show_txt:
            if comp in ("left", "right"):
                cw, ch = tw + gap + iw, max(th, ih)
            elif comp in ("top", "bottom"):
                cw, ch = max(tw, iw), th + gap + ih
            else:
                cw, ch = max(tw, iw), max(th, ih)
        else:
            cw, ch = max(tw, iw), max(th, ih)
        padx = ui_px(14) if o["padx"] is None else max(ui_px(14), ui_px(int(o["padx"]) + 8))
        pady = ui_px(8) if o["pady"] is None else max(ui_px(8), ui_px(int(o["pady"]) + 4))
        lr = int(getattr(self, "_left_reserve", 0) or 0)  # مساحة محجوزة لأيقونة على اليسار
        w = cw + 2 * padx + lr
        h = max(ch + 2 * pady, ui_px(34))
        try:
            gw, gh = int(float(o["width"] or 0)), int(float(o["height"] or 0))
        except (TypeError, ValueError):
            gw = gh = 0
        if gw > 0:
            w = max(w, ui_px(gw) if show_img else gw * f.measure("0") + 2 * padx)
        if gh > 0:
            h = max(h, ui_px(gh) if show_img else gh * f.metrics("linespace") + 2 * pady)
        self._req = (w, h)
        self._layout = (show_txt, show_img, tw, th, iw, ih, gap, comp)
        tk.Misc.configure(self, width=w, height=h)

    def _draw(self, w=None, h=None):
        """يرسم الزر بالكامل (الخلفية، الحد، النص، الصورة) حسب حالته الحالية"""
        try:
            w = w or self.winfo_width()
            h = h or self.winfo_height()
        except tk.TclError:
            return
        if w < 6 or h < 6:
            return
        o = self._o
        disabled = str(o["state"]) == "disabled"
        base = _norm_color(self, o["bg"], _T["input"])
        fg = _norm_color(self, o["fg"], _T["dark"])
        if disabled:
            fill = _mix(base, _T["border"], 0.65)
            fg = _norm_color(self, o["disabledforeground"], "#94A3B8")
        elif self._pressed:
            ab = o["activebackground"]
            fill = _shade(_norm_color(self, ab, base) if ab else base, 0.84 if not ab else 0.92)
        elif self._hover:
            ab = o["activebackground"]
            fill = _norm_color(self, ab, _shade(base, 0.92)) if ab else _shade(base, 0.92)
            if o["activeforeground"]:
                fg = _norm_color(self, o["activeforeground"], fg)
        else:
            fill = base
        radius = 0 if _FLAT_BUTTONS else max(min(ui_px(10), h // 2 - 1), ui_px(4))
        self._bg_photo = _card_image(w, h, radius, fill, getattr(self, "_outline", None), shadow=False, pad=0,
                                    ow=int(getattr(self, "_ow", 1) or 1))
        self.itemconfigure(self._bg_item, image=self._bg_photo)
        show_txt, show_img, tw, th, iw, ih, gap, comp = self._layout
        lr = int(getattr(self, "_left_reserve", 0) or 0)
        cx, cy = (w + lr) / 2, h / 2
        tx = ty = ix = iy = None
        if show_txt and show_img:
            if comp == "left":
                x0 = cx - (iw + gap + tw) / 2
                ix, iy, tx, ty = x0 + iw / 2, cy, x0 + iw + gap + tw / 2, cy
            elif comp == "right":
                x0 = cx - (iw + gap + tw) / 2
                tx, ty, ix, iy = x0 + tw / 2, cy, x0 + tw + gap + iw / 2, cy
            elif comp == "top":
                y0 = cy - (ih + gap + th) / 2
                ix, iy, tx, ty = cx, y0 + ih / 2, cx, y0 + ih + gap + th / 2
            elif comp == "bottom":
                y0 = cy - (ih + gap + th) / 2
                tx, ty, ix, iy = cx, y0 + th / 2, cx, y0 + th + gap + ih / 2
            else:
                tx, ty, ix, iy = cx, cy, cx, cy
        elif show_txt:
            tx, ty = cx, cy
        elif show_img:
            ix, iy = cx, cy
        if show_txt:
            self.coords(self._txt_item, tx, ty)
            text = str(self._o["text"])
            self.itemconfigure(self._txt_item, text=text, font=o["font"], fill=fg, state="normal",
                               width=ui_px(int(o["wraplength"] or 0)), justify=o["justify"] or "center")
        else:
            self.itemconfigure(self._txt_item, state="hidden")
        if show_img:
            self.coords(self._img_item, ix, iy)
            self.itemconfigure(self._img_item, image=o["image"], state="normal")
        else:
            self.itemconfigure(self._img_item, state="hidden")
        self.tag_lower(self._bg_item)

    # ───────── واجهة tk.Button ─────────
    def configure(self, cnf=None, **kw):
        """يقرأ/يعدّل خيارات الزر على نمط tk.Button.configure"""
        if isinstance(cnf, str):
            key = self._ALIAS.get(cnf, cnf)
            return (key, key, key, "", self._o.get(key, ""))
        opts = dict(cnf or {})
        opts.update(kw)
        if not opts:
            return {k: (k, k, k, "", v) for k, v in self._o.items()}
        retextvar = font_changed = False
        for k, v in opts.items():
            k = self._ALIAS.get(k, k)
            if k in self._IGNORED:
                continue
            if k == "cursor":
                tk.Misc.configure(self, cursor=v)
                continue
            if k in self._o:
                self._o[k] = v
                retextvar = retextvar or k == "textvariable"
                font_changed = font_changed or k == "font"
        if font_changed:
            self._font = self._make_font()
        if retextvar:
            if self._var is not None and self._var_id:
                try:
                    self._var.trace_remove("write", self._var_id)
                except Exception:
                    pass
            self._var = self._o["textvariable"]
            if self._var is not None:
                self._var_id = self._var.trace_add("write", self._sync_var)
                try:
                    self._o["text"] = self._var.get()
                except Exception:
                    pass
        if "state" in opts:
            tk.Misc.configure(self, cursor="arrow" if str(self._o["state"]) == "disabled" else "hand2")
        self._recalc()
        self._draw()
        return None

    config = configure

    def cget(self, key):
        """يرجع قيمة خيار الزر على نمط tk.Button.cget"""
        key = self._ALIAS.get(key, key)
        if key in self._o:
            return self._o[key]
        if key in self._IGNORED:
            return 0
        return tk.Misc.cget(self, key)

    def __getitem__(self, key):
        """يسمح بقراءة الخيار بصيغة button[key]"""
        return self.cget(key)

    def __setitem__(self, key, value):
        """يسمح بتعديل الخيار بصيغة button[key] = value"""
        self.configure({key: value})

    # Canvas يعيد تعريف هذه الدوال لعناصره الداخلية؛ نعيدها لسلوك الـ widget العادي
    lift = tkraise = tk.Misc.tkraise
    lower = tk.Misc.lower
    focus = tk.Misc.focus_set

    def destroy(self):
        """يفك ربط StringVar ثم يدمّر الزر"""
        if self._var is not None and self._var_id:
            try:
                self._var.trace_remove("write", self._var_id)
            except Exception:
                pass
        super().destroy()


class FlatButton(RoundedButton):
    """زر شريط الفواتير: مسطح بلا أي تأثير (لا هوفر ولا ظل ولا تغيّر عند الضغط)،
    وينفّذ أمره لحظة الضغط (ButtonPress) فيعمل من أول نقرة حتى لو تغيّر شيء على الشاشة بين الضغط والرفع.
    مع حماية من النقر المزدوج السريع."""
    RADIUS = 10

    def __init__(self, master, **kw):
        kw.setdefault("radius", self.RADIUS)
        super().__init__(master, **kw)
        self._radius = ui_px(kw["radius"])  # مستقل عن مفتاح _FLAT_BUTTONS العام
        self._last_fire = 0.0
        self.bind("<ButtonPress-1>", self._fire)

    def _set_hover(self, v):
        """لا تأثير عند مرور الماوس"""
        return None

    def _on_click(self, e):
        """الأمر ينفَّذ عند الضغط لا عند الرفع"""
        return None

    def _fire(self, e=None):
        now = time.monotonic()
        if now - self._last_fire < 0.35:
            return "break"
        self._last_fire = now
        if self._cmd:
            self._cmd()
        return "break"


class SuspendTab(ModernButton):
    """تبويب فاتورة معلّقة / طاولة: نفس واجهة ModernButton تماماً (cget/config/_outline/_ow/_left_reserve...)
    لكن مسطح بلا هوفر ولا ظل ولا شريط، بزوايا ناعمة، وينفّذ أمره لحظة الضغط فيعمل من أول نقرة."""
    TAB_H = 40
    MIN_W = 110
    RADIUS = 10

    def __init__(self, master=None, **kw):
        self._last_fire = 0.0
        super().__init__(master, **kw)

    def _recalc(self):
        """نفس الحساب الأصلي ثم نثبّت الارتفاع الموحّد وحدّاً أدنى للعرض"""
        super()._recalc()
        w, _h = self._req
        w = max(w, ui_px(self.MIN_W))
        self._req = (w, ui_px(self.TAB_H))
        tk.Misc.configure(self, width=w, height=ui_px(self.TAB_H))

    def _set_state_flag(self, name, value):
        """يلغي تأثيري المرور والضغط (لا إعادة رسم)، وينفّذ الأمر لحظة الضغط"""
        setattr(self, name, False)
        if name == "_pressed" and value:
            now = time.monotonic()
            if now - self._last_fire >= 0.35:
                self._last_fire = now
                self._click()

    def _on_release(self, e):
        self._pressed = False

    def _draw(self, w=None, h=None):
        """يرسم الزر بالمنطق الأصلي ثم يستبدل الخلفية بخلفية مسطحة بزوايا ناعمة"""
        super()._draw(w, h)
        try:
            w = w or self.winfo_width()
            h = h or self.winfo_height()
        except tk.TclError:
            return
        if w < 6 or h < 6:
            return
        fill = _norm_color(self, self._o["bg"], "#FFFFFF")
        self._bg_photo = _card_image(w, h, ui_px(self.RADIUS), fill, getattr(self, "_outline", None),
                                     shadow=False, pad=0, ow=int(getattr(self, "_ow", 1) or 1))
        self.itemconfigure(self._bg_item, image=self._bg_photo)
        self.tag_lower(self._bg_item)


class ModernLabelFrame(tk.Frame):
    """بديل لـ tk.LabelFrame و ttk.LabelFrame: بطاقة مسطحة بإطار ناعم وعنوان عريض بلون الهوية."""

    _FRAME_OK = {"cursor", "height", "width", "padx", "pady", "name", "container", "colormap", "visual"}

    @staticmethod
    def _padding(v):
        """يحوّل قيمة padding (رقم/نص/tuple) إلى tuple من قيمتين (أفقي, رأسي)"""
        if v is None:
            return (0, 0)
        if isinstance(v, (int, float)):
            return (int(v), int(v))
        nums = [int(float(x)) for x in (v.split() if isinstance(v, str) else v)]
        if len(nums) == 1:
            return (nums[0], nums[0])
        if len(nums) == 2:
            return (nums[0], nums[1])
        if len(nums) == 4:
            return ((nums[0] + nums[2]) // 2, (nums[1] + nums[3]) // 2)
        return (0, 0)

    def __init__(self, master=None, cnf=None, **kw):
        """ينشئ إطاراً بعنوان (بديل LabelFrame) بشكل عصري وبنفس خيارات tk.LabelFrame"""
        opts = dict(cnf or {})
        opts.update(kw)
        text = opts.pop("text", "")
        font = opts.pop("font", None)
        fg = opts.pop("fg", None) or opts.pop("foreground", None)
        opts.pop("foreground", None)
        padding = opts.pop("padding", None)
        bg = opts.pop("bg", None) or opts.pop("background", None)
        try:
            parent_bg = master.cget("bg")
        except Exception:
            parent_bg = _T["bg"]
        bg = bg or parent_bg
        px, py = self._padding(padding)
        px = int(opts.pop("padx", px) or px)
        py = int(opts.pop("pady", py) or py)
        frame_kw = {k: v for k, v in opts.items() if k in self._FRAME_OK and k not in ("padx", "pady")}
        super().__init__(master, bg=bg, highlightthickness=1, highlightbackground=_T["border"],
                         highlightcolor=_T["border"], bd=0, padx=px, pady=py + 16, **frame_kw)
        self._title = None
        if text:
            fam = _tkfont.nametofont("TkDefaultFont").actual("family")
            self._title = tk.Label(self, text=text, font=font or (fam, 10, "bold"), bg=bg,
                                   fg=fg or _T["accent_hover"])
            self._title.place(relx=1.0, x=-12, y=3, anchor="ne", bordermode="outside")
            # ✅ العنوان يتكيّف مع عرض الإطار (لف النص) ويُحجز له ارتفاع كافٍ فوق المحتوى مهما كان الزوم
            self._base_pady = ui_px(py + 16)
            self._last_wrap = None
            self._last_need = None
            self.bind("<Configure>", self._fit_title, add="+")
            self.after(30, self._fit_title)

    def _fit_title(self, event=None):
        """يلف نص العنوان بحسب عرض الإطار ويضبط الهامش العلوي ليتّسع للعنوان فلا يتداخل مع المحتوى"""
        try:
            t = self._title
            if t is None or not self.winfo_exists():
                return
            w = self.winfo_width()
            if w <= 1:
                return
            wrap = max(w - 26, 60)
            if wrap != self._last_wrap:
                self._last_wrap = wrap
                raw_configure(t, wraplength=wrap, justify="right")
                t.update_idletasks()
            need = max(self._base_pady, t.winfo_reqheight() + 8)
            if need != self._last_need:
                self._last_need = need
                raw_configure(self, pady=need)
        except tk.TclError:
            pass

    def configure(self, cnf=None, **kw):
        """يعدّل خيارات الإطار والعنوان على نمط tk.LabelFrame.configure"""
        if isinstance(cnf, str):
            return tk.Frame.cget(self, cnf)
        opts = dict(cnf or {})
        opts.update(kw)
        if self._title is not None:
            t = {}
            if "text" in opts:
                t["text"] = opts.pop("text")
            if "font" in opts:
                t["font"] = opts.pop("font")
            for k in ("fg", "foreground"):
                if k in opts:
                    t["fg"] = opts.pop(k)
            bg = opts.get("bg", opts.get("background"))
            if bg:
                t["bg"] = bg
            if t:
                try:
                    self._title.configure(**t)
                except tk.TclError:
                    pass
        else:
            for k in ("text", "font", "fg", "foreground"):
                opts.pop(k, None)
        for k in ("bd", "borderwidth", "relief", "labelanchor", "labelwidget", "padding", "style", "takefocus",
                  "underline"):
            opts.pop(k, None)
        if not opts:
            return None
        return tk.Frame.configure(self, **opts)

    config = configure

    def cget(self, key):
        """يرجع قيمة خيار الإطار (والنص من العنوان) على نمط cget"""
        if key == "text" and self._title is not None:
            return self._title.cget("text")
        try:
            return tk.Frame.cget(self, key)
        except tk.TclError:
            return ""

    def __getitem__(self, key):
        """يسمح بقراءة الخيار بصيغة frame[key]"""
        return self.cget(key)

    def __setitem__(self, key, value):
        """يسمح بتعديل الخيار بصيغة frame[key] = value"""
        self.configure({key: value})


# ───────── نوافذ الرسائل العصرية (بديل messagebox) ─────────
def _pick_dialog_parent(parent=None):
    """يختار نافذة أب ظاهرة فعلاً لنافذة الرسالة. السبب: الصفحة الرئيسية تُصغَّر (iconify) أثناء فتح
    الصفحات الأخرى، وإذا رُبطت الرسالة بها (transient) على ويندوز تختفي الرسالة بينما grab_set يقفل كل
    النوافذ، فيبدو أن النافذة لا تُغلق ولا يعمل التمرير دون أي خطأ."""
    root = tk._default_root

    def ok(w):
        """يتحقق أن النافذة موجودة وظاهرة ومناسبة لتكون أباً لنافذة الحوار"""
        try:
            return w is not None and bool(w.winfo_exists()) and w.state() == "normal" and bool(w.winfo_viewable())
        except Exception:
            return False

    try:
        cand = parent.winfo_toplevel() if parent is not None else None
    except Exception:
        cand = None
    if ok(cand):
        return cand
    try:
        f = root.focus_get()
        top = f.winfo_toplevel() if f is not None else None
        if ok(top):
            return top
    except Exception:
        pass
    try:
        for w in reversed(root.winfo_children()):
            if isinstance(w, tk.Toplevel) and ok(w):
                return w
    except Exception:
        pass
    return root if ok(root) else None


class _MsgButton(tk.Label):
    """زر نوافذ الرسائل: Label عادي بدل Canvas مرسوم يدوياً، فمقاسه يتبع الخط والحشوات والزوم ولا يُقصّ أبداً"""

    def __init__(self, master, text, command, bg, fg, hover, font):
        super().__init__(master, text=text, bg=bg, fg=fg, font=font, padx=34, pady=9, cursor="hand2",
                         takefocus=1, bd=0, highlightthickness=1, highlightbackground=bg,
                         highlightcolor="#93C5FD")
        self._cmd, self._bg, self._hover = command, bg, hover
        self.bind("<Enter>", lambda e: self.config(bg=self._hover, highlightbackground=self._hover))
        self.bind("<Leave>", lambda e: self.config(bg=self._bg, highlightbackground=self._bg))
        self.bind("<ButtonRelease-1>", self._release)
        self.bind("<space>", lambda e: self.invoke())

    def _release(self, e):
        if 0 <= e.x < self.winfo_width() and 0 <= e.y < self.winfo_height():
            self.invoke()

    def invoke(self):
        self._cmd()


def _modern_dialog(kind, title, message, buttons, default=0, cancel=None, parent=None):
    """buttons: [(نص, قيمة_الإرجاع, 'primary'|'secondary'|'danger')] — الأول يظهر أقصى اليمين."""
    root = tk._default_root
    if root is None:
        return None
    parent = _pick_dialog_parent(parent)  # None إذا لا توجد نافذة ظاهرة → تُعرض في وسط الشاشة
    dlg = tk.Toplevel(parent or root)
    dlg.withdraw()
    dlg.title(title or "")
    dlg.configure(bg=_T["card"])
    dlg.resizable(False, False)
    if parent is not None:
        try:
            dlg.transient(parent)
        except tk.TclError:
            pass
    result = {"v": cancel}

    def finish(v):
        """يحفظ اختيار المستخدم ويغلق نافذة الحوار"""
        result["v"] = v
        try:
            dlg.destroy()
        except tk.TclError:
            pass

    colors = {"info": (_T["accent"], _T["tint"], "i"), "question": (_T["accent"], _T["tint"], "?"),
              "warning": (_T["warning"], _T["warning_bg"], "!"), "error": (_T["danger"], _T["danger_bg"], "✕")}
    col, tint, glyph = colors.get(kind, colors["info"])
    fam = _T["font"]
    body = tk.Frame(dlg, bg=_T["card"])
    body.pack(fill="both", expand=True, padx=26, pady=(24, 14))
    ic = tk.Canvas(body, width=56, height=56, bg=_T["card"], highlightthickness=0, bd=0)
    ic.create_oval(2, 2, 54, 54, fill=tint, outline="")
    ic.create_text(28, 28, text=glyph, fill=col, font=(fam, 22, "bold"))
    ic.pack(side="right", anchor="n", padx=(16, 0))
    txt = tk.Frame(body, bg=_T["card"])
    txt.pack(side="right", fill="both", expand=True)
    if title:
        tk.Label(txt, text=title, font=(fam, 14, "bold"), bg=_T["card"], fg=_T["dark"], anchor="e",
                 justify="right", wraplength=360).pack(fill="x", anchor="e")
    tk.Label(txt, text=str(message if message is not None else ""), font=(fam, 11), bg=_T["card"],
             fg=_T["muted"], anchor="e", justify="right", wraplength=360).pack(fill="x", anchor="e",
                                                                                 pady=(6 if title else 0, 0))
    tk.Frame(dlg, bg=_T["border"], height=1).pack(fill="x")
    foot = tk.Frame(dlg, bg=_T["bg"])
    foot.pack(fill="x")
    btns = []
    for i, (label, value, style) in enumerate(buttons):
        if style == "primary":
            bg, fgc, ab = _T["accent"], "#FFFFFF", _T["accent_hover"]
        elif style == "danger":
            bg, fgc, ab = _T["danger"], "#FFFFFF", "#DC2626"
        else:
            bg, fgc, ab = _T["input"], _T["dark"], "#E2E8F0"
        b = _MsgButton(foot, label, lambda v=value: finish(v), bg, fgc, ab, (fam, 11, "bold"))
        b.pack(side="right", padx=(0, 10) if i else (16, 10), pady=12)
        btns.append(b)
    dlg.protocol("WM_DELETE_WINDOW", lambda: finish(cancel))
    dlg.bind("<Escape>", lambda e: finish(cancel))
    dlg.bind("<Return>", lambda e: finish(buttons[default][1]))
    dlg.update_idletasks()
    w, h = max(dlg.winfo_reqwidth(), ui_px(420)), dlg.winfo_reqheight()   # 420 بوحدات التصميم → يُقاس بالزوم
    try:
        if parent is None:
            raise tk.TclError
        parent.update_idletasks()
        px = parent.winfo_rootx() + (parent.winfo_width() - w) // 2
        py = parent.winfo_rooty() + (parent.winfo_height() - h) // 2
        if parent.winfo_width() < 50:
            raise tk.TclError
    except tk.TclError:
        px, py = (dlg.winfo_screenwidth() - w) // 2, (dlg.winfo_screenheight() - h) // 2
    raw_geometry(dlg, f"{w}x{h}+{max(px, 0)}+{max(py, 0)}")   # w/h بالبكسل الفعلي (من winfo) → بدون قياس مضاعف يقصّ الزر
    dlg.deiconify()
    try:
        dlg.attributes("-topmost", True)
    except tk.TclError:
        pass
    dlg.lift()

    def regrow():
        """الأزرار (Canvas) يتغيّر مقاسها بعد الرسم الأول؛ نعيد قياس المحتوى ونكبّر النافذة لو كانت أصغر منه
        حتى لا يُقصّ زر «موافق» (خصوصاً مع الزوم)."""
        try:
            if not dlg.winfo_exists():
                return
            dlg.update_idletasks()
            need_h = body.winfo_reqheight() + 1 + foot.winfo_reqheight()
            need_w = max(body.winfo_reqwidth(), foot.winfo_reqwidth(), ui_px(420))
            cw, ch = dlg.winfo_width(), dlg.winfo_height()
            if need_h > ch + 1 or need_w > cw + 1:
                nw, nh = max(cw, need_w), max(ch, need_h)
                nx = max(0, dlg.winfo_x() - (nw - cw) // 2)
                ny = max(0, min(dlg.winfo_y() - (nh - ch) // 2, dlg.winfo_screenheight() - nh - 60))
                raw_geometry(dlg, f"{nw}x{nh}+{nx}+{ny}")
        except tk.TclError:
            pass

    try:
        dlg.focus_force()
        btns[default].focus_set()
        dlg.update()
        regrow()
        for ms in (40, 150, 400):
            dlg.after(ms, regrow)
        # لا نقفل (grab) إلا إذا كانت الرسالة ظاهرة فعلاً، وإلا يتجمّد التطبيق بنافذة غير مرئية
        if dlg.winfo_viewable():
            dlg.grab_set()
    except tk.TclError:
        pass
    dlg.wait_window()
    return result["v"]


def _wrap_mb(orig, kind, make_buttons, default=0, cancel=None):
    """يغلّف دالة messagebox الأصلية لتعرض نافذة حديثة بدلها (ويرجع للأصلية لو لا يوجد root)"""
    def fn(title=None, message=None, **options):
        """الدالة البديلة لـ messagebox: تعرض الحوار الحديث بالأزرار المطلوبة وترجع الاختيار"""
        if tk._default_root is None:
            return orig(title, message, **options)
        return _modern_dialog(kind, title, message, make_buttons(options), default=options.get("default_idx", default),
                              cancel=cancel, parent=options.get("parent"))
    return fn


_OK = lambda o: [("موافق", "ok", "primary")]
messagebox.showinfo = _wrap_mb(messagebox.showinfo, "info", _OK, cancel="ok")
messagebox.showwarning = _wrap_mb(messagebox.showwarning, "warning", _OK, cancel="ok")
messagebox.showerror = _wrap_mb(messagebox.showerror, "error", _OK, cancel="ok")
messagebox.askyesno = _wrap_mb(messagebox.askyesno, "question",
                               lambda o: [("نعم", True, "primary"), ("لا", False, "secondary")], default=0,
                               cancel=False)
messagebox.askokcancel = _wrap_mb(messagebox.askokcancel, "question",
                                  lambda o: [("موافق", True, "primary"), ("إلغاء", False, "secondary")],
                                  default=0, cancel=False)
messagebox.askretrycancel = _wrap_mb(messagebox.askretrycancel, "warning",
                                     lambda o: [("إعادة المحاولة", True, "primary"), ("إلغاء", False, "secondary")],
                                     default=0, cancel=False)
messagebox.askquestion = _wrap_mb(messagebox.askquestion, "question",
                                  lambda o: [("نعم", "yes", "primary"), ("لا", "no", "secondary")], default=0,
                                  cancel="no")
messagebox.askyesnocancel = _wrap_mb(messagebox.askyesnocancel, "question",
                                     lambda o: [("نعم", True, "primary"), ("لا", False, "secondary"),
                                                ("إلغاء", None, "secondary")], default=0, cancel=None)
try:
    simpledialog.Button = ModernButton
except Exception:
    pass


class CartList(tk.Frame):
    """قائمة الفاتورة كبطاقات احترافية. تحاكي واجهة ttk.Treeview المستخدمة في الكود الحالي
    (insert / item / delete / get_children / selection / selection_set / focus / see / index ...)
    حتى تعمل كل الدوال القديمة كما هي دون تعديل.
    ترتيب القيم كما في الجدول القديم: [0]باركود [1]الإجمالي [2]سعر البيع [3]السعر الأصلي [4]الوزن
    [5]الكمية [6]الموظف [7]الاسم ..."""

    COL_DEL, COL_TOTAL, COL_UNIT, COL_QTY, COL_EMP, COL_NAME = 0, 1, 2, 3, 4, 5

    # أحجام الأعمدة حسب العرض المتاح: (حذف, إجمالي, سعر الوحدة, كمية, موظف, أقل عرض للاسم)
    _LAYOUTS = {
        "wide":    (92, 118, 118, 150, 150, 150),
        "compact": (80, 92, 86, 124, 0, 120),    # الموظف ينتقل تحت الاسم
        "tiny":    (68, 76, 72, 104, 0, 90),
    }

    def __init__(self, master, app, **kw):
        """ينشئ قائمة الفاتورة كبطاقات (Canvas قابل للتمرير + رأس أعمدة) بواجهة تحاكي Treeview"""
        self.app = app
        super().__init__(master, bg=app.card_bg)
        self._mode = "wide"
        self._head_labels = {}
        self._data = {}  # iid -> {"values": tuple, "tags": tuple, "card": RoundedFrame}
        self._order = []
        self._sel = []
        self._focused = ""
        self._counter = 0
        self._action = None
        self._checked = []   # العناصر المعلّمة بالتشيك بوكس (للنقل الجماعي)
        self._bar = None
        self._bar_count = None

        ff = app.font_family
        # ── رأس الأعمدة ──
        self._header = tk.Frame(self, bg=app.card_bg)
        self._header.pack(fill="x", padx=(14, 30), pady=(8, 2))
        self._configure_cols(self._header)
        heads = {self.COL_DEL: "", self.COL_TOTAL: "الإجمالي", self.COL_UNIT: "سعر الوحدة",
                 self.COL_QTY: "الكمية", self.COL_EMP: "الموظف", self.COL_NAME: "المنتج"}
        for col, txt in heads.items():
            _hl = tk.Label(self._header, text=txt, font=(ff, 10, "bold"), bg=app.card_bg, fg=app.text_muted,
                           anchor="e" if col == self.COL_NAME else "center")
            _hl.grid(row=0, column=col, sticky="ew")
            self._head_labels[col] = _hl
        tk.Frame(self, bg=app.border_color, height=1).pack(fill="x", padx=10, pady=(4, 4))

        # ── منطقة التمرير ──
        body = tk.Frame(self, bg=app.card_bg)
        body.pack(fill="both", expand=True)
        self._vsb = ttk.Scrollbar(body, orient="vertical")
        self._vsb.pack(side=tk.RIGHT, fill=tk.Y)
        self._canvas = tk.Canvas(body, bg=app.card_bg, highlightthickness=0, bd=0,
                                 yscrollcommand=self._vsb.set)
        self._canvas.pack(side=tk.LEFT, fill="both", expand=True)
        self._vsb.config(command=self._canvas.yview)
        self._rows = tk.Frame(self._canvas, bg=app.card_bg)
        self._inner_win = self._canvas.create_window((0, 0), window=self._rows, anchor="nw")
        self._canvas.bind("<Configure>", self._on_canvas_resize)
        self._rows.bind("<Configure>", lambda e: self._canvas.configure(scrollregion=self._canvas.bbox("all")))

        # ── حالة فارغة ──
        self._empty = tk.Frame(self._canvas, bg=app.card_bg)
        tk.Label(self._empty, image=_glyph_image("box", 64, app.accent_color, app.accent_tint),
                 bg=app.card_bg).pack()
        tk.Label(self._empty, text="الفاتورة فارغة", font=(ff, 15, "bold"), bg=app.card_bg,
                 fg=app.text_dark).pack(pady=(10, 0))
        tk.Label(self._empty, text="امسح الباركود أو اختر منتجاً من القائمة لإضافته", font=(ff, 11),
                 bg=app.card_bg, fg=app.text_muted).pack(pady=(2, 0))
        self._refresh_empty()

    # ───────── مساعدات الشبكة ─────────
    def _configure_cols(self, frame):
        """يضبط عرض أعمدة الشبكة حسب النمط الحالي (wide / compact / tiny)"""
        d, t, u, q, e, n = self._LAYOUTS[self._mode]
        frame.grid_columnconfigure(self.COL_DEL, minsize=d)
        frame.grid_columnconfigure(self.COL_TOTAL, minsize=t)
        frame.grid_columnconfigure(self.COL_UNIT, minsize=u)
        frame.grid_columnconfigure(self.COL_QTY, minsize=q)
        frame.grid_columnconfigure(self.COL_EMP, minsize=e)
        frame.grid_columnconfigure(self.COL_NAME, weight=1, minsize=n)

    def _mode_for_width(self, w):
        """يحدد نمط العرض المناسب (واسع/مضغوط/صغير) حسب العرض المتاح"""
        if w >= ui_px(800):
            return "wide"
        if w >= ui_px(540):
            return "compact"
        return "tiny"

    def _on_canvas_resize(self, e):
        """عند تغيّر حجم اللوحة: يضبط عرض المحتوى ويبدّل نمط الأعمدة عند الحاجة"""
        self._canvas.itemconfigure(self._inner_win, width=e.width)
        mode = self._mode_for_width(e.width)
        if mode == self._mode:
            return
        self._mode = mode
        self._configure_cols(self._header)
        emp_head = self._head_labels.get(self.COL_EMP)
        if emp_head is not None:
            if mode == "wide":
                emp_head.grid()
            else:
                emp_head.grid_remove()
        for iid in list(self._order):
            self._fill_card(iid)

    # ───────── صور الموظفين (دائرية + كاش) ─────────
    _AVATAR_CACHE = {}  # اسم الموظف -> PhotoImage أو None (لا توجد صورة)

    @classmethod
    def clear_avatar_cache(cls):
        """استدعها بعد تغيير صورة أي موظف ليُعاد تحميلها."""
        cls._AVATAR_CACHE.clear()

    def _employee_avatar(self, name, size=22):
        """يُرجع صورة الموظف دائرية بحجم size، أو None إن لم توجد (فيُستخدم الرمز الافتراضي)."""
        key = (str(name), size)
        if key in self._AVATAR_CACHE:
            return self._AVATAR_CACHE[key]
        photo = None
        try:
            cur = self.app.cursor
            cur.execute("SELECT image FROM employees WHERE name = %s ORDER BY left_work ASC LIMIT 1",
                        (str(name),))
            row = cur.fetchone()
            if row and row[0]:
                S = 4  # رسم بدقة أعلى ثم تصغير لحواف ناعمة
                im = Image.open(io.BytesIO(row[0])).convert("RGBA")
                m = min(im.size)
                im = im.crop(((im.width - m) // 2, (im.height - m) // 2,
                              (im.width + m) // 2, (im.height + m) // 2)).resize((size * S, size * S),
                                                                                  Image.LANCZOS)
                mask = Image.new("L", (size * S, size * S), 0)
                ImageDraw.Draw(mask).ellipse((0, 0, size * S - 1, size * S - 1), fill=255)
                out = Image.new("RGBA", (size * S, size * S), (0, 0, 0, 0))
                out.paste(im, (0, 0), mask)
                ImageDraw.Draw(out).ellipse((0, 0, size * S - 1, size * S - 1),
                                            outline=_hex_rgb(self.app.border_color) + (255,), width=S)
                photo = ImageTk.PhotoImage(out.resize((size, size), Image.LANCZOS))
        except Exception as e:
            print(f"خطأ في جلب صورة الموظف {name}: {e}")
            photo = None
        self._AVATAR_CACHE[key] = photo
        return photo

    def set_action_handler(self, fn):
        """fn(action, iid) حيث action ∈ {'increase','decrease','delete'}"""
        self._action = fn

    def _refresh_empty(self):
        """يُظهر أو يخفي رسالة 'القائمة فارغة' حسب وجود عناصر"""
        if self._order:
            self._empty.place_forget()
        else:
            self._empty.place(relx=0.5, rely=0.42, anchor="center")
            self._empty.lift()

    # ───────── واجهة شبيهة بـ Treeview ─────────
    @staticmethod
    def _conv(v):
        """يحوّل القيمة إلى int إن أمكن وإلا يتركها نصاً"""
        s = str(v)
        try:
            return int(s)
        except ValueError:
            return s

    def _norm(self, values):
        """يطبّع صف قيم (يحوّل كل قيمة بـ _conv)"""
        return tuple(self._conv(v) for v in values)

    def insert(self, parent, index, iid=None, **kw):
        """يضيف بطاقة جديدة للقائمة (مثل Treeview.insert) ويرجع معرّفها"""
        self._counter += 1
        iid = iid or "I%03d" % self._counter
        values = self._norm(kw.get("values", ()))
        tags = tuple(kw.get("tags", ()))
        card = RoundedFrame(self._rows, fill=self.app.card_bg, outline=self.app.border_color,
                            radius=0 if _FLAT_BUTTONS else 12,
                            shadow=not _FLAT_BUTTONS, pad=3, padding=(8, 5))
        self._data[iid] = {"values": values, "tags": tags, "card": card}
        if index == "end" or not isinstance(index, int) or index >= len(self._order):
            self._order.append(iid)
            card.pack(fill="x", padx=(8, 6), pady=(0, 1))
        else:
            ref = self._data[self._order[index]]["card"]
            self._order.insert(index, iid)
            card.pack(fill="x", padx=(8, 6), pady=(0, 1), before=ref)
        self._fill_card(iid)
        self._refresh_empty()
        return iid

    def item(self, iid, option=None, **kw):
        """يقرأ/يعدّل بيانات عنصر (قيم، وسوم) مثل Treeview.item"""
        rec = self._data.get(iid)
        if rec is None:
            raise tk.TclError("Item %s not found" % iid)
        if kw:
            changed = False
            if "values" in kw:
                nv = self._norm(kw["values"])
                if nv != rec["values"]:
                    rec["values"] = nv
                    changed = True
            if "tags" in kw:
                rec["tags"] = tuple(kw["tags"])
            if changed:
                self._fill_card(iid)
            return None
        info = {"text": "", "image": "", "values": rec["values"], "open": 0, "tags": rec["tags"]}
        return info.get(option) if option else info

    def get_children(self, item=""):
        """يرجع معرّفات كل العناصر بالترتيب (مثل get_children)"""
        return tuple(self._order)

    def delete(self, *items):
        """يحذف عنصراً أو أكثر من القائمة مع بطاقاتها"""
        flat = []
        for it in items:
            flat.extend(it if isinstance(it, (list, tuple)) else [it])
        for iid in flat:
            rec = self._data.pop(iid, None)
            if rec is None:
                continue
            try:
                rec["card"].destroy()
            except tk.TclError:
                pass
            if iid in self._order:
                self._order.remove(iid)
            if iid in self._sel:
                self._sel.remove(iid)
            if iid in self._checked:
                self._checked.remove(iid)
            if self._focused == iid:
                self._focused = ""
        self._refresh_empty()
        self._update_bar()

    def selection(self):
        """يرجع العناصر المحددة حالياً"""
        return tuple(self._sel)

    @staticmethod
    def _flat(items):
        """يسطّح قائمة عناصر متداخلة إلى قائمة واحدة ويتجاهل القيم الفارغة"""
        out = []
        for it in items:
            if isinstance(it, (list, tuple)):
                out.extend(it)
            elif it not in (None, ""):
                out.append(it)
        return out

    def selection_set(self, *items):
        """يحدد العناصر المعطاة (ويلغي تحديد غيرها) ويلوّن بطاقاتها"""
        new = [i for i in self._flat(items) if i in self._data]
        for iid in list(self._sel):
            if iid not in new:
                self._paint(iid, False)
        self._sel = new
        for iid in new:
            self._paint(iid, True)

    def selection_remove(self, *items):
        """يلغي تحديد العناصر المعطاة"""
        for iid in self._flat(items):
            if iid in self._sel:
                self._sel.remove(iid)
                self._paint(iid, False)

    def selection_add(self, *items):
        """يضيف العناصر المعطاة إلى التحديد الحالي"""
        for iid in self._flat(items):
            if iid in self._data and iid not in self._sel:
                self._sel.append(iid)
                self._paint(iid, True)

    def focus(self, item=None):
        """يقرأ/يضبط العنصر الذي عليه التركيز"""
        if item is None:
            return self._focused
        self._focused = item if item in self._data else ""
        return self._focused

    def index(self, iid):
        """يرجع ترتيب العنصر داخل القائمة"""
        return self._order.index(iid)

    def see(self, iid):
        """يمرّر القائمة لتظهر بطاقة العنصر المطلوب"""
        rec = self._data.get(iid)
        if not rec:
            return
        self.update_idletasks()
        total = max(self._rows.winfo_height(), 1)
        view_h = self._canvas.winfo_height()
        y, h = rec["card"].winfo_y(), rec["card"].winfo_height()
        top = self._canvas.canvasy(0)
        if y < top:
            self._canvas.yview_moveto(y / total)
        elif y + h > top + view_h:
            self._canvas.yview_moveto(max(0, (y + h - view_h) / total))

    def tag_configure(self, *a, **k):
        """دالة توافق مع Treeview (لا تفعل شيئاً)"""
        return None

    def heading(self, *a, **k):
        """دالة توافق مع Treeview (لا تفعل شيئاً)"""
        return None

    def column(self, *a, **k):
        """دالة توافق مع Treeview (لا تفعل شيئاً)"""
        return None

    def identify_region(self, x, y):
        """دالة توافق مع Treeview: تعتبر كل نقرة داخل خلية"""
        return "cell"

    def identify_row(self, y):
        """دالة توافق مع Treeview (لا تحدد صفاً)"""
        return ""

    def identify_column(self, x):
        """دالة توافق مع Treeview (لا تحدد عموداً)"""
        return ""

    def yview(self, *a):
        """يمرّر عرض اللوحة رأسياً (يوجه yview للـ Canvas)"""
        return self._canvas.yview(*a)

    def xview(self, *a):
        """دالة توافق مع Treeview (لا يوجد تمرير أفقي)"""
        return (0.0, 1.0)

    def xview_moveto(self, *a):
        """دالة توافق مع Treeview (لا تفعل شيئاً)"""
        return None

    def configure(self, cnf=None, **kw):
        """يعدّل خيارات القائمة مع تجاهل خيارات Treeview غير المدعومة (style, height)"""
        kw.pop("style", None)
        kw.pop("height", None)
        if cnf is None and not kw:
            return super().configure()
        if isinstance(cnf, dict):
            kw = {**cnf, **kw}
        kw.pop("style", None)
        if kw:
            return super().configure(**kw)

    config = configure

    # ───────── الرسم ─────────
    def _paint(self, iid, selected):
        """يلوّن بطاقة العنصر حسب كونه محدداً أم لا"""
        rec = self._data.get(iid)
        if not rec:
            return
        a = self.app
        if selected:
            rec["card"].recolor(fill=a.accent_tint, outline=a.accent_color)
        else:
            rec["card"].recolor(fill=a.card_bg, outline=a.border_color)

    def _to_float(self, v, default=0.0):
        """يحوّل قيمة إلى float بعد إزالة الفواصل، أو يرجع القيمة الافتراضية"""
        try:
            return float(str(v).replace(",", ""))
        except (ValueError, TypeError):
            return default

    def _fill_card(self, iid):
        """يبني محتوى بطاقة العنصر (الاسم، الكمية، السعر، الموظف، أزرار الحذف/التعديل)"""
        rec = self._data[iid]
        card, vals, a = rec["card"], rec["values"], self.app
        selected = iid in self._sel
        fill = a.accent_tint if selected else a.card_bg
        inner = card.inner
        for ch in inner.winfo_children():
            ch.destroy()
        inner.configure(bg=fill)
        card._fill = fill
        self._configure_cols(inner)
        ff = a.font_family

        def g(i, d=""):
            """يرجع قيمة العمود i من الصف أو قيمة افتراضية لو غير موجود"""
            return vals[i] if i < len(vals) else d

        barcode, total, sale = g(0), self._to_float(g(1)), self._to_float(g(2))
        original, weight, qty = self._to_float(g(3)), self._to_float(g(4)), g(5, 1)
        employee, name = g(6), g(7)
        if str(employee) in ("None", "0"):
            employee = ""

        # ── الاسم + سطر الباركود ──
        mode = self._mode
        wide = mode == "wide"
        fs_name, fs_total, fs_unit, fs_qty = {"wide": (13, 14, 12, 14), "compact": (12, 12, 11, 13),
                                              "tiny": (11, 11, 10, 12)}[mode]
        btn_size = 30 if wide else (28 if mode == "compact" else 24)
        name_box = tk.Frame(inner, bg=fill)
        name_box.grid(row=0, column=self.COL_NAME, sticky="e", padx=(0, 4))
        tk.Label(name_box, text=str(name), font=(ff, fs_name, "bold"), bg=fill, fg=a.text_dark, anchor="e",
                 justify="right", wraplength=(0 if wide else (200 if mode == "compact" else 120))
                 ).pack(anchor="e")
        has_barcode = str(barcode) not in ("", "None")
        if has_barcode:
            tk.Label(name_box, text="#" + str(barcode), font=(ff, 9), bg=fill, fg=a.text_muted,
                     anchor="e").pack(anchor="e")

        # ── الموظف (صورة أكبر + اسم) في منتصف الصف بين الاسم والكمية ──
        if employee:
            if wide:
                emp_box = tk.Frame(inner, bg=fill)
                emp_box.grid(row=0, column=self.COL_EMP, padx=6)
            else:
                emp_box = tk.Frame(name_box, bg=fill)
                emp_box.pack(anchor="e", pady=(2, 0))
            avatar = self._employee_avatar(employee, 40 if wide else 22)
            if avatar:
                av_lbl = tk.Label(emp_box, image=avatar, bg=fill, bd=0)
                av_lbl.image = avatar  # مرجع حتى لا تختفي الصورة
            else:
                av_lbl = tk.Label(emp_box, text="👤", font=(ff, 18 if wide else 10), bg=fill, fg=a.text_muted)
            av_lbl.pack(side=tk.RIGHT, padx=(8 if wide else 4, 0))
            tk.Label(emp_box, text=str(employee), font=(ff, 11 if wide else 9, "bold"), bg=fill, fg=a.text_muted,
                     anchor="e").pack(side=tk.RIGHT)

        # ── الكمية: ستيبر (+/−) أو الوزن للمنتجات الموزونة ──
        qty_box = tk.Frame(inner, bg=fill)
        qty_box.grid(row=0, column=self.COL_QTY)
        if weight > 0:
            tk.Label(qty_box, text="%.3f kg" % weight, font=(ff, 12 if wide else 10, "bold"), bg=fill,
                     fg=a.info_color).pack()
        else:
            btn_minus = self._icon_button(qty_box, "minus", a.text_muted, "#F1F5F9", "#E2E8F0",
                                          lambda: self._fire("decrease", iid), size=btn_size)
            btn_minus.pack(side=tk.LEFT)
            tk.Label(qty_box, text=str(qty), font=(ff, fs_qty, "bold"), bg=fill, fg=a.text_dark,
                     width=3 if wide else 2).pack(side=tk.LEFT, padx=2)
            btn_plus = self._icon_button(qty_box, "plus", "#FFFFFF", a.accent_color, a.accent_hover,
                                         lambda: self._fire("increase", iid), size=btn_size)
            btn_plus.pack(side=tk.LEFT)

        # ── سعر الوحدة (مع شطب السعر الأصلي عند وجود خصم) ──
        unit_box = tk.Frame(inner, bg=fill)
        unit_box.grid(row=0, column=self.COL_UNIT)
        if original > 0 and abs(original - sale) > 0.001:
            tk.Label(unit_box, text="%.2f" % original, font=(ff, 9, "overstrike"), bg=fill,
                     fg=a.text_muted).pack()
        tk.Label(unit_box, text="%.2f" % sale, font=(ff, fs_unit, "bold"), bg=fill, fg=a.danger_color).pack()

        # ── الإجمالي ──
        tk.Label(inner, text="%.2f" % total, font=(ff, fs_total, "bold"), bg=fill,
                 fg=a.danger_color).grid(row=0, column=self.COL_TOTAL)

        # ── تحديد (اختياري) + حذف ──
        act_box = tk.Frame(inner, bg=fill)
        act_box.grid(row=0, column=self.COL_DEL)
        _isz = 34 if wide else 28
        try:
            _show_sel = bool(a._cart_selection_enabled())
        except Exception:
            _show_sel = False
        if _show_sel:
            if iid in self._checked:
                chk_btn = self._icon_button(act_box, "check_on", "#FFFFFF", a.accent_color, a.accent_hover,
                                            lambda: self.toggle_check(iid), size=_isz - 6)
            else:
                chk_btn = self._icon_button(act_box, "check_off", "#94A3B8", fill, "#EFF6FF",
                                            lambda: self.toggle_check(iid), size=_isz - 6)
            chk_btn.pack(side=tk.LEFT, padx=(0, 8))
        # أيقونة الحذف تظهر دائماً؛ عند تفعيل «منع حذف المنتج» يمر الضغط عليها بفحص الصلاحية وكلمة المرور
        del_btn = self._icon_button(act_box, "trash", a.danger_color, a.danger_bg_light, "#FECACA",
                                    lambda: self._fire("delete", iid), size=_isz)
        del_btn.pack(side=tk.LEFT)

        # ── النقر على أي مكان في البطاقة يحدّد الصف ──
        def _bind_select(w):
            """يربط نقر عنصر داخل البطاقة بتحديد البطاقة (ما عدا أزرار البطاقة نفسها)"""
            if getattr(w, "_is_cart_btn", False):
                return
            w.bind("<Button-1>", lambda e, i=iid: self.selection_set(i), add="+")
            for ch in w.winfo_children():
                _bind_select(ch)

        _bind_select(inner)
        card.bind("<Button-1>", lambda e, i=iid: self.selection_set(i), add="+")

    # ───────── التحديد المتعدد (تشيك بوكس) + شريط «نقل المحدد» ─────────
    def checked(self):
        """يرجع العناصر المعلّمة بالتشيك بوكس بترتيب ظهورها في الفاتورة"""
        return [i for i in self._order if i in self._checked]

    def toggle_check(self, iid):
        """يعلّم/يلغي تعليم منتج بالتشيك بوكس"""
        if iid not in self._data:
            return
        if iid in self._checked:
            self._checked.remove(iid)
        else:
            self._checked.append(iid)
        self._fill_card(iid)
        self._update_bar()

    def check_all(self):
        """يعلّم كل المنتجات (وإن كانت كلها معلّمة يلغي التعليم)"""
        everything = len(self._checked) >= len(self._order) > 0
        self._checked = [] if everything else list(self._order)
        for iid in list(self._order):
            self._fill_card(iid)
        self._update_bar()

    def clear_checks(self):
        """يلغي تعليم كل المنتجات"""
        old = list(self._checked)
        self._checked = []
        for iid in old:
            if iid in self._data:
                self._fill_card(iid)
        self._update_bar()

    def _selection_enabled(self):
        """هل إعداد إظهار التحديد مفعّل؟"""
        try:
            return bool(self.app._cart_selection_enabled())
        except Exception:
            return False

    def _build_bar(self):
        """ينشئ شريط التحديد (يظهر فوق القائمة عند تعليم منتج واحد على الأقل)"""
        a = self.app
        ff = a.font_family
        bar = tk.Frame(self, bg=a.accent_tint, highlightthickness=1, highlightbackground=a.accent_color)
        self._bar_count = tk.Label(bar, text="", font=(ff, 11, "bold"), bg=a.accent_tint, fg=a.text_dark)
        self._bar_count.pack(side=tk.RIGHT, padx=(10, 12), pady=6)
        tk.Button(bar, text="محاسبة المحدد", command=lambda: self._fire("checkout_selected", None),
                  font=(ff, 11, "bold"), bg=a.accent_color, fg="white", activebackground=a.accent_hover,
                  activeforeground="white", relief="flat", bd=0, padx=16, pady=4,
                  cursor="hand2").pack(side=tk.RIGHT, padx=4, pady=6)
        tk.Button(bar, text="نقل المحدد", command=lambda: self._fire("move_selected", None),
                  font=(ff, 10, "bold"), bg="#DBEAFE", fg="#1D4ED8", activebackground="#BFDBFE",
                  relief="flat", bd=0, padx=12, pady=4, cursor="hand2").pack(side=tk.RIGHT, padx=4, pady=6)
        self._bar_all_btn = tk.Button(bar, text="تحديد الكل", command=self.check_all, font=(ff, 10, "bold"),
                                      bg="#E8EDF3", fg="#334155", activebackground="#D5DCE6", relief="flat",
                                      bd=0, padx=12, pady=4, cursor="hand2")
        self._bar_all_btn.pack(side=tk.RIGHT, padx=4, pady=6)
        tk.Button(bar, text="إلغاء التحديد", command=self.clear_checks, font=(ff, 10), bg=a.accent_tint,
                  fg=a.text_muted, activebackground=a.accent_tint, relief="flat", bd=0, padx=10, pady=4,
                  cursor="hand2").pack(side=tk.LEFT, padx=6, pady=6)
        self._bar = bar

    def _update_bar(self):
        """يُظهر/يُخفي شريط التحديد ويحدّث العدّاد حسب عدد المعلّم"""
        n = len(self._checked)
        if n == 0 or not self._selection_enabled():
            if self._bar is not None:
                self._bar.pack_forget()
            return
        if self._bar is None:
            self._build_bar()
        self._bar_count.configure(text=f"تم تحديد {n}" if n != 1 else "تم تحديد منتج واحد")
        self._bar_all_btn.configure(text="إلغاء الكل" if n >= len(self._order) else "تحديد الكل")
        if not self._bar.winfo_ismapped():
            self._bar.pack(fill="x", padx=10, pady=(6, 0), before=self._header)

    def _icon_button(self, parent, kind, fg, bg, hover_bg, command, size=30):
        """ينشئ زر أيقونة صغيراً (Label) بتأثير hover وأمر عند الضغط"""
        lbl = tk.Label(parent, image=_glyph_image(kind, size, fg, bg), bg=parent.cget("bg"), cursor="hand2",
                       bd=0)
        lbl._is_cart_btn = True
        lbl.bind("<Enter>", lambda e: lbl.configure(image=_glyph_image(kind, size, fg, hover_bg)))
        lbl.bind("<Leave>", lambda e: lbl.configure(image=_glyph_image(kind, size, fg, bg)))
        lbl.bind("<Button-1>", lambda e: command() or "break")
        return lbl

    def _fire(self, action, iid):
        """يستدعي دالة الإجراء الخارجية (حذف/تعديل...) للعنصر المحدد"""
        if self._action:
            self._action(action, iid)


# ═══════════════════════════════════════════════════════════════════════════════
#  باركود Code128 (بدون مكتبات خارجية) — يُستخدم لعرض رقم الفاتورة أسفل الفاتورة
# ═══════════════════════════════════════════════════════════════════════════════
_C128_PATTERNS = (
    "212222 222122 222221 121223 121322 131222 122213 122312 132212 221213 "
    "221312 231212 112232 122132 122231 113222 123122 123221 223211 221132 "
    "221231 213212 223112 312131 311222 321122 321221 312212 322112 322211 "
    "212123 212321 232121 111323 131123 131321 112313 132113 132311 211313 "
    "231113 231311 112133 112331 132131 113123 113321 133121 313121 211331 "
    "231131 213113 213311 213131 311123 311321 331121 312113 312311 332111 "
    "314111 221411 431111 111224 111422 121124 121421 141122 141221 112214 "
    "112412 122114 122411 142112 142211 241211 221114 413111 241112 134111 "
    "111242 121142 121241 114212 124112 124211 411212 421112 421211 212141 "
    "214121 412121 111143 111341 131141 114113 114311 411113 411311 113141 "
    "114131 311141 411131 211412 211214 211232 2331112"
).split()


def _code128_modules(data):
    """يرجع قائمة عروض (شريط/فراغ بالتناوب يبدأ بشريط) لباركود Code128 للنص data."""
    data = str(data)
    if data.isdigit() and len(data) >= 2 and len(data) % 2 == 0:      # Code C: رقمان في كل رمز
        codes = [105] + [int(data[i:i + 2]) for i in range(0, len(data), 2)]
    else:                                                               # Code B: حروف وأرقام
        codes = [104] + [(ord(c) - 32) if 32 <= ord(c) < 128 else 0 for c in data]
    chk = codes[0]
    for i, c in enumerate(codes[1:], 1):
        chk += i * c
    codes.append(chk % 103)
    codes.append(106)                                                   # STOP
    widths = []
    for c in codes:
        widths += [int(ch) for ch in _C128_PATTERNS[c]]
    return widths


def make_code128_image(data, bar_h=80, module=3, quiet=10, max_w=None):
    """صورة باركود Code128 (أبيض/أسود) — module = عرض أصغر شريط بالبكسل.
    لو max_w محدد يصغّر الـ module تلقائياً حتى يتسع الباركود (لا يقل عن 1)."""
    from PIL import Image, ImageDraw
    widths = _code128_modules(data)
    total_modules = sum(widths) + 2 * quiet
    if max_w:
        module = max(1, min(module, int(max_w // total_modules)))
    w = total_modules * module
    img = Image.new('RGB', (w, bar_h), (255, 255, 255))
    dr = ImageDraw.Draw(img)
    x = quiet * module
    for i, wd in enumerate(widths):
        if i % 2 == 0:                                                   # شريط أسود
            dr.rectangle([x, 0, x + wd * module - 1, bar_h], fill=(0, 0, 0))
        x += wd * module
    return img


# ═══════════════════════════════════════════════════════════════════════════════
#  QR روابط التواصل الاجتماعي للإيصال: كل رابط يُحوَّل لـ QR بأيقونة منصته في المنتصف
#  (فيسبوك / إنستغرام / تيك توك / إكس / يوتيوب / واتساب / سناب / لينكدإن / تليجرام / جوجل)
#  الأيقونات تُرسم بالكود (بدون ملفات أو إنترنت) بالأبيض والأسود لتناسب الطابعة الحرارية.
# ═══════════════════════════════════════════════════════════════════════════════
# (المفتاح، النطاقات، السطر الأول للعنوان، السطر الثاني)
_SOCIAL_PLATFORMS = (
    ("facebook", ("facebook.com", "fb.com", "fb.me", "fb.watch"), "تابعنا على", "فيسبوك"),
    ("instagram", ("instagram.com", "instagr.am"), "تابعنا على", "إنستغرام"),
    ("tiktok", ("tiktok.com",), "تابعنا على", "تيك توك"),
    ("x", ("twitter.com", "x.com"), "تابعنا على", "إكس"),
    ("youtube", ("youtube.com", "youtu.be"), "اشترك في", "قناتنا"),
    ("whatsapp", ("wa.me", "whatsapp.com"), "تواصل معنا على", "واتساب"),
    ("snapchat", ("snapchat.com",), "تابعنا على", "سناب شات"),
    ("linkedin", ("linkedin.com",), "تابعنا على", "لينكدإن"),
    ("telegram", ("t.me", "telegram.me", "telegram.org"), "تابعنا على", "تليجرام"),
)
_TRACKING_PARAMS = {"locale", "hl", "igsh", "igshid", "fbclid", "si", "ref", "feature", "mibextid", "s"}


def _normalize_link(url):
    """يضيف https:// لو الرابط بلا بروتوكول، ويرجع '' لو فارغ."""
    u = str(url or "").strip()
    if not u:
        return ""
    if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.\-]*:", u):
        u = "https://" + u
    return u


def _social_platform(url):
    """يتعرّف على المنصة من نطاق الرابط → (المفتاح، سطر العنوان 1، سطر العنوان 2)."""
    from urllib.parse import urlparse
    try:
        host = re.sub(r"^www\.", "", (urlparse(url).netloc or "").lower())
    except Exception:
        host = ""
    for key, domains, l1, l2 in _SOCIAL_PLATFORMS:
        for dom in domains:
            if host == dom or host.endswith("." + dom):
                return key, l1, l2
    return "link", "تواصل معنا", "عبر الرابط"


def _shorten_social_url(url):
    """يحذف باراميترات التتبع (locale / hl / igsh / utm_*...) لتقليل حجم الـ QR وزيادة وضوحه، دون المساس بباقي الرابط."""
    from urllib.parse import urlparse, parse_qsl, urlencode, urlunparse
    try:
        p = urlparse(url)
        q = [(k, v) for k, v in parse_qsl(p.query, keep_blank_values=True)
             if k.lower() not in _TRACKING_PARAMS and not k.lower().startswith("utm_")]
        return urlunparse((p.scheme, p.netloc, p.path, p.params, urlencode(q), ""))
    except Exception:
        return url


def _icon_font(size):
    """خط عريض لرسم الحروف داخل الأيقونات (يرجع الخط الافتراضي لو لم يوجد)."""
    from PIL import ImageFont
    for c in ("arialbd.ttf", "C:/Windows/Fonts/arialbd.ttf", "tahomabd.ttf", "C:/Windows/Fonts/tahomabd.ttf",
              "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"):
        try:
            return ImageFont.truetype(c, size)
        except Exception:
            continue
    return ImageFont.load_default()


def _social_icon(kind, size):
    """أيقونة المنصة كدائرة سوداء بداخلها رمز أبيض (محاطة بحلقة بيضاء) بحجم size×size."""
    from PIL import Image, ImageDraw
    N = size * 6                                   # رسم بدقة أعلى ثم تصغير لنعومة الحواف
    im = Image.new("RGB", (N, N), (255, 255, 255))
    d = ImageDraw.Draw(im)
    pad = int(N * 0.05)
    d.ellipse([pad, pad, N - pad, N - pad], fill=(0, 0, 0))
    W_, K_ = (255, 255, 255), (0, 0, 0)

    def P(*pts):
        return [(x * N, y * N) for x, y in pts]

    def line(a, b, w, fill=W_):
        d.line(P(a, b), fill=fill, width=int(w * N))
        for (x, y) in (a, b):                      # أطراف دائرية
            r = w * N / 2
            d.ellipse([x * N - r, y * N - r, x * N + r, y * N + r], fill=fill)

    if kind == "facebook":
        d.text((0.55 * N, 0.80 * N), "f", font=_icon_font(int(N * 0.86)), fill=W_, anchor="ms")
    elif kind == "instagram":
        d.rounded_rectangle([0.25 * N, 0.25 * N, 0.75 * N, 0.75 * N], radius=int(0.15 * N), outline=W_,
                            width=int(0.065 * N))
        d.ellipse([0.37 * N, 0.37 * N, 0.63 * N, 0.63 * N], outline=W_, width=int(0.06 * N))
        d.ellipse([0.62 * N, 0.31 * N, 0.69 * N, 0.38 * N], fill=W_)
    elif kind == "tiktok":
        d.rectangle(P((0.51, 0.24), (0.585, 0.64)), fill=W_)
        d.ellipse(P((0.33, 0.54), (0.55, 0.76)), fill=W_)
        d.polygon(P((0.585, 0.24), (0.66, 0.36), (0.76, 0.40), (0.76, 0.48), (0.66, 0.45), (0.585, 0.40)), fill=W_)
    elif kind == "x":
        line((0.30, 0.28), (0.70, 0.72), 0.075)
        line((0.70, 0.28), (0.30, 0.72), 0.075)
    elif kind == "youtube":
        d.rounded_rectangle([0.22 * N, 0.31 * N, 0.78 * N, 0.69 * N], radius=int(0.10 * N), fill=W_)
        d.polygon(P((0.44, 0.40), (0.44, 0.60), (0.61, 0.50)), fill=K_)
    elif kind == "whatsapp":
        d.ellipse(P((0.24, 0.22), (0.76, 0.74)), outline=W_, width=int(0.06 * N))
        d.polygon(P((0.26, 0.80), (0.28, 0.62), (0.40, 0.72)), fill=W_)
        # سماعة الهاتف: قوس سميك في الربع السفلي الأيسر بنهايتين دائريتين
        d.arc(P((0.33, 0.31), (0.67, 0.65)), start=100, end=190, fill=W_, width=int(0.085 * N))
        for (bx, by) in ((0.49, 0.645), (0.345, 0.485)):
            d.ellipse([(bx - 0.05) * N, (by - 0.05) * N, (bx + 0.05) * N, (by + 0.05) * N], fill=W_)
    elif kind == "snapchat":
        d.ellipse(P((0.32, 0.22), (0.68, 0.58)), fill=W_)
        d.rectangle(P((0.32, 0.40), (0.68, 0.68)), fill=W_)
        d.polygon(P((0.32, 0.68), (0.39, 0.76), (0.46, 0.68), (0.54, 0.76), (0.61, 0.68), (0.68, 0.76),
                    (0.68, 0.68)), fill=W_)
        d.ellipse(P((0.40, 0.38), (0.46, 0.46)), fill=K_)
        d.ellipse(P((0.54, 0.38), (0.60, 0.46)), fill=K_)
    elif kind == "linkedin":
        d.text((0.50 * N, 0.69 * N), "in", font=_icon_font(int(N * 0.50)), fill=W_, anchor="ms")
    elif kind == "telegram":
        d.polygon(P((0.21, 0.50), (0.80, 0.26), (0.66, 0.76), (0.50, 0.62), (0.40, 0.72), (0.39, 0.57)), fill=W_)
        line((0.39, 0.57), (0.72, 0.36), 0.03, fill=K_)
    elif kind == "google":
        d.text((0.52 * N, 0.755 * N), "G", font=_icon_font(int(N * 0.66)), fill=W_, anchor="ms")
    else:                                          # رابط عام: سلسلة
        d.rounded_rectangle(P((0.20, 0.38), (0.58, 0.62)), radius=int(0.12 * N), outline=W_, width=int(0.06 * N))
        d.rounded_rectangle(P((0.42, 0.38), (0.80, 0.62)), radius=int(0.12 * N), outline=W_, width=int(0.06 * N))
    return im.resize((size, size), Image.LANCZOS)


def make_social_qr(url, target, kind=None):
    """QR للرابط داخل مربع target×target بكسل بوحدات صحيحة (حادّة)، وبأيقونة المنصة في المنتصف (لو kind محدد).
    مستوى التصحيح Q ليتحمل الأيقونة مع بقاء الرمز صغيراً وواضحاً على الورق الحراري."""
    import qrcode
    from PIL import Image
    qr = qrcode.QRCode(version=None, error_correction=qrcode.constants.ERROR_CORRECT_Q, box_size=1, border=1)
    qr.add_data(str(url))
    qr.make(fit=True)
    modules = qr.modules_count + 2          # + الحدود (1 على كل جانب)
    box = max(2, target // modules)         # أكبر حجم صحيح للوحدة
    qr.box_size = box
    qr_img = qr.make_image(fill_color="black", back_color="white").convert("RGB")
    side = qr_img.width
    canvas = qr_img                         # بحجمها الفعلي (مضاعف صحيح لعرض الوحدة) بدون تمطيط
    if kind:
        isz = max(24, int(side * 0.23)) // 2 * 2
        canvas.paste(_social_icon(kind, isz), ((canvas.width - isz) // 2, (canvas.height - isz) // 2))
    return canvas


_AR_DAYS = ("الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد")


def arabic_day_name(dt):
    """اسم اليوم بالعربي لكائن datetime/date (الاثنين=0 ... الأحد=6)."""
    try:
        return _AR_DAYS[dt.weekday()]
    except Exception:
        return ""


# ═══════════════════════════════════════════════════════════════════════════════
#  مولّد التقارير للطابعة الحرارية 80mm — تصميم موحّد (يُستخدم في تقرير المصروفات
#  وتقرير الإجمالي). الفاتورة لها نفس الهوية البصرية داخل build_invoice_image.
# ═══════════════════════════════════════════════════════════════════════════════
class ThermalDoc:
    """مستند إيصال حراري (80mm): يرسم الترويسة والجداول والإجماليات كصورة جاهزة للطباعة (تقرير المصروفات/الإجمالي)"""
    CURRENCY = "ج.م"
    W = int((80 / 25.4) * 203)      # 639 بكسل = عرض ورق 80mm
    M = 22                          # هامش جانبي (كبّره لو قُصّت حواف الطباعة)
    BLACK = (0, 0, 0)
    WHITE = (255, 255, 255)
    _bold_path = None
    _reg_path = None
    _resolved = False

    # ───────────────────────── تهيئة ─────────────────────────
    @classmethod
    def _resolve_fonts(cls):
        """يحدد مسارات الخطوط (عادي/عريض) المتاحة على الجهاز ويخزنها لكل الإيصالات"""
        if cls._resolved:
            return
        from PIL import ImageFont

        def pick(cands):
            """يرجع أول مسار خط صالح من قائمة المرشحين"""
            for c in cands:
                try:
                    ImageFont.truetype(c, 20)
                    return c
                except Exception:
                    continue
            return None

        cls._bold_path = pick(["tahomabd.ttf", "C:/Windows/Fonts/tahomabd.ttf",
                               "arialbd.ttf", "C:/Windows/Fonts/arialbd.ttf",
                               "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"])
        cls._reg_path = pick(["tahoma.ttf", "C:/Windows/Fonts/tahoma.ttf",
                              "arial.ttf", "C:/Windows/Fonts/arial.ttf",
                              "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"]) or cls._bold_path
        cls._resolved = True

    def __init__(self):
        """ينشئ مستند إيصال جديداً (صورة بيضاء بعرض الورق الحراري) ويضبط مؤشر الكتابة"""
        from PIL import Image, ImageDraw
        self._resolve_fonts()
        self.CW = self.W - 2 * self.M
        self.img = Image.new('RGB', (self.W, 2400), self.WHITE)
        self.d = ImageDraw.Draw(self.img)
        self.y = 14
        self._fc = {}

    def _room(self, h):
        """يكبّر اللوحة تلقائياً لو اقتربنا من نهايتها."""
        from PIL import Image, ImageDraw
        while self.y + h + 80 > self.img.height:
            new = Image.new('RGB', (self.W, self.img.height * 2), self.WHITE)
            new.paste(self.img, (0, 0))
            self.img = new
            self.d = ImageDraw.Draw(new)

    # ───────────────────────── أدوات نص ─────────────────────────
    def F(self, size, bold=False):
        """يرجع خطاً بالحجم والسُمك المطلوبين مع تخزين مؤقت للخطوط"""
        from PIL import ImageFont
        k = (size, bold)
        if k not in self._fc:
            try:
                basic = getattr(getattr(ImageFont, 'Layout', None), 'BASIC', 0)
                self._fc[k] = ImageFont.truetype(self._bold_path if bold else self._reg_path,
                                                 size, layout_engine=basic)
            except Exception:
                self._fc[k] = ImageFont.load_default()
        return self._fc[k]

    @staticmethod
    def ar(t):
        """يجهّز النص العربي للرسم (إعادة تشكيل الحروف + اتجاه RTL)"""
        t = '' if t is None else str(t)
        if not t:
            return ''
        try:
            import arabic_reshaper
            from bidi.algorithm import get_display
            return get_display(arabic_reshaper.reshape(t))
        except Exception:
            return t

    def tw(self, t, f):
        """يحسب عرض النص بالبكسل بعد تجهيزه عربياً"""
        return self.d.textlength(self.ar(t), font=f)

    @staticmethod
    def asc(f):
        """يرجع ارتفاع الخط فوق خط الأساس (ascent)"""
        try:
            return f.getmetrics()[0]
        except Exception:
            return 20

    @staticmethod
    def lh(f):
        """يرجع ارتفاع سطر الخط الكامل (ascent + descent)"""
        try:
            a, b = f.getmetrics()
            return a + b
        except Exception:
            return 26

    def txt(self, t, x, y, f, anchor='ra', fill=None):
        """يكتب نصاً عربياً في الموضع المحدد"""
        self.d.text((x, y), self.ar(t), font=f, fill=fill or self.BLACK, anchor=anchor)

    def fit(self, t, size, bold, max_w, min_size=14):
        """يصغّر حجم الخط تدريجياً حتى يناسب النص العرض المسموح"""
        s = size
        while s > min_size and self.tw(t, self.F(s, bold)) > max_w:
            s -= 1
        return self.F(s, bold)

    def wrap(self, t, f, max_w):
        """يقسم النص إلى أسطر لا يتجاوز كل منها العرض المسموح"""
        t = str(t if t is not None else '').strip()
        if not t:
            return ['']
        lines, cur = [], ''
        for w in t.split():
            trial = (cur + ' ' + w).strip()
            if self.tw(trial, f) <= max_w:
                cur = trial
                continue
            if cur:
                lines.append(cur)
            if self.tw(w, f) > max_w:
                piece = ''
                for ch in w:
                    if self.tw(piece + ch, f) <= max_w:
                        piece += ch
                    else:
                        lines.append(piece)
                        piece = ch
                cur = piece
            else:
                cur = w
        if cur:
            lines.append(cur)
        return lines or ['']

    # ───────────────────────── خطوط فاصلة ─────────────────────────
    def hline(self, y, kind='solid', th=2, x1=None, x2=None):
        """يرسم خطاً أفقياً (متصل/منقط/مزدوج) في الارتفاع المحدد"""
        x1 = self.M if x1 is None else x1
        x2 = self.W - self.M if x2 is None else x2
        if kind == 'dotted':
            x = x1
            while x < x2:
                self.d.line([(x, y), (min(x + 4, x2), y)], fill=self.BLACK, width=th)
                x += 9
        elif kind == 'dashed':
            x = x1
            while x < x2:
                self.d.line([(x, y), (min(x + 12, x2), y)], fill=self.BLACK, width=max(th, 2))
                x += 19
        elif kind == 'double':
            self.d.line([(x1, y), (x2, y)], fill=self.BLACK, width=3)
            self.d.line([(x1, y + 7), (x2, y + 7)], fill=self.BLACK, width=1)
        else:
            self.d.line([(x1, y), (x2, y)], fill=self.BLACK, width=th)

    def rule(self, kind='solid', th=2, after=12):
        """يرسم فاصلاً أفقياً عند موضع الكتابة الحالي ثم ينزل بعده"""
        self._room(40)
        self.hline(self.y, kind, th)
        self.y += after + (7 if kind == 'double' else 0)

    def gap(self, h=8):
        """يترك مسافة رأسية فارغة"""
        self.y += h

    # ───────────────────────── الترويسة ─────────────────────────
    def brand(self, settings=None, logo_max=110):
        """شعار + اسم المتجر + فاصل مزدوج. settings = صف invoice_settings."""
        import io
        from PIL import Image

        def S(i):
            """يقرأ حقل إعداد بالفهرس ويرجع None لو فارغ"""
            try:
                v = settings[i]
                return v if v not in (None, '') else None
            except Exception:
                return None

        self._room(300)
        logo_blob = S(1)
        if logo_blob:
            try:
                logo = Image.open(io.BytesIO(logo_blob)).convert('RGB')
                logo.thumbnail((logo_max, logo_max), Image.Resampling.LANCZOS)
                self.img.paste(logo, ((self.W - logo.width) // 2, self.y))
                self.y += logo.height + 10
            except Exception as e:
                print(f"⚠️ خطأ في الشعار: {e}")
        name = S(9)
        if name:
            f = self.fit(name, 36, True, self.CW)
            self.txt(name, self.W / 2, self.y, f, 'ma')
            self.y += self.lh(f) + 4
        self.y += 6
        self.hline(self.y, 'double')
        self.y += 22

    def title_bar(self, label, sub=None):
        """يرسم شريط عنوان أسود بنص أبيض في وسط الإيصال"""
        self._room(120)
        f = self.F(32, True)
        ic = self._icon_for(label)
        ic_s = 28
        tw_ = self.tw(label, f)
        total = tw_ + ((ic_s + 12) if ic else 0)
        bw, bh = total + 90, self.lh(f) + 12
        bw = min(bw, self.CW)
        self.d.rounded_rectangle([((self.W - bw) / 2, self.y), ((self.W + bw) / 2, self.y + bh)],
                                 radius=10, fill=self.BLACK)
        cxm = self.W / 2
        if ic:
            self.txt(label, cxm - total / 2 + tw_ / 2, self.y + 6, f, 'ma', fill=self.WHITE)
            self.icon(ic, cxm + total / 2 - ic_s / 2, self.y + bh / 2, ic_s, fill=self.WHITE)
        else:
            self.txt(label, cxm, self.y + 6, f, 'ma', fill=self.WHITE)
        self.y += bh + 8
        if sub:
            f2 = self.F(23)
            self.txt(sub, self.W / 2, self.y, f2, 'ma')
            self.y += self.lh(f2) + 6
        self.y += 8

    def info_card(self, rows):
        """rows: قائمة صفوف — كل صف tuple من خلية أو أكثر (عنوان, قيمة|[قيم]) أو None.
        الخلايا الفارغة (None) تُهمل والباقي يتقاسم عرض الصف بالتساوي."""
        PAD = 12
        self._room(120 + 70 * len(rows))
        top = self.y
        self.y += 8
        fl = self.F(20)

        for ri, row in enumerate(rows):
            cells = [c for c in row if c]
            if not cells:
                continue
            if ri > 0:
                self.hline(self.y - 2, 'dotted', 1, self.M + PAD, self.W - self.M - PAD)
                self.y += 4
            n = len(cells)
            pad = PAD if n < 3 else 7          # هامش أضيق عند 3 أعمدة فأكثر لتوفير مساحة
            # عرض كل عمود: متساوٍ لعمودين؛ ومن 3 أعمدة يُحسب حسب المحتوى الفعلي (بدون فراغات زائدة)
            # والمساحة المتبقية تُمنح لعمود "الوردية" إن وُجد، وإلا تتوزع بالتساوي
            if n < 3:
                widths = [self.CW / n] * n
            else:
                fv27 = self.F(27, True)
                nat = []
                for (lbl, vals) in cells:
                    vv = vals if isinstance(vals, (list, tuple)) else [vals]
                    w_val = max([self.tw(str(v), fv27) for v in vv] + [0])
                    nat.append(max(self.tw(lbl, fl) + (23 if self._icon_for(lbl) else 0),
                                   min(w_val, self.CW * 0.34)) + 2 * pad + 4)
                tot = sum(nat)
                if tot >= self.CW:
                    widths = [self.CW * w / tot for w in nat]
                else:
                    extra = self.CW - tot
                    flex = [k for k, (lbl, _v) in enumerate(cells) if lbl == "الوردية"] or list(range(n))
                    widths = list(nat)
                    for k in flex:
                        widths[k] += extra / len(flex)
            r0 = self.y
            end_y = r0
            x_edge = self.W - self.M
            divs = []
            for k, (lbl, vals) in enumerate(cells):
                col_w = widths[k]
                if not isinstance(vals, (list, tuple)):
                    vals = [vals]
                x_right = x_edge - pad
                yy = r0
                _ic = self._icon_for(lbl)
                if _ic:
                    self.icon(_ic, x_right - 9, yy + self.lh(fl) / 2, 19)
                    self.txt(lbl, x_right - 23, yy, fl, 'ra')
                else:
                    self.txt(lbl, x_right, yy, fl, 'ra')
                yy += self.lh(fl)
                for v in vals:
                    fv = self.fit(str(v), 27, True, col_w - 2 * pad, min_size=(16 if n >= 3 else 14))
                    if self.tw(str(v), fv) > col_w - 2 * pad:      # لا يتّسع حتى بأصغر خط ← يُقسّم على أسطر
                        lines = self.wrap(str(v), fv, col_w - 2 * pad)
                    else:
                        lines = [str(v)]
                    for ln in lines:
                        self.txt(ln, x_right, yy, fv, 'ra')
                        yy += self.lh(fv)
                end_y = max(end_y, yy)
                x_edge -= col_w
                if k < n - 1:
                    divs.append(x_edge)
            end_y += 4
            for xd in divs:
                self.d.line([(xd, r0 - 2), (xd, end_y - 4)], fill=self.BLACK, width=1)
            self.y = end_y
        self.d.rounded_rectangle([(self.M, top), (self.W - self.M, self.y)], radius=10,
                                 outline=self.BLACK, width=2)
        self.y += 12

    # ───────────────────────── أقسام وصفوف ─────────────────────────
    def section(self, title):
        """يرسم عنوان قسم (نص بين خطين) في الإيصال"""
        self._room(80)
        self.y += 4
        f = self.F(25, True)
        tw_ = self.tw(title, f)
        ic = self._icon_for(title)
        ic_s = 24
        w = tw_ + ((ic_s + 8) if ic else 0)
        cx = self.W / 2
        mid_y = self.y + self.lh(f) // 2
        self.d.line([(self.M, mid_y), (cx - w / 2 - 12, mid_y)], fill=self.BLACK, width=2)
        self.d.line([(cx + w / 2 + 12, mid_y), (self.W - self.M, mid_y)], fill=self.BLACK, width=2)
        if ic:
            self.txt(title, cx - w / 2 + tw_ / 2, self.y, f, 'ma')
            self.icon(ic, cx + w / 2 - ic_s / 2, mid_y, ic_s)
        else:
            self.txt(title, cx, self.y, f, 'ma')
        self.y += self.lh(f) + 6

    def kv(self, label, value, bold=False, size=25):
        """يكتب سطر (اسم: قيمة) بمحاذاة اليمين واليسار"""
        self._room(60)
        fl, fv = self.F(size, bold), self.F(size, True)
        base = self.y + max(self.asc(fl), self.asc(fv))
        _ic = self._icon_for(label)
        if _ic:
            _is = max(16, size - 4)
            self.icon(_ic, self.W - self.M - _is / 2, self.y + max(self.lh(fl), self.lh(fv)) / 2, _is)
            self.d.text((self.W - self.M - _is - 7, base), self.ar(label), font=fl, fill=self.BLACK, anchor='rs')
        else:
            self.d.text((self.W - self.M, base), self.ar(label), font=fl, fill=self.BLACK, anchor='rs')
        self.d.text((self.M, base), self.ar(value), font=fv, fill=self.BLACK, anchor='ls')
        self.y += max(self.lh(fl), self.lh(fv)) + 3

    def total_box(self, label, value, with_currency=True):
        """يرسم صندوقاً أسود للإجمالي (النص يميناً والمبلغ يساراً)"""
        self._room(120)
        flb, fam = self.F(29, True), self.F(40, True)
        box_h = max(self.lh(flb), self.lh(fam)) + 20
        self.d.rounded_rectangle([(self.M, self.y), (self.W - self.M, self.y + box_h)],
                                 radius=12, fill=self.BLACK)
        base = self.y + 10 + max(self.asc(flb), self.asc(fam))
        self.icon('cash', self.W - self.M - 16 - 16, self.y + box_h / 2, 32, fill=self.WHITE)
        self.d.text((self.W - self.M - 16 - 40, base), self.ar(label), font=flb,
                    fill=self.WHITE, anchor='rs')
        amt = str(value) + (f" {self.CURRENCY}" if (with_currency and self.CURRENCY) else "")
        fa = self.fit(amt, 40, True, self.CW - 40 - 40 - self.tw(label, flb) - 20, min_size=22)
        self.d.text((self.M + 16, base), self.ar(amt), font=fa, fill=self.WHITE, anchor='ls')
        self.y += box_h + 16

    def note(self, text, size=22):
        """يكتب ملاحظة نصية في منتصف الإيصال مع التفاف الأسطر"""
        self._room(100)
        f = self.F(size)
        for ln in self.wrap(text, f, self.CW):
            self.txt(ln, self.W / 2, self.y, f, 'ma')
            self.y += self.lh(f) + 2
        self.y += 6

    def empty_note(self, text):
        """يرسم صندوقاً بحد يحمل رسالة 'لا توجد بيانات'"""
        self._room(100)
        f = self.F(23)
        bh = self.lh(f) + 20
        self.d.rounded_rectangle([(self.M, self.y), (self.W - self.M, self.y + bh)], radius=10,
                                 outline=self.BLACK, width=1)
        self.txt(text, self.W / 2, self.y + 10, f, 'ma')
        self.y += bh + 14

    # ───────────────────────── الجدول ─────────────────────────
    def table(self, cols, rows, font_size=None):
        """cols: [{'h':عنوان,'r':نسبة,'a':'r'|'c','w':لف النص,'b':خط عريض}]  (الأول = أقصى اليمين)
        rows: [{'c':[...], 's': None|'group'|'sub'}]"""
        n = len(cols)
        fs = font_size or (18 if n >= 8 else 19 if n >= 7 else 21 if n >= 5 else 22)
        fh = self.F(fs - 1 if n >= 7 else fs, True)
        tot = sum(c['r'] for c in cols)
        widths = [int(self.CW * c['r'] / tot) for c in cols]
        widths[-1] += self.CW - sum(widths)
        x_rights, xr = [], self.W - self.M
        for w_ in widths:
            x_rights.append(xr)
            xr -= w_
        CP = 6

        def put(ci, text, yy, font, fill=None):
            """يكتب نص خلية الجدول بمحاذاة العمود (وسط/يمين)"""
            if cols[ci].get('a', 'r') == 'c':
                self.txt(text, x_rights[ci] - widths[ci] / 2, yy, font, 'ma', fill)
            else:
                self.txt(text, x_rights[ci] - CP, yy, font, 'ra', fill)

        # رأس الجدول
        hh = self.lh(fh) + 14
        self._room(hh + 40)
        self.d.rectangle([(self.M, self.y), (self.W - self.M, self.y + hh)], fill=self.BLACK)
        for i, c in enumerate(cols):
            hf = self.fit(c['h'], getattr(fh, 'size', 20), True, widths[i] - 2 * CP, min_size=12)
            put(i, c['h'], self.y + 7, hf, self.WHITE)
        self.y += hh

        for idx, row in enumerate(rows):
            style = row.get('s')
            cells = row['c']
            nxt = rows[idx + 1].get('s') if idx + 1 < len(rows) else 'end'

            if style == 'group':
                fg = self.F(fs + 2, True)
                lines = self.wrap(cells[0], fg, self.CW - 2 * CP)
                self._room(len(lines) * self.lh(fg) + 24)
                self.y += 5
                for ln in lines:
                    self.txt(ln, self.W - self.M - CP, self.y, fg, 'ra')
                    self.y += self.lh(fg)
                self.hline(self.y + 1, 'solid', 1)
                self.y += 3
                continue

            bold_row = style == 'sub'
            if bold_row:
                self.hline(self.y, 'solid', 2)

            per_col_lines, per_col_font = [], []
            for i, c in enumerate(cols):
                text = str(cells[i]) if i < len(cells) and cells[i] is not None else ''
                is_bold = bold_row or c.get('b', False)
                if c.get('w'):
                    f = self.F(fs, is_bold)
                    lns = self.wrap(text, f, widths[i] - 2 * CP)
                else:
                    f = self.fit(text, fs, is_bold, widths[i] - 2 * CP, min_size=13)
                    lns = [text]
                per_col_lines.append(lns)
                per_col_font.append(f)
            nl_h = max(len(per_col_lines[i]) * self.lh(per_col_font[i]) for i in range(n))
            rh = nl_h + 10
            self._room(rh + 20)
            ty = self.y + 5
            for i in range(n):
                for k, ln in enumerate(per_col_lines[i]):
                    put(i, ln, ty + k * self.lh(per_col_font[i]), per_col_font[i])
            self.y += rh
            if nxt not in ('end', 'group', 'sub') and not bold_row:
                self.hline(self.y, 'dotted', 1)

        self.hline(self.y, 'solid', 3)
        self.y += 8

    def entries(self, rows):
        """بنود مفصّلة بسطرين لكل بند (خط بولد واضح):
        rows: [{'title': الاسم, 'amount': المبلغ, 'sub': الخدمة/الوصف, 'tag': نص صغير يسار السطر الثاني}]"""
        FT, FS, FG = self.F(27, True), self.F(23, True), self.F(21, True)
        n = len(rows)
        for i, r in enumerate(rows):
            title = str(r.get('title') or '')
            amount = str(r.get('amount') or '')
            sub = str(r.get('sub') or '').strip()
            tag = str(r.get('tag') or '').strip()
            tag_w = (self.tw(tag, FG) + 22) if tag else 0
            sub_lines = self.wrap(sub, FS, self.CW - tag_w - 4) if sub else []
            h = self.lh(FT) + len(sub_lines) * self.lh(FS) + 16
            self._room(h + 24)
            y0 = self.y + 6
            amt_w = self.tw(amount, FT)
            ft = self.fit(title, 27, True, self.CW - amt_w - 24, min_size=18)
            base = y0 + max(self.asc(FT), self.asc(ft))
            self.d.text((self.W - self.M, base), self.ar(title), font=ft, fill=self.BLACK, anchor='rs')
            self.d.text((self.M, base), self.ar(amount), font=FT, fill=self.BLACK, anchor='ls')
            yy = y0 + max(self.lh(FT), self.lh(ft))
            for k, ln in enumerate(sub_lines):
                b2 = yy + self.asc(FS)
                self.d.text((self.W - self.M, b2), self.ar(ln), font=FS, fill=self.BLACK, anchor='rs')
                if k == 0 and tag:
                    self.d.text((self.M, b2), self.ar(tag), font=FG, fill=self.BLACK, anchor='ls')
                yy += self.lh(FS)
            self.y = yy + 8
            if i < n - 1:
                self.hline(self.y - 2, 'dotted', 1)
                self.y += 2

    def summary_box(self, label, value):
        """صندوق إجمالي بإطار (أخف من total_box الأسود) — لإجمالي كل قسم."""
        self._room(90)
        self.y += 4
        fl, fv = self.F(27, True), self.F(31, True)
        bh = max(self.lh(fl), self.lh(fv)) + 18
        self.d.rounded_rectangle([(self.M, self.y), (self.W - self.M, self.y + bh)],
                                 radius=10, outline=self.BLACK, width=3)
        base = self.y + 9 + max(self.asc(fl), self.asc(fv))
        self.d.text((self.W - self.M - 14, base), self.ar(label), font=fl, fill=self.BLACK, anchor='rs')
        self.d.text((self.M + 14, base), self.ar(value), font=fv, fill=self.BLACK, anchor='ls')
        self.y += bh + 8

    # ───────────────────────── التذييل ─────────────────────────
    def signature(self, label):
        """يرسم خط توقيع مع اسم الجهة تحته"""
        self._room(160)
        self.y += 30
        self.hline(self.y, 'solid', 1, int(self.W * 0.2), int(self.W * 0.8))
        self.y += 6
        f = self.F(21)
        self.txt(label, self.W / 2, self.y, f, 'ma')
        self.y += self.lh(f) + 10


    # ───────────────────────── أيقونات (ترسم بالأشكال — تصلح للطابعة الحرارية) ─────────────────────────
    BRANCH_NAME = "الفرع الرئيسي"      # اسم الفرع المطبوع على تذكرة التحضير (غيّره حسب الفرع)

    _ICON_RULES = (
        ("مجموع", "cash"),
        ("دليفري", "bike"), ("التوصيل", "bike"), ("السائق", "bike"),
        ("تيك", "bag"), ("الأصناف", "bag"), ("الصنف", "bag"),
        ("الموعد", "stopwatch"),
        ("وقت", "clock"), ("الوقت", "clock"), ("الوردية", "clock"),
        ("التاريخ", "calendar"), ("الاثنين", "calendar"), ("الثلاثاء", "calendar"),
        ("الأربعاء", "calendar"), ("الخميس", "calendar"), ("الجمعة", "calendar"),
        ("السبت", "calendar"), ("الأحد", "calendar"),
        ("الفرع", "store"),
        ("الهاتف", "phone"), ("العنوان", "pin"), ("المنطقة", "pin"),
        ("الكاشير", "user"), ("المستخدم", "user"), ("العميل", "user"), ("الموظف", "user"),
        ("الدفع", "cash"), ("الإجمالي", "cash"), ("المطلوب", "cash"), ("مصروف", "cash"),
        ("مجموع", "cash"), ("الخصم", "tag"),
        ("ملاحظ", "note"), ("تقرير", "note"),
        ("رقم", "hash"),
    )

    def _icon_for(self, label):
        """يرجع اسم الأيقونة المناسبة لعنوان/تسمية (أو None)"""
        t = str(label or '').strip()
        if t in ("من", "إلى"):
            return "calendar"
        for key, ic in self._ICON_RULES:
            if key in t:
                return ic
        return None

    def icon(self, name, cx, cy, s=24, fill=None):
        """يرسم أيقونة بسيطة اسمها name مركزها (cx, cy) وحجمها s بكسل"""
        d = self.d
        c = fill or self.BLACK
        bg = self.WHITE if c == self.BLACK else self.BLACK
        r = s / 2.0
        x0, y0, x1, y1 = cx - r, cy - r, cx + r, cy + r
        w = max(2, int(round(s / 11.0)))
        if name == 'clock':
            d.ellipse([x0, y0, x1, y1], outline=c, width=w)
            d.line([(cx, cy), (cx, cy - r * .58)], fill=c, width=w)
            d.line([(cx, cy), (cx + r * .45, cy + r * .1)], fill=c, width=w)
        elif name == 'stopwatch':
            d.ellipse([x0 + s * .06, y0 + s * .16, x1 - s * .06, y1], outline=c, width=w)
            d.rectangle([cx - s * .14, y0, cx + s * .14, y0 + s * .12], fill=c)
            d.line([(cx, cy + s * .1), (cx, cy - s * .2)], fill=c, width=w)
            d.line([(cx, cy + s * .1), (cx + s * .2, cy + s * .2)], fill=c, width=w)
        elif name == 'calendar':
            d.rounded_rectangle([x0 + 1, y0 + s * .12, x1 - 1, y1 - 1], radius=max(2, int(s * .1)), outline=c, width=w)
            d.rectangle([x0 + 1, y0 + s * .12, x1 - 1, y0 + s * .38], fill=c)
            for px in (.3, .7):
                d.line([(x0 + s * px, y0), (x0 + s * px, y0 + s * .22)], fill=c, width=w)
            for gx in (.28, .5, .72):
                for gy in (.55, .76):
                    d.rectangle([x0 + s * gx - 1.5, y0 + s * gy - 1.5, x0 + s * gx + 1.5, y0 + s * gy + 1.5], fill=c)
        elif name == 'store':
            d.polygon([(x0, y0 + s * .42), (x0 + s * .14, y0 + s * .08), (x1 - s * .14, y0 + s * .08), (x1, y0 + s * .42)], fill=c)
            d.rectangle([x0 + s * .1, y0 + s * .42, x1 - s * .1, y1 - 1], outline=c, width=w)
            d.rectangle([cx - s * .13, y0 + s * .6, cx + s * .13, y1 - 1], fill=c)
        elif name == 'printer':
            d.rectangle([x0 + s * .26, y0, x1 - s * .26, y0 + s * .36], outline=c, width=w)
            d.rounded_rectangle([x0, y0 + s * .34, x1, y0 + s * .78], radius=max(2, int(s * .1)), fill=c)
            d.rectangle([x0 + s * .26, y0 + s * .6, x1 - s * .26, y1], fill=bg, outline=c, width=w)
        elif name == 'chef':
            d.ellipse([x0, y0 + s * .26, x0 + s * .5, y0 + s * .66], fill=c)
            d.ellipse([x1 - s * .5, y0 + s * .26, x1, y0 + s * .66], fill=c)
            d.ellipse([x0 + s * .2, y0, x1 - s * .2, y0 + s * .58], fill=c)
            d.rectangle([x0 + s * .15, y0 + s * .5, x1 - s * .15, y0 + s * .84], fill=c)
            d.rectangle([x0 + s * .15, y0 + s * .88, x1 - s * .15, y1], fill=c)
            d.line([(x0 + s * .15, y0 + s * .86), (x1 - s * .15, y0 + s * .86)], fill=bg, width=max(1, w - 1))
        elif name == 'user':
            d.ellipse([cx - s * .2, y0, cx + s * .2, y0 + s * .4], fill=c)
            d.pieslice([x0 + s * .08, y0 + s * .52, x1 - s * .08, y1 + s * .5], 180, 360, fill=c)
        elif name == 'phone':
            d.rounded_rectangle([cx - s * .26, y0, cx + s * .26, y1], radius=max(2, int(s * .12)), outline=c, width=w)
            d.line([(cx - s * .08, y1 - s * .14), (cx + s * .08, y1 - s * .14)], fill=c, width=w)
        elif name == 'pin':
            d.ellipse([cx - s * .31, y0, cx + s * .31, y0 + s * .62], fill=c)
            d.polygon([(cx - s * .27, y0 + s * .46), (cx + s * .27, y0 + s * .46), (cx, y1)], fill=c)
            d.ellipse([cx - s * .11, y0 + s * .2, cx + s * .11, y0 + s * .42], fill=bg)
        elif name == 'bike':
            rw = s * .42
            lc = (x0 + rw / 2, y1 - rw / 2)
            rc = (x1 - rw / 2, y1 - rw / 2)
            d.ellipse([x0, y1 - rw, x0 + rw, y1], outline=c, width=w)
            d.ellipse([x1 - rw, y1 - rw, x1, y1], outline=c, width=w)
            top = (cx, y0 + s * .32)
            d.line([lc, top, rc], fill=c, width=w)
            d.line([top, (cx + s * .22, y0 + s * .12), (cx + s * .38, y0 + s * .12)], fill=c, width=w)
            d.line([lc, (cx - s * .1, y0 + s * .32), (cx - s * .2, y0 + s * .32)], fill=c, width=w)
        elif name == 'bag':
            d.rectangle([x0 + s * .1, y0 + s * .32, x1 - s * .1, y1], fill=c)
            d.arc([cx - s * .22, y0, cx + s * .22, y0 + s * .62], 180, 360, fill=c, width=w)
        elif name == 'cash':
            d.rounded_rectangle([x0, y0 + s * .2, x1, y1 - s * .2], radius=max(2, int(s * .08)), outline=c, width=w)
            d.ellipse([cx - s * .17, cy - s * .17, cx + s * .17, cy + s * .17], outline=c, width=w)
        elif name == 'note':
            d.rounded_rectangle([x0 + s * .14, y0, x1 - s * .14, y1], radius=max(2, int(s * .08)), outline=c, width=w)
            for k in (.28, .5, .72):
                d.line([(x0 + s * .3, y0 + s * k), (x1 - s * .3, y0 + s * k)], fill=c, width=max(1, w - 1))
        elif name == 'hash':
            for px in (.36, .64):
                d.line([(x0 + s * px, y0 + s * .05), (x0 + s * px, y1 - s * .05)], fill=c, width=w)
            for py in (.36, .64):
                d.line([(x0 + s * .05, y0 + s * py), (x1 - s * .05, y0 + s * py)], fill=c, width=w)
        elif name == 'tag':
            d.polygon([(x0, cy), (x0 + s * .35, y0 + s * .1), (x1, y0 + s * .1), (x1, y1 - s * .1), (x0 + s * .35, y1 - s * .1)], outline=c, width=w)
            d.ellipse([x0 + s * .3, cy - s * .08, x0 + s * .46, cy + s * .08], fill=c)
        elif name == 'check':
            d.line([(x0 + s * .1, cy), (cx - s * .1, y1 - s * .15), (x1 - s * .05, y0 + s * .15)], fill=c, width=w + 1)
        elif name == 'smile':
            d.ellipse([x0, y0, x1, y1], outline=c, width=w)
            for ex in (-.2, .2):
                d.ellipse([cx + s * ex - s * .05, cy - s * .2, cx + s * ex + s * .05, cy - s * .1], fill=c)
            d.arc([cx - s * .28, cy - s * .2, cx + s * .28, cy + s * .3], 20, 160, fill=c, width=w)
        elif name == 'utensils':
            d.line([(x0 + s * .22, y0), (x0 + s * .22, y1)], fill=c, width=w)
            for fx in (.08, .22, .36):
                d.line([(x0 + s * fx, y0), (x0 + s * fx, y0 + s * .32)], fill=c, width=max(1, w - 1))
            d.ellipse([x1 - s * .4, y0, x1 - s * .1, y0 + s * .5], fill=c)
            d.line([(x1 - s * .25, y0 + s * .45), (x1 - s * .25, y1)], fill=c, width=w)
        else:
            d.ellipse([cx - s * .15, cy - s * .15, cx + s * .15, cy + s * .15], fill=c)

    def printed_by(self, name):
        """سطر 'طبع بواسطة' في منتصف الإيصال مع أيقونة الطابعة"""
        self._room(60)
        f = self.F(20)
        t = f"طبع بواسطة: {name}"
        w = self.tw(t, f)
        ic_s = 22
        total = w + ic_s + 8
        cx = self.W / 2
        h = max(self.lh(f), ic_s)
        self.txt(t, cx - total / 2 + w / 2, self.y + (h - self.lh(f)) / 2, f, 'ma')
        self.icon('printer', cx + total / 2 - ic_s / 2, self.y + h / 2, ic_s)
        self.y += h + 8

    # ───────────────────────── تذكرة التحضير (تصميم المطبخ) ─────────────────────────
    def ticket_header(self, settings, badge_ar, badge_en=None, logo_sz=104, show_name=False):
        """ترويسة: الشعار أعلى اليسار، اسم المطعم في الوسط، شارة العنوان أعلى اليمين، ثم خط."""
        import io
        from PIL import Image

        def S(i):
            try:
                v = settings[i]
                return v if v not in (None, '') else None
            except Exception:
                return None

        self._room(240)
        top = self.y
        bf1, bf2 = self.F(30, True), self.F(21, True)
        badge_w = int(max(self.tw(badge_ar, bf1), self.tw(badge_en or '', bf2)) + 38)
        badge_h = self.lh(bf1) + (self.lh(bf2) if badge_en else 0) + 18
        row_h = max(logo_sz, badge_h)

        # الشعار (يسار) — لو لا يوجد شعار محفوظ يُرسم رمز الطاهي
        logo_w = logo_sz
        drawn = False
        blob = S(1)
        if blob:
            try:
                lg = Image.open(io.BytesIO(blob)).convert('RGB')
                lg.thumbnail((logo_sz, logo_sz), Image.Resampling.LANCZOS)
                self.img.paste(lg, (self.M, int(top + (row_h - lg.height) // 2)))
                logo_w = lg.width
                drawn = True
            except Exception as e:
                print(f"⚠️ خطأ في الشعار: {e}")
        if not drawn:
            self.icon('chef', self.M + logo_sz / 2, top + row_h / 2 - 14, 64)
            self.icon('utensils', self.M + logo_sz / 2, top + row_h / 2 + 34, 24)

        # الشارة (يمين)
        bx2 = self.W - self.M
        bx1 = bx2 - badge_w
        by = top + (row_h - badge_h) / 2
        self.d.rounded_rectangle([(bx1, by), (bx2, by + badge_h)], radius=14, fill=self.BLACK)
        self.txt(badge_ar, (bx1 + bx2) / 2, by + 8, bf1, 'ma', fill=self.WHITE)
        if badge_en:
            self.txt(badge_en, (bx1 + bx2) / 2, by + 8 + self.lh(bf1), bf2, 'ma', fill=self.WHITE)

        # اسم المطعم (وسط) — يظهر فقط لو show_name=True
        name = S(9) if show_name else None
        if name:
            al, ar_ = self.M + logo_w + 14, bx1 - 14
            aw = max(60, ar_ - al)
            f = self.fit(name, 42, True, aw, min_size=20)
            lines = self.wrap(name, f, aw) if self.tw(name, f) > aw else [name]
            hh = len(lines) * self.lh(f)
            yy = top + (row_h - hh) / 2
            for ln in lines:
                self.txt(ln, (al + ar_) / 2, yy, f, 'ma')
                yy += self.lh(f)
        self.y = top + row_h + 10
        self.hline(self.y, 'solid', 3)
        self.y += 16

    def slip_header(self, settings, number, number_label="رقم الطلب", logo_sz=100):
        """ترويسة إيصال التيك واي/الدليفري: الشعار يساراً، رقم الطلب كبير يميناً، واسم المتجر بينهما (يُقصَّر لو طويل)."""
        import io
        from PIL import Image

        def S(i):
            try:
                v = settings[i]
                return v if v not in (None, '') else None
            except Exception:
                return None

        fl, fn = self.F(24, True), self.F(74, True)
        bw = 150
        bh = self.lh(fl) + self.lh(fn) + 18
        row_h = max(bh, logo_sz)
        self._room(row_h + 80)
        top = self.y
        # مربع رقم الطلب (يمين)
        bx2 = self.W - self.M
        bx1 = bx2 - bw
        by = top + (row_h - bh) / 2
        self.d.rounded_rectangle([(bx1, by), (bx2, by + bh)], radius=18,
                                 fill=(236, 236, 236), outline=self.BLACK, width=3)
        self.txt(number_label, (bx1 + bx2) / 2, by + 8, fl, 'ma')
        self.txt(str(number), (bx1 + bx2) / 2, by + 8 + self.lh(fl), fn, 'ma')
        # العمود الأيسر: الشعار في الأعلى واسم المتجر أسفله مباشرة (يُقصَّر لو طويل)
        al, ar_ = self.M, bx1 - 12
        aw = max(60, ar_ - al)
        cx_l = (al + ar_) / 2
        name = S(9)
        nm, f, name_h = None, None, 0
        if name:
            f = self.fit(name, 32, True, aw, min_size=18)
            nm = str(name)
            if self.tw(nm, f) > aw:
                words = nm.split()
                while len(words) > 1 and self.tw(' '.join(words) + ' …', f) > aw:
                    words.pop()
                nm = ' '.join(words) + ' …'
                while len(nm) > 3 and self.tw(nm, f) > aw:
                    nm = nm[:-3].rstrip() + ' …'
            name_h = self.lh(f) + 4
        lsz = 80 if name else logo_sz
        lh_used, drawn = lsz, False
        blob = S(1)
        lg = None
        if blob:
            try:
                lg = Image.open(io.BytesIO(blob)).convert('RGB')
                lg.thumbnail((lsz, lsz), Image.Resampling.LANCZOS)
                lh_used, drawn = lg.height, True
            except Exception as e:
                print(f"⚠️ خطأ في الشعار: {e}")
                lg = None
        block_h = lh_used + name_h
        y_blk = top + max(0, (row_h - block_h) / 2)
        if lg is not None:
            self.img.paste(lg, (int(cx_l - lg.width / 2), int(y_blk)))
        else:
            self.icon('chef', cx_l, y_blk + lsz / 2, 60)
        if nm:
            self.txt(nm, cx_l, y_blk + lh_used + 4, f, 'ma')
        self.y = top + row_h + 10
        self.hline(self.y, 'double')
        self.y += 18

    def ticket_order_block(self, number, right_items, left_items, number_label="رقم الطلب"):
        """مربع رقم الطلب في المنتصف + بيانات (أيقونة، نص) على اليمين واليسار."""
        fl, fn = self.F(24, True), self.F(74, True)
        bw = 150
        bh = self.lh(fl) + self.lh(fn) + 18
        self._room(bh + 60)
        top = self.y
        cx = self.W / 2
        self.d.rounded_rectangle([(cx - bw / 2, top), (cx + bw / 2, top + bh)], radius=18,
                                 fill=(236, 236, 236), outline=self.BLACK, width=3)
        self.txt(number_label, cx, top + 8, fl, 'ma')
        self.txt(str(number), cx, top + 8 + self.lh(fl), fn, 'ma')
        side_w = (self.CW - bw) / 2 - 12

        def col(items, x_right):
            if not items:
                return
            fi = self.F(21, True)
            row_h = max(self.lh(fi), 24) + 16
            y0 = top + (bh - len(items) * row_h) / 2
            for i, (ic, t) in enumerate(items):
                yc = y0 + i * row_h + row_h / 2
                self.icon(ic, x_right - 12, yc, 24)
                f = self.fit(t, 20, True, side_w - 34, min_size=10)
                self.txt(t, x_right - 32, yc - self.lh(f) / 2, f, 'ra')

        col(right_items, self.W - self.M)
        col(left_items, cx - bw / 2 - 12)
        self.y = top + bh + 16

    def status_banner(self, text):
        """شريط حالة بإطار: رمز الطاهي يساراً والنص في الوسط ووجه مبتسم بعده."""
        f = self.F(34, True)
        bh = self.lh(f) + 34
        self._room(bh + 40)
        top = self.y
        self.d.rounded_rectangle([(self.M, top), (self.W - self.M, top + bh)], radius=16,
                                 fill=(236, 236, 236), outline=self.BLACK, width=3)
        f = self.fit(text, 34, True, self.CW - 190, min_size=18)
        self.icon('chef', self.M + 52, top + bh / 2, 58)
        ic_s = 36
        tw_ = self.tw(text, f)
        cxm = self.W / 2 + 28
        self.txt(text, cxm, top + (bh - self.lh(f)) / 2, f, 'ma')
        self.icon('smile', cxm - tw_ / 2 - ic_s / 2 - 10, top + bh / 2, ic_s)
        self.y = top + bh + 16

    def ticket_footer(self, right_text, left_text):
        """تذييل: أيقونة الطابعة + 'طباعة : المستخدم' يميناً، وعبارة الشكر يساراً."""
        self._room(70)
        top = self.y
        f1, f2 = self.F(20), self.F(22, True)
        h = max(self.lh(f1), self.lh(f2), 26)
        self.icon('printer', self.W - self.M - 13, top + h / 2, 26)
        f1 = self.fit(right_text, 20, False, self.CW * 0.5 - 34, min_size=13)
        self.txt(right_text, self.W - self.M - 34, top + (h - self.lh(f1)) / 2, f1, 'ra')
        f2 = self.fit(left_text, 22, True, self.CW * 0.48, min_size=13)
        self.txt(left_text, self.M, top + (h - self.lh(f2)) / 2, f2, 'la')
        self.y = top + h + 10

    def finish(self):
        """ينهي الإيصال (فاصل مزدوج) ويرجع الصورة النهائية مقصوصة"""
        self.hline(self.y, 'double')
        self.y += 16
        return self.img.crop((0, 0, self.W, self.y + 20))


# ═══════════════════════════════════════════════════════════════════════════════
#  محرك الطباعة الحرارية الموحّد (يُستخدم في: الفاتورة + تقرير المصروفات + تقرير الإجمالي)
#  - يقرأ المساحة القابلة للطباعة الفعلية من الدرايفر (أي طابعة حرارية 58/80mm)
#  - يضبط الهامش يمين = يسار بالنسبة لمنتصف الورقة الحقيقي
#  - يصغّر/يكبّر الصورة بجودة عالية لتناسب العرض بدون قص أي جزء
#  - يقسّم الصفحات عند سطر فارغ حتى لا يُقطع نص من المنتصف
# ═══════════════════════════════════════════════════════════════════════════════
THERMAL_SIDE_SAFETY_PX = 4          # هامش أمان إضافي (بكسل) من كل جانب، متساوٍ يمين ويسار
THERMAL_FORCE_PRINTABLE_DOTS = None  # لو الدرايفر يرجّع عرضاً خاطئاً ضع هنا عدد النقاط (مثلاً 576)
THERMAL_SHARPEN = True              # تحسين حدة النص بعد تغيير الحجم
THERMAL_BINARIZE = False            # True = أبيض/أسود حاد بالكامل (النص أحدّ، لكن الشعار/الصور تفقد التدرج)
THERMAL_BINARIZE_THRESHOLD = 170    # كلما زاد الرقم زاد سُمك الأسود


def _thermal_geometry(horz, physical_width=None, offset_x=0, safety=THERMAL_SIDE_SAFETY_PX):
    """يحسب (x_off, usable_w): موضع بداية الصورة وعرضها داخل المساحة القابلة للطباعة
    بحيث يكون الهامش يمين = يسار بالنسبة لمنتصف الورقة الفعلي.
    horz            : عرض المساحة القابلة للطباعة (HORZRES)
    physical_width  : عرض الورقة الكامل (PHYSICALWIDTH) إن توفر
    offset_x        : الهامش غير القابل للطباعة يسار (PHYSICALOFFSETX)"""
    horz = int(horz)
    if physical_width and int(physical_width) >= horz and offset_x is not None and offset_x >= 0:
        center = int(physical_width) / 2.0 - float(offset_x)   # منتصف الورقة داخل منطقة الطباعة
    else:
        center = horz / 2.0
    if not (0 < center < horz):
        center = horz / 2.0
    half = min(center, horz - center)                           # أقصى نصف عرض متماثل حول المنتصف
    usable = int(2 * half) - 2 * int(safety)
    usable = max(usable, 32)
    x_off = int(round(center - usable / 2.0))
    x_off = max(0, min(x_off, horz - usable))
    return x_off, usable


def _thermal_prepare_image(img, target_w):
    """يغيّر عرض الصورة إلى target_w بجودة عالية (LANCZOS + حدة اختيارية)."""
    from PIL import Image, ImageFilter
    if img.mode != 'RGB':
        img = img.convert('RGB')
    if img.width != target_w:
        new_h = max(1, int(round(img.height * target_w / float(img.width))))
        img = img.resize((target_w, new_h), Image.Resampling.LANCZOS)
        if THERMAL_SHARPEN:
            img = img.filter(ImageFilter.UnsharpMask(radius=0.9, percent=70, threshold=2))
    if THERMAL_BINARIZE:
        g = img.convert('L').point(lambda p: 255 if p > THERMAL_BINARIZE_THRESHOLD else 0)
        img = g.convert('RGB')
    return img


def _thermal_page_breaks(img, page_h, search_back=160):
    """يرجّع قائمة (بداية، نهاية) لكل صفحة، ويفضّل القطع عند سطر أبيض بالكامل."""
    g = img.convert('L')
    w, h = g.size
    breaks, sy = [], 0
    while sy < h:
        ey = min(sy + page_h, h)
        if ey < h:                                   # ليست الصفحة الأخيرة: ابحث عن سطر فارغ للقطع
            for yy in range(ey, max(sy + 60, ey - search_back), -1):
                if g.crop((0, yy - 1, w, yy)).getextrema()[0] >= 245:
                    ey = yy
                    break
        breaks.append((sy, ey))
        sy = ey
    return breaks


# ═══════════════════════════════════════════════════════════════════════════════
#  الطابعة الافتراضية للنظام: اختيار واحد (USB أو شبكة كما تظهر في ويندوز) يُستخدم لكل المستندات
#  (الفاتورة، التقارير، تذكرة الدور، الحجز، درج النقد). بدون اختيار → طابعة ويندوز الافتراضية.
#  الإعداد محفوظ في جدول printer_routes (الصف role='all') وفي الذاكرة _PRINTER_ROUTES.
# ═══════════════════════════════════════════════════════════════════════════════
PRINTER_DEFAULT_LABEL = "— طابعة ويندوز الافتراضية —"
_PRINTER_ROUTES = {}                 # {'all': {'printer': str}}
_PRINT_ERROR_HANDLER = [None]        # دالة يضبطها التطبيق لعرض تنبيه عند فشل الطباعة


def list_system_printers():
    """أسماء الطابعات المثبتة على الجهاز (USB + شبكة ويندوز)، بدون تكرار."""
    names = []
    try:
        flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS
        for p in win32print.EnumPrinters(flags):
            n = p[2]
            if n and n not in names:
                names.append(n)
    except Exception as e:
        print(f"⚠️ تعذّر جلب قائمة الطابعات: {e}")
    return names


def get_default_printer_name():
    """اسم طابعة ويندوز الافتراضية أو '' إن لم توجد."""
    try:
        return win32print.GetDefaultPrinter()
    except Exception:
        return ""


def get_printer_state(name):
    """يرجع (الحالة, النص) حيث الحالة ∈ ok / error / missing."""
    if not name:
        return "missing", "لا توجد طابعة"
    if name not in list_system_printers():
        return "missing", "غير مثبتة على هذا الجهاز"
    try:
        h = win32print.OpenPrinter(name)
        try:
            info = win32print.GetPrinter(h, 2)
        finally:
            win32print.ClosePrinter(h)
    except Exception as e:
        return "error", f"تعذّر الاتصال ({e})"
    st = info.get("Status", 0) or 0
    attrs = info.get("Attributes", 0) or 0
    if attrs & 0x00000400:  # WORK_OFFLINE
        return "error", "غير متصلة (Offline)"
    for bit, txt in [(0x80, "غير متصلة"), (0x10, "نفد الورق"), (0x8, "انحشار ورق"),
                     (0x400000, "الغطاء مفتوح"), (0x2, "خطأ بالطابعة"), (0x1000, "غير متاحة"),
                     (0x40, "مشكلة بالورق"), (0x100000, "تحتاج تدخل المستخدم")]:
        if st & bit:
            return "error", txt
    return "ok", "جاهزة"


def resolve_printer(role=None):
    """يرجع (اسم الطابعة، 1، True): الطابعة المختارة في الإعدادات لو متاحة، وإلا افتراضية ويندوز.
    (role موجود للتوافق مع الاستدعاءات القديمة — كل المستندات تستخدم نفس الطابعة)"""
    name = ((_PRINTER_ROUTES.get('all') or {}).get('printer') or '').strip()
    if name and name not in list_system_printers():
        print(f"⚠️ الطابعة المختارة '{name}' غير متاحة — سيتم استخدام الافتراضية")
        name = ""
    return (name or get_default_printer_name()), 1, True


# ── قائمة انتظار الطباعة (مثل ويندوز): عرض المستندات المعلّقة، إلغاء مستند، مسح الكل ──
_JOB_STATUS_TEXT = [
    (0x4, "جارٍ الحذف"), (0x2, "خطأ"), (0x400, "تحتاج تدخل المستخدم"), (0x40, "نفد الورق"),
    (0x20, "غير متصلة"), (0x1, "متوقف مؤقتاً"), (0x10, "جارٍ الطباعة"), (0x8, "جارٍ التحضير"),
    (0x80, "تمت الطباعة"), (0x800, "إعادة تشغيل"), (0x200, "محظور"),
]


def _job_status_text(status, pstatus=None):
    """يحوّل حالة مستند الطباعة إلى نص عربي."""
    parts = [txt for bit, txt in _JOB_STATUS_TEXT if (status or 0) & bit]
    if not parts:
        parts = [pstatus] if pstatus else ["في الانتظار"]
    return "، ".join(parts)


def list_print_jobs(name):
    """يرجع قائمة المستندات المعلّقة في طابعة: [{id, doc, user, status, pages, size_kb, time}]."""
    jobs = []
    if not name:
        return jobs
    try:
        h = win32print.OpenPrinter(name)
        try:
            for j in (win32print.EnumJobs(h, 0, -1, 2) or []):
                sub = j.get("Submitted")
                try:
                    tm = sub.strftime("%H:%M:%S") if sub else ""
                except Exception:
                    tm = ""
                total = j.get("TotalPages", 0) or 0
                done = j.get("PagesPrinted", 0) or 0
                jobs.append({
                    "id": j.get("JobId"),
                    "doc": j.get("pDocument") or "(بدون اسم)",
                    "user": j.get("pUserName") or "",
                    "status": _job_status_text(j.get("Status", 0), j.get("pStatus")),
                    "pages": f"{done}/{total}" if total else "-",
                    "size_kb": f"{max(1, round((j.get('Size', 0) or 0) / 1024))} KB",
                    "time": tm,
                })
        finally:
            win32print.ClosePrinter(h)
    except Exception as e:
        print(f"⚠️ تعذّر قراءة قائمة الانتظار: {e}")
    return jobs


def _open_printer_admin(name):
    """يفتح الطابعة بصلاحية الإدارة (للإلغاء/المسح) وإن لم تتوفر يفتحها بصلاحية الاستخدام."""
    try:
        return win32print.OpenPrinter(name, {"DesiredAccess": win32print.PRINTER_ALL_ACCESS})
    except Exception:
        return win32print.OpenPrinter(name)


def cancel_print_job(name, job_id):
    """يلغي مستنداً واحداً من قائمة الانتظار."""
    h = _open_printer_admin(name)
    try:
        win32print.SetJob(h, job_id, 0, None, win32print.JOB_CONTROL_DELETE)
    finally:
        win32print.ClosePrinter(h)


def purge_print_queue(name):
    """يمسح كل المستندات المعلّقة في الطابعة."""
    h = _open_printer_admin(name)
    try:
        win32print.SetPrinter(h, 0, None, win32print.PRINTER_CONTROL_PURGE)
    finally:
        win32print.ClosePrinter(h)


def _build_test_image(title, printer_name, width=576):
    """صورة صفحة تجربة صغيرة (عربي) لاختبار طابعة من نافذة الإعدادات."""
    from PIL import ImageFont
    font_path = None
    for c in ["tahomabd.ttf", "C:/Windows/Fonts/tahomabd.ttf", "arialbd.ttf", "C:/Windows/Fonts/arialbd.ttf",
              "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"]:
        try:
            ImageFont.truetype(c, 20)
            font_path = c
            break
        except Exception:
            continue

    def F(sz):
        try:
            return ImageFont.truetype(font_path, sz)
        except Exception:
            return ImageFont.load_default()

    def ar(t):
        try:
            return get_display(arabic_reshaper.reshape(t))
        except Exception:
            return t

    img = Image.new("RGB", (width, 330), "white")
    d = ImageDraw.Draw(img)
    y = 20
    for txt, sz in ((ar("صفحة تجربة الطباعة"), 34), (ar(title), 28), (printer_name or "-", 22),
                    (datetime.now().strftime("%Y-%m-%d %I:%M %p"), 22)):
        f = F(sz)
        w = d.textlength(txt, font=f)
        d.text(((width - w) / 2, y), txt, font=f, fill="black")
        y += sz + 22
    d.rectangle((6, 6, width - 7, y + 10), outline="black", width=2)
    return img.crop((0, 0, width, y + 30))


def _print_pil_image(img, job_name="Report", printer_name=None, role=None):
    """يطبع صورة PIL على الطابعة المختارة في الإعدادات (لكل المستندات). عند الفشل يظهر تنبيه للكاشير."""
    if not printer_name:
        printer_name = resolve_printer()[0]
    try:
        _print_pil_image_once(img, job_name, printer_name)
    except Exception as e:
        msg = f"فشلت الطباعة على «{printer_name}»:\n{e}"
        print(f"❌ {msg}")
        h = _PRINT_ERROR_HANDLER[0]
        if h:
            try:
                h(msg)
            except Exception:
                pass
        raise



def _print_pil_image_blocking(img, job_name="Report", printer_name=None):
    """يطبع صورة PIL مرة واحدة على أي طابعة حرارية (الافتراضية أو المحددة) بهوامش متساوية وجودة عالية.
    دالة حاجبة: تُنادى فقط من خيط خلفي (لا من خيط الواجهة أبدًا)."""
    import win32print
    import win32ui
    import win32con
    from PIL import ImageWin

    printer_name = printer_name or win32print.GetDefaultPrinter()
    hdc = win32ui.CreateDC()
    try:
        hdc.CreatePrinterDC(printer_name)
        horz = hdc.GetDeviceCaps(win32con.HORZRES)
        vert = hdc.GetDeviceCaps(win32con.VERTRES)
        phys_w = hdc.GetDeviceCaps(getattr(win32con, 'PHYSICALWIDTH', 110))
        off_x = hdc.GetDeviceCaps(getattr(win32con, 'PHYSICALOFFSETX', 112))

        if THERMAL_FORCE_PRINTABLE_DOTS:
            horz, phys_w, off_x = int(THERMAL_FORCE_PRINTABLE_DOTS), None, 0

        x_off, usable_w = _thermal_geometry(horz, phys_w, off_x)
        img = _thermal_prepare_image(img, usable_w)
        w_, h_ = img.size
        print(f"🖨️ {printer_name} | منطقة الطباعة={horz} | عرض الورق={phys_w} | "
              f"هامش غير مطبوع يسار={off_x} | عرض الصورة={usable_w} | بداية={x_off}")

        hdc.StartDoc(job_name)
        for sy, ey in _thermal_page_breaks(img, vert):
            hdc.StartPage()
            dib = ImageWin.Dib(img.crop((0, sy, w_, ey)))
            dib.draw(hdc.GetHandleOutput(), (x_off, 0, x_off + w_, ey - sy))
            hdc.EndPage()
        hdc.EndDoc()
    finally:
        try:
            hdc.DeleteDC()
        except Exception:
            pass


def _print_pil_image_once(img, job_name="Report", printer_name=None, timeout=30):
    """يطبع في خيط خلفي، وتبقى الواجهة حيّة أثناء الانتظار.
    إذا لم تستجب الطابعة خلال timeout ثانية يرفع خطأ بدل التجمّد."""
    box = {"err": None, "done": False}

    def _worker():
        try:
            _print_pil_image_blocking(img, job_name, printer_name)
        except Exception as e:
            box["err"] = e
        finally:
            box["done"] = True

    t = threading.Thread(target=_worker, daemon=True)
    t.start()

    root = getattr(tk, "_default_root", None)
    start = time.time()
    while not box["done"]:
        if time.time() - start > timeout:
            raise RuntimeError(
                f"الطابعة «{printer_name or 'الافتراضية'}» لا تستجيب (أكثر من {timeout} ثانية).\n"
                "تأكد من توصيلها وتشغيلها، أو امسح طابور الطباعة من إعدادات الويندوز.")
        try:
            if root:
                root.update()
        except Exception:
            pass
        time.sleep(0.03)

    if box["err"]:
        raise box["err"]


# ═══════════════════════════════════════════════════════════════════════════════
#  طابعة المطبخ بالـIP (تذكرة التحضير): إرسال مباشر لطابعة حرارية شبكية عبر المنفذ 9100 بأوامر ESC/POS
#  - لا تحتاج تعريفاً في ويندوز، وتعمل من أي جهاز كاشير على نفس الشبكة.
#  - الإعداد محفوظ في جدول printer_routes (الصف role='kitchen') وفي الذاكرة _PRINTER_ROUTES['kitchen'].
#  - لو فشل الاتصال تُطبع التذكرة على الطابعة الرئيسية مع تنبيه للكاشير (حتى لا يضيع الطلب).
# ═══════════════════════════════════════════════════════════════════════════════
KITCHEN_PRINTER_WIDTH_DOTS = 576      # 80mm = 576 نقطة (لو الطابعة 512 نقطة غيّر الرقم)
KITCHEN_PRINTER_TIMEOUT = 4           # ثواني للاتصال/الإرسال
KITCHEN_PRINTER_AUTOCUT = True        # قص الورق بعد كل تذكرة


def _safe_port(v, default=9100):
    """يحوّل قيمة المنفذ إلى رقم صحيح (أو الافتراضي لو غير صالحة)"""
    try:
        v = int(str(v).strip())
        return v if 0 < v < 65536 else default
    except Exception:
        return default


def get_kitchen_printer_cfg():
    """إعداد طابعة المطبخ: {'enabled': bool, 'host': str, 'port': int}"""
    c = _PRINTER_ROUTES.get('kitchen') or {}
    try:
        port = int(c.get('port') or 9100)
    except Exception:
        port = 9100
    return {'enabled': bool(c.get('enabled')), 'host': (c.get('host') or '').strip(), 'port': port}


def _image_to_escpos(img, width_dots=KITCHEN_PRINTER_WIDTH_DOTS, cut=KITCHEN_PRINTER_AUTOCUT):
    """يحوّل صورة PIL إلى أوامر ESC/POS (صورة نقطية GS v 0) جاهزة للإرسال لطابعة حرارية."""
    from PIL import Image
    width_dots = (int(width_dots) // 8) * 8
    if img.mode != 'RGB':
        img = img.convert('RGB')
    if img.width != width_dots:
        h = max(1, int(round(img.height * width_dots / float(img.width))))
        img = img.resize((width_dots, h), Image.Resampling.LANCZOS)
    g = img.convert('L').point(lambda p: 255 if p > 200 else 0)      # أبيض/أسود حاد (الرمادي الفاتح يصير أبيض)
    bw = g.convert('1', dither=Image.Dither.NONE) if hasattr(Image, 'Dither') else g.convert('1')
    wbytes = width_dots // 8
    out = bytearray(b'\x1b\x40')                                     # ESC @ تهيئة الطابعة
    step = 200                                                       # شرائح صغيرة لتناسب ذاكرة الطابعة
    for y in range(0, bw.height, step):
        strip = bw.crop((0, y, width_dots, min(bw.height, y + step)))
        sh = strip.height
        raw = bytes(b ^ 0xFF for b in strip.tobytes())               # في ESC/POS الـ1 = نقطة سوداء
        out += b'\x1d\x76\x30\x00' + bytes([wbytes & 255, wbytes >> 8, sh & 255, sh >> 8]) + raw
    out += b'\x1b\x64\x04'                                          # تغذية 4 أسطر
    if cut:
        out += b'\x1d\x56\x42\x00'                                 # قص الورق
    return bytes(out)


def send_raw_to_ip(host, port, data, timeout=KITCHEN_PRINTER_TIMEOUT):
    """يرسل بايتات خام لطابعة شبكية (TCP). يرفع استثناءً عند الفشل."""
    import socket
    with socket.create_connection((host, int(port)), timeout=timeout) as sock:
        sock.settimeout(timeout)
        sock.sendall(data)
        try:
            sock.shutdown(socket.SHUT_WR)
        except Exception:
            pass


def print_image_to_ip(img, host, port=9100, job_name="Kitchen"):
    """يطبع صورة PIL على طابعة شبكية بالـIP مباشرة."""
    host = (host or '').strip()
    if not host:
        raise ValueError("لم يتم إدخال عنوان IP للطابعة")
    send_raw_to_ip(host, port, _image_to_escpos(img))
    print(f"🖨️ {job_name} ← {host}:{port}")


def test_ip_printer(host, port=9100, timeout=3):
    """يختبر إمكانية الاتصال بالطابعة: يرجع (نجح؟، رسالة بالعربي)."""
    import socket
    host = (host or '').strip()
    if not host:
        return False, "أدخل عنوان IP أولاً"
    try:
        with socket.create_connection((host, int(port)), timeout=timeout):
            return True, "الاتصال ناجح"
    except socket.timeout:
        return False, "انتهت مهلة الاتصال — تأكد من العنوان وأن الطابعة تعمل على نفس الشبكة"
    except ConnectionRefusedError:
        return False, "رفضت الطابعة الاتصال — تأكد من رقم المنفذ (الغالب 9100)"
    except Exception as e:
        return False, f"تعذّر الاتصال: {e}"


def _print_kitchen_image(img, job_name="Kitchen"):
    """يطبع تذكرة التحضير: على طابعة المطبخ (IP) لو مفعّلة، وإلا (أو عند الفشل) على الطابعة الرئيسية."""
    cfg = get_kitchen_printer_cfg()
    if cfg['enabled'] and cfg['host']:
        try:
            print_image_to_ip(img, cfg['host'], cfg['port'], job_name)
            return
        except Exception as e:
            msg = (f"تعذّرت الطباعة على طابعة المطبخ ({cfg['host']}:{cfg['port']}):\n{e}\n"
                   f"سيتم طباعة التذكرة على الطابعة الرئيسية.")
            print(f"❌ {msg}")
            h = _PRINT_ERROR_HANDLER[0]
            if h:
                try:
                    h(msg)
                except Exception:
                    pass
    _print_pil_image(img, job_name, role="invoice")


def make_circular_photo(blob, size=40, border="#E2E8F0"):
    """يحوّل صورة (bytes) إلى PhotoImage دائرية بحواف ناعمة، أو None لو فشل/لا توجد صورة."""
    if not blob:
        return None
    try:
        S = 4  # رسم بدقة أعلى ثم تصغير لحواف ناعمة
        im = Image.open(io.BytesIO(blob)).convert("RGBA")
        m = min(im.size)
        im = im.crop(((im.width - m) // 2, (im.height - m) // 2,
                      (im.width + m) // 2, (im.height + m) // 2)).resize((size * S, size * S), Image.LANCZOS)
        mask = Image.new("L", (size * S, size * S), 0)
        ImageDraw.Draw(mask).ellipse((0, 0, size * S - 1, size * S - 1), fill=255)
        out = Image.new("RGBA", (size * S, size * S), (0, 0, 0, 0))
        out.paste(im, (0, 0), mask)
        ImageDraw.Draw(out).ellipse((0, 0, size * S - 1, size * S - 1), outline=border, width=S * 2)
        return ImageTk.PhotoImage(out.resize((size, size), Image.LANCZOS))
    except Exception as e:
        print(f"خطأ في تجهيز الصورة الدائرية: {e}")
        return None


# ═══════════════════════════════════════════════════════════════════════════════
#  مديول الدليفري والتيك واي (DeliveryMixin)
#  ─────────────────────────────────────────────────────────────────────────────
#  الفكرة: كل طلب دليفري/تيك واي = صف في pos_orders + فاتورة معلقة برمز DLV-<id> / TKW-<id>
#  (نفس أسلوب الطاولات TBL-). فتبقى التبويبات والحفظ في القاعدة والدفع كما هي.
#
#  القواعد المحاسبية:
#   - رسم التوصيل يُحسب فقط لطلب «دليفري» من منطقة التوصيل، ويُحفظ في invoices.delivery_fee
#     منفصلاً (total_amount يظل شاملاً الرسم كما كان، فلا تتأثر التقارير القديمة).
#   - العمولات تُحسب على قيمة المنتجات بدون رسم التوصيل.
#   - الأوقات كلها بتوقيت سيرفر القاعدة (NOW()) والعداد يُحسب منها، فيتطابق بين الأجهزة.
#   - السائق = موظف وظيفته مصنَّفة «سائق توصيل» في job_types.job_kind (اختيار من قائمة، لا كتابة).
#   - حالة السائق (متاح/في توصيلة) تُشتق من الطلبات نفسها، فلا تتعارض أو تعلق.
# ═══════════════════════════════════════════════════════════════════════════════
DLV_PREFIX = "DLV-"
TKW_PREFIX = "TKW-"
DLV_ACTIVE = ('preparing', 'ready', 'out')
DLV_STATUS_AR = {
    'preparing': 'قيد التحضير', 'ready': 'جاهز', 'out': 'في الطريق',
    'done': 'مكتمل', 'cancelled': 'ملغي', 'failed': 'فشل التوصيل',
}
DLV_JOB_KINDS = {'': 'عادي', 'driver': 'سائق توصيل'}


# ═══════════════════════════════════════════════════════════════════════════════
#  خدمة الموقع والخريطة للدليفري
#  كل ما في هذا القسم يعمل في خيط خلفي: لا يلمس واجهة Tk ولا قاعدة البيانات أبداً،
#  لذلك لا تتجمد النوافذ أثناء البحث عن العنوان أو حساب المسار أو تحميل الخريطة.
#  النتائج تعود للواجهة عبر طابور (queue) وتُقرأ من الخيط الرئيسي.
# ═══════════════════════════════════════════════════════════════════════════════
import urllib.parse as _urlparse
import queue as _queue

_DLV_UA = "CodeTechPOS-Delivery/2.0"
_DLV_TILE_URL = "https://tile.openstreetmap.org/{z}/{x}/{y}.png"
_DLV_OSRM_URL = "https://router.project-osrm.org/route/v1/driving/{a_lng:.6f},{a_lat:.6f};{b_lng:.6f},{b_lat:.6f}"

# أنماط استخراج الإحداثيات من روابط جوجل. الأول (!3d..!4d) هو دبوس المكان الفعلي،
# والثاني (@..) مركز الشاشة فقط، لذلك الترتيب مهم. الأخير: نص إحداثيات خام «30.12, 31.23».
_DLV_COORD_PATTERNS = [
    r'!3d(-?\d{1,3}\.\d+)!4d(-?\d{1,3}\.\d+)',
    r'@(-?\d{1,3}\.\d+),(-?\d{1,3}\.\d+)',
    r'[?&](?:q|ll|query|destination|daddr|center|sll|viewpoint)=\+?(-?\d{1,3}\.\d+)\s*,\s*\+?(-?\d{1,3}\.\d+)',
    r'\[null,null,(-?\d{1,3}\.\d+),(-?\d{1,3}\.\d+)\]',
    r'^\s*(-?\d{1,3}\.\d+)\s*[,،;\s]\s*(-?\d{1,3}\.\d+)\s*$',
]


def _dlv_valid_ll(lat, lng):
    try:
        lat, lng = float(lat), float(lng)
    except (TypeError, ValueError):
        return None
    if -90 <= lat <= 90 and -180 <= lng <= 180 and not (lat == 0 and lng == 0):
        return lat, lng
    return None


def _dlv_parse_coords(text, bare=True):
    """يستخرج (lat, lng) من رابط جوجل ماب أو من نص إحداثيات. None لو لا يوجد.
    bare=False يتجاهل نمط «إحداثيات خام في سطر» (يُستخدم عند فحص صفحات HTML)."""
    if not text:
        return None
    t = _urlparse.unquote(str(text))
    pats = _DLV_COORD_PATTERNS if bare else _DLV_COORD_PATTERNS[:4]
    for p in pats:
        m = re.search(p, t, re.M)
        if m:
            ll = _dlv_valid_ll(m.group(1), m.group(2))
            if ll:
                return ll
    return None


def _dlv_extract_url(text):
    m = re.search(r'https?://[^\s"\'<>]+', str(text or ''))
    return m.group(0) if m else None


def _dlv_place_from_url(url):
    m = re.search(r'/maps/place/([^/@?]+)', str(url or ''))
    if not m:
        return None
    name = _urlparse.unquote(m.group(1)).replace('+', ' ').strip()
    return name or None


def _dlv_haversine(a, b):
    p1, p2 = math.radians(a[0]), math.radians(b[0])
    dphi, dl = p2 - p1, math.radians(b[1] - a[1])
    h = math.sin(dphi / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * 6371.0 * math.asin(min(1.0, math.sqrt(h)))


import bisect as _bisect


def _dlv_tint(color, t=0.88):
    """نسخة فاتحة من اللون (خلفيات ناعمة للشارات والأزرار)."""
    return _mix(color, "#FFFFFF", t)


def _dlv_path_cum(path):
    """المسافات التراكمية (كم) على طول المسار."""
    cum = [0.0]
    for i in range(1, len(path)):
        cum.append(cum[-1] + _dlv_haversine(path[i - 1], path[i]))
    return cum


def _dlv_path_at(path, cum, frac):
    """نقطة على المسار عند نسبة frac (0..1) → (النقطة, فهرس القطعة, هل الاتجاه شرقاً؟)."""
    if not path:
        return None, 0, True
    if len(path) == 1 or cum[-1] <= 0:
        return (path[0][0], path[0][1]), 0, True
    frac = min(max(float(frac), 0.0), 1.0)
    target = cum[-1] * frac
    i = min(max(_bisect.bisect_right(cum, target) - 1, 0), len(path) - 2)
    seg = cum[i + 1] - cum[i]
    t = 0.0 if seg <= 0 else (target - cum[i]) / seg
    a, b = path[i], path[i + 1]
    return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t), i, (b[1] >= a[1])


def _dlv_bind_map_click(mw, callback, tol=7, max_secs=1.2):
    """نقرة يسار على خريطة tkintermapview تتحمّل اهتزاز الفأرة.
    المكتبة نفسها لا تعتبرها نقرة إلا لو الفأرة لم تتحرك ولا بكسل واحد بين الضغط والإفلات،
    وبعد الزوم بعجلة الفأرة أو مع لوحة اللمس يحدث ذلك كثيراً فلا يُحدَّد الموقع."""
    st = {'x': None, 'y': None, 't': 0.0}

    def down(ev):
        st['x'], st['y'], st['t'] = ev.x, ev.y, time.time()

    def up(ev):
        if st['x'] is None:
            return
        moved = max(abs(ev.x - st['x']), abs(ev.y - st['y']))
        fast = (time.time() - st['t']) <= max_secs
        st['x'] = None
        if moved <= tol and fast:
            try:
                c = mw.convert_canvas_coords_to_decimal_coords(ev.x, ev.y)
                callback(c)
            except Exception as e:
                print(f"تعذر تحديد النقطة من الخريطة: {e}")

    mw.canvas.bind("<ButtonPress-1>", down, add="+")
    mw.canvas.bind("<ButtonRelease-1>", up, add="+")


def _dlv_glyph_pil(kind, N, color):
    """أيقونة بسيطة شفافة N×N (PIL RGBA)."""
    im = Image.new("RGBA", (N, N), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    c = _hex_rgb(color) + (255,)
    k = lambda v: int(N * v)
    if kind == "scooter":
        d.rounded_rectangle((k(.04), k(.26), k(.36), k(.52)), radius=k(.05), fill=c)      # صندوق التوصيل
        d.rounded_rectangle((k(.20), k(.55), k(.76), k(.64)), radius=k(.04), fill=c)      # أرضية الدراجة
        d.line((k(.80), k(.74), k(.70), k(.26)), fill=c, width=k(.07))                    # الشوكة
        d.line((k(.60), k(.22), k(.84), k(.22)), fill=c, width=k(.07))                    # المقود
        for wx in (.20, .80):
            wr = k(.13)
            d.ellipse((k(wx) - wr, k(.76) - wr, k(wx) + wr, k(.76) + wr), outline=c, width=k(.06))
    elif kind == "bag":
        d.rounded_rectangle((k(.18), k(.34), k(.82), k(.90)), radius=k(.09), fill=c)
        d.arc((k(.33), k(.10), k(.67), k(.56)), 180, 360, fill=c, width=k(.06))
        d.arc((k(.33), k(.10), k(.67), k(.56)), 0, 180, fill=c, width=k(.06))
    elif kind == "orders":
        d.rounded_rectangle((k(.18), k(.12), k(.82), k(.90)), radius=k(.08), outline=c, width=k(.06))
        d.rounded_rectangle((k(.36), k(.06), k(.64), k(.20)), radius=k(.04), fill=c)
        for yy in (.34, .50, .66):
            d.rounded_rectangle((k(.30), k(yy), k(.70), k(yy + .07)), radius=k(.03), fill=c)
    elif kind == "receipt":
        d.polygon([(k(.22), k(.10)), (k(.78), k(.10)), (k(.78), k(.88)), (k(.695), k(.80)),
                   (k(.61), k(.88)), (k(.525), k(.80)), (k(.44), k(.88)), (k(.355), k(.80)),
                   (k(.27), k(.88)), (k(.22), k(.82))], fill=c)
        for yy in (.24, .37, .50, .63):
            d.rectangle((k(.32), k(yy), k(.68), k(yy + .05)), fill=(0, 0, 0, 0))
    elif kind == "user":
        d.ellipse((k(.34), k(.10), k(.66), k(.42)), fill=c)
        d.pieslice((k(.16), k(.50), k(.84), k(1.14)), 180, 360, fill=c)
    elif kind == "clock":
        d.ellipse((k(.12), k(.12), k(.88), k(.88)), outline=c, width=k(.09))
        d.line((k(.50), k(.50), k(.50), k(.28)), fill=c, width=k(.08))
        d.line((k(.50), k(.50), k(.68), k(.60)), fill=c, width=k(.08))
    elif kind == "pin":
        d.ellipse((k(.22), k(.06), k(.78), k(.62)), fill=c)
        d.polygon([(k(.29), k(.48)), (k(.71), k(.48)), (k(.50), k(.94))], fill=c)
        d.ellipse((k(.39), k(.23), k(.61), k(.45)), fill=(0, 0, 0, 0))
    elif kind == "store":
        d.polygon([(k(.08), k(.40)), (k(.20), k(.14)), (k(.80), k(.14)), (k(.92), k(.40))], fill=c)
        d.rounded_rectangle((k(.16), k(.46), k(.84), k(.88)), radius=k(.04), fill=c)
        d.rounded_rectangle((k(.42), k(.60), k(.58), k(.88)), radius=k(.02), fill=(0, 0, 0, 0))
    elif kind == "check":
        d.ellipse((k(.10), k(.10), k(.90), k(.90)), outline=c, width=k(.08))
        d.line((k(.30), k(.52), k(.45), k(.67), k(.72), k(.35)), fill=c, width=k(.09), joint="curve")
    elif kind == "cross":
        d.ellipse((k(.10), k(.10), k(.90), k(.90)), outline=c, width=k(.08))
        d.line((k(.34), k(.34), k(.66), k(.66)), fill=c, width=k(.09))
        d.line((k(.66), k(.34), k(.34), k(.66)), fill=c, width=k(.09))
    elif kind == "timer":
        d.ellipse((k(.14), k(.22), k(.86), k(.94)), outline=c, width=k(.08))
        d.rectangle((k(.42), k(.04), k(.58), k(.14)), fill=c)
        d.line((k(.50), k(.58), k(.50), k(.38)), fill=c, width=k(.08))
        d.line((k(.50), k(.58), k(.64), k(.66)), fill=c, width=k(.08))
    elif kind == "hourglass":
        d.polygon([(k(.24), k(.10)), (k(.76), k(.10)), (k(.52), k(.50)), (k(.76), k(.90)),
                   (k(.24), k(.90)), (k(.48), k(.50))], outline=c, width=k(.07))
        d.polygon([(k(.34), k(.78)), (k(.66), k(.78)), (k(.50), k(.60))], fill=c)
        d.line((k(.20), k(.10), k(.80), k(.10)), fill=c, width=k(.07))
        d.line((k(.20), k(.90), k(.80), k(.90)), fill=c, width=k(.07))
    elif kind == "cash":
        d.rounded_rectangle((k(.06), k(.26), k(.94), k(.74)), radius=k(.07), outline=c, width=k(.07))
        d.ellipse((k(.36), k(.36), k(.64), k(.64)), fill=c)
        d.ellipse((k(.14), k(.44), k(.22), k(.56)), fill=c)
        d.ellipse((k(.78), k(.44), k(.86), k(.56)), fill=c)
    elif kind == "alert":
        d.polygon([(k(.50), k(.08)), (k(.94), k(.88)), (k(.06), k(.88))], outline=c, width=k(.07))
        d.line((k(.50), k(.38), k(.50), k(.62)), fill=c, width=k(.08))
        d.ellipse((k(.45), k(.70), k(.55), k(.80)), fill=c)
    return im


def _dlv_badge_pil(kind, size, fg, tint):
    """شارة مربعة بحواف مدوّرة بخلفية فاتحة وأيقونة ملوّنة (للمؤشرات وصور العملاء)."""
    S = 4
    N = size * S
    im = Image.new("RGBA", (N, N), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rounded_rectangle((0, 0, N - 1, N - 1), radius=int(N * 0.30), fill=_hex_rgb(tint) + (255,))
    g = _dlv_glyph_pil(kind, int(N * 0.56), fg)
    off = (N - g.width) // 2
    im.alpha_composite(g, (off, off))
    return im.resize((size, size), Image.LANCZOS)


def _dlv_round_marker_pil(glyph, color, size=44, flip=False):
    """دبوس دائري على الخريطة (أسلوب أوبر): حلقة بيضاء + دائرة ملوّنة + أيقونة بيضاء + ظل خفيف."""
    from PIL import ImageOps
    S = 4
    N = size * S
    im = Image.new("RGBA", (N, N), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    pad, off = int(N * 0.06), int(N * 0.03)
    d.ellipse((pad, pad + off, N - pad, N - pad + off), fill=(0, 0, 0, 60))
    d.ellipse((pad, pad, N - pad, N - pad), fill=(255, 255, 255, 255))
    r2 = int(N * 0.15)
    d.ellipse((r2, r2, N - r2, N - r2), fill=_hex_rgb(color) + (255,))
    g = _dlv_glyph_pil(glyph, int(N * 0.52), "#FFFFFF")
    o2 = (N - g.width) // 2
    im.alpha_composite(g, (o2, o2))
    if flip:
        im = ImageOps.mirror(im)
    return im.resize((size, size), Image.LANCZOS)


def _dlv_throttle(state, gap=1.1):
    """سياسة Nominatim: طلب واحد كحد أقصى كل ثانية."""
    if state is None:
        return
    wait = state.get('last', 0.0) + gap - time.time()
    if wait > 0:
        time.sleep(wait)
    state['last'] = time.time()


_DLV_BROWSER_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
                   "Chrome/124.0.0.0 Safari/537.36")
_DLV_BROWSER_HDR = {'User-Agent': _DLV_BROWSER_UA, 'Accept-Language': 'en-US,en;q=0.9',
                    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'}
_DLV_HTML_PATTERNS = [
    (r'!3d(-?\d{1,3}\.\d+)!4d(-?\d{1,3}\.\d+)', False),
    (r'!2d(-?\d{1,3}\.\d+)!3d(-?\d{1,3}\.\d+)', True),
    (r'@(-?\d{1,3}\.\d+),(-?\d{1,3}\.\d+)', False),
    (r'[?&;](?:q|ll|query|destination|daddr|center|sll|viewpoint)=\+?(-?\d{1,3}\.\d+)\s*,\s*\+?(-?\d{1,3}\.\d+)', False),
    (r'\[null,null,(-?\d{1,3}\.\d+),(-?\d{1,3}\.\d+)\]', False),
    (r'"lat(?:itude)?"\s*:\s*(-?\d{1,3}\.\d+)\s*,\s*"l(?:ng|on|ongitude)"\s*:\s*(-?\d{1,3}\.\d+)', False),
    (r'data-lat="(-?\d{1,3}\.\d+)"[^>]*data-l(?:ng|on)="(-?\d{1,3}\.\d+)"', False),
    (r'center=(-?\d{1,3}\.\d+)%2C(-?\d{1,3}\.\d+)', False),
    (r'APP_INITIALIZATION_STATE=\[\[\[[\d.\-e]+,(-?\d{1,3}\.\d+),(-?\d{1,3}\.\d+)', True),
    (r'\[\[\[[\d.]+,(-?\d{1,3}\.\d{4,}),(-?\d{1,3}\.\d{4,})\]', True),
]


def _dlv_parse_html_coords(text):
    if not text:
        return None
    t = str(text).replace('\\u003d', '=').replace('\\u0026', '&').replace('\\x3d', '=').replace('\\x26', '&')
    t = _urlparse.unquote(t.replace('&amp;', '&'))
    for pat, swap in _DLV_HTML_PATTERNS:
        m = re.search(pat, t)
        if m:
            a, b = m.group(1), m.group(2)
            ll = _dlv_valid_ll(b, a) if swap else _dlv_valid_ll(a, b)
            if ll:
                return ll
    return None


def _dlv_name_from_html(url, html):
    """اسم المكان من رابط بحث جوجل (q=) أو من عنوان الصفحة، ليُبحث عنه كخطة بديلة."""
    try:
        q = _urlparse.parse_qs(_urlparse.urlparse(url).query).get('q')
        if q and q[0].strip() and not _dlv_parse_coords(q[0]):
            return q[0].strip()
    except Exception:
        pass
    m = re.search(r'<meta[^>]+property="og:title"[^>]+content="([^"]+)"', html or '')
    if not m:
        m = re.search(r'<title>([^<]{3,150})</title>', html or '')
    if m:
        t = re.sub(r'\s*[-–|]\s*(Google Maps|خرائط Google|Google).*$', '', m.group(1)).strip()
        if t and t.lower() not in ('google maps', 'google', 'before you continue to google', 'google search'):
            return t
    return None


def _dlv_resolve_map_link(sess, text):
    """رابط جوجل (طويل أو مختصر: maps.app.goo.gl / goo.gl / share.google) أو إحداثيات
    → {'lat','lng','name'} أو None. يرسل هوية متصفح عادي، ويتخطى صفحة الموافقة،
    ويجرب cid/ftid، وأخيراً يبحث باسم المكان في خرائط جوجل نفسه ثم في OSM."""
    ll = _dlv_parse_coords(text)
    name = _dlv_place_from_url(text)
    if ll:
        return {'lat': ll[0], 'lng': ll[1], 'name': name}
    url = _dlv_extract_url(text)
    if not url:
        return None
    try:
        sess.cookies.set('CONSENT', 'YES+cb', domain='.google.com')
        sess.cookies.set('SOCS', 'CAI', domain='.google.com')
    except Exception:
        pass
    html, final, ll = '', url, None
    tried = set()
    for _hop in range(5):
        tried.add(url)
        r = sess.get(url, headers=_DLV_BROWSER_HDR, allow_redirects=True, timeout=15)
        final = r.url or url
        sess._dlv_dbg = f"{r.status_code} {_urlparse.urlparse(final).netloc}{_urlparse.urlparse(final).path[:30]}"
        html = (r.text or '')[:1200000]
        chain = [h.headers.get('Location', '') for h in r.history] + [final]
        for u in chain:
            ll = _dlv_parse_coords(u, bare=False)
            if ll:
                break
        if ll:
            break
        name = name or _dlv_place_from_url(final)
        ll = _dlv_parse_html_coords(html)
        if ll:
            break
        nxt = None
        qs = _urlparse.parse_qs(_urlparse.urlparse(final).query)
        if 'consent.google' in final or 'consent.youtube' in final:
            cont = qs.get('continue')
            nxt = cont[0] if cont else None
        if not nxt:
            m = (re.search(r'(?:cid|ludocid)=(\d{8,25})', final + ' ' + html[:200000])
                 or re.search(r'ftid=(0x[0-9a-f]+:0x[0-9a-f]+)', final + ' ' + html[:200000]))
            if m:
                nxt = ('https://www.google.com/maps?cid=' + m.group(1)) if m.group(1).isdigit() \
                    else ('https://www.google.com/maps?ftid=' + m.group(1))
        if not nxt:
            m = (re.search(r'http-equiv=["\']refresh["\'][^>]*url=([^"\'>\s]+)', html, re.I)
                 or re.search(r'(?:location\.replace|location\.href\s*=|window\.location\s*=)\s*\(?["\']([^"\']+)["\']', html)
                 or re.search(r'href="(https?://(?:www\.)?google\.[a-z.]+/maps[^"]+)"', html))
            if m:
                nxt = m.group(1).replace('&amp;', '&').replace('\\u003d', '=').replace('\\u0026', '&').replace('\\x3d', '=').replace('\\x26', '&')
                nxt = _urlparse.urljoin(final, nxt)
        if not nxt or nxt in tried:
            break
        url = nxt
    if ll:
        return {'lat': ll[0], 'lng': ll[1], 'name': name}
    name = name or _dlv_name_from_html(final, html)
    if name:
        # اسم المكان معروف: نسأل خرائط جوجل نفسها عن إحداثياته قبل الاعتماد على OSM
        try:
            r2 = sess.get('https://www.google.com/maps', params={'q': name, 'hl': 'en'},
                          headers=_DLV_BROWSER_HDR, allow_redirects=True, timeout=15)
            ll = _dlv_parse_coords(r2.url, bare=False) or _dlv_parse_html_coords((r2.text or '')[:1200000])
        except Exception:
            ll = None
        if ll:
            return {'lat': ll[0], 'lng': ll[1], 'name': name}
        return {'lat': None, 'lng': None, 'name': name}
    return None


def _dlv_nominatim(sess, q, near, state):
    _dlv_throttle(state)
    params = {'q': q, 'format': 'jsonv2', 'limit': 4, 'accept-language': 'ar'}
    if near:
        d = 0.7
        params['viewbox'] = f"{near[1] - d:.4f},{near[0] + d:.4f},{near[1] + d:.4f},{near[0] - d:.4f}"
    r = sess.get('https://nominatim.openstreetmap.org/search', params=params, timeout=12)
    r.raise_for_status()
    out = []
    for it in r.json():
        ll = _dlv_valid_ll(it.get('lat'), it.get('lon'))
        if ll:
            out.append(ll)
    return out


def _dlv_photon(sess, q, near, state):
    params = {'q': q, 'limit': 4}
    if near:
        params['lat'], params['lon'] = near[0], near[1]
    r = sess.get('https://photon.komoot.io/api/', params=params, timeout=12)
    r.raise_for_status()
    out = []
    for f in (r.json().get('features') or []):
        c = (f.get('geometry') or {}).get('coordinates') or []
        if len(c) >= 2:
            ll = _dlv_valid_ll(c[1], c[0])
            if ll:
                out.append(ll)
    return out


def _dlv_pick(cands, near, max_km=80):
    """أقرب نتيجة لموقع المتجر، وترفض النتائج البعيدة جداً (تطابق اسم شارع في مدينة أخرى)."""
    if not cands:
        return None
    if near is None:
        return cands[0]
    best = min(cands, key=lambda c: _dlv_haversine(near, c))
    return best if _dlv_haversine(near, best) <= max_km else None


def _dlv_geocode_address(sess, address, zone, hint, near, state):
    """(lat, lng, precision) أو None. precision: 'addr' = مطابقة بالعنوان، 'zone' = بالمنطقة فقط (تقريبي)."""
    def clean(s):
        return " ".join(re.sub(r'[^\w\s\u0600-\u06FF]', ' ', s or '').split())
    a, z, h = clean(address), clean(zone), clean(hint)
    variants = []
    if a and z:
        variants.append((f"{a} {z} {h}".strip(), 'addr'))
    if a:
        variants.append((f"{a} {h}".strip(), 'addr'))
    if z:
        variants.append((f"{z} {h}".strip(), 'zone'))
    seen = set()
    for q, prec in variants:
        if q in seen:
            continue
        seen.add(q)
        for engine in (_dlv_nominatim, _dlv_photon):
            try:
                cands = engine(sess, q, near, state)
            except Exception:
                continue
            pick = _dlv_pick(cands, near)
            if pick:
                return pick[0], pick[1], prec
    return None


def _dlv_route(sess, a, b):
    """(كم, دقائق, نقاط المسار, تقريبي؟). لو خادم المسارات لا يرد: خط مستقيم ×1.3 بسرعة 25 كم/س."""
    try:
        r = sess.get(_DLV_OSRM_URL.format(a_lat=a[0], a_lng=a[1], b_lat=b[0], b_lng=b[1]),
                     params={'overview': 'full', 'geometries': 'geojson'}, timeout=12)
        rt = r.json()['routes'][0]
        coords = [(c[1], c[0]) for c in rt['geometry']['coordinates']]
        if len(coords) > 300:
            step = len(coords) / 300.0
            coords = [coords[int(i * step)] for i in range(300)] + [coords[-1]]
        return rt['distance'] / 1000.0, rt['duration'] / 60.0, coords, False
    except Exception:
        km = _dlv_haversine(a, b) * 1.3
        return km, km / 25.0 * 60.0, [a, b], True


def _dlv_px(lat, lng, z):
    n = 256.0 * (2 ** z)
    x = (lng + 180.0) / 360.0 * n
    s = math.sin(math.radians(max(min(lat, 85.0511), -85.0511)))
    y = (0.5 - math.log((1 + s) / (1 - s)) / (4 * math.pi)) * n
    return x, y


def _dlv_get_tile(sess, z, x, y):
    n = 2 ** z
    x %= n
    if y < 0 or y >= n:
        return None
    d = os.path.join(tempfile.gettempdir(), 'dlv_tiles', str(z), str(x))
    fp = os.path.join(d, f"{y}.png")
    try:
        if os.path.exists(fp):
            return Image.open(fp).convert('RGB')
    except Exception:
        pass
    try:
        r = sess.get(_DLV_TILE_URL.format(z=z, x=x, y=y), timeout=10)
        if r.status_code != 200:
            return None
        img = Image.open(io.BytesIO(r.content)).convert('RGB')
        try:
            os.makedirs(d, exist_ok=True)
            img.save(fp, 'PNG')
        except Exception:
            pass
        return img
    except Exception:
        return None


def _dlv_render_map(sess, store, cust, path, size=(440, 180), single_zoom=None):
    """يرسم خريطة ثابتة (بلاطات OpenStreetMap) عليها المتجر والعميل والمسار. PIL.Image أو None."""
    W, H = size
    pts = [p for p in (store, cust) if p]
    if path:
        pts += list(path)
    if not pts:
        return None
    if single_zoom or len(pts) == 1:
        z = single_zoom or 16
        cx, cy = _dlv_px(pts[0][0], pts[0][1], z)
    else:
        z = 17
        for z in range(17, 2, -1):
            xy = [_dlv_px(p[0], p[1], z) for p in pts]
            xs, ys = [q[0] for q in xy], [q[1] for q in xy]
            if max(xs) - min(xs) <= W - 90 and max(ys) - min(ys) <= H - 70:
                break
        xy = [_dlv_px(p[0], p[1], z) for p in pts]
        xs, ys = [q[0] for q in xy], [q[1] for q in xy]
        cx, cy = (max(xs) + min(xs)) / 2.0, (max(ys) + min(ys)) / 2.0
    x0, y0 = cx - W / 2.0, cy - H / 2.0
    canvas = Image.new('RGB', (W, H), (232, 237, 243))
    ok = 0
    for ty in range(int(math.floor(y0 / 256)), int(math.floor((y0 + H) / 256)) + 1):
        for tx in range(int(math.floor(x0 / 256)), int(math.floor((x0 + W) / 256)) + 1):
            t = _dlv_get_tile(sess, z, tx, ty)
            if t is not None:
                ok += 1
                canvas.paste(t, (int(round(tx * 256 - x0)), int(round(ty * 256 - y0))))
    if ok == 0:
        return None
    S = 2
    ov = Image.new('RGBA', (W * S, H * S), (0, 0, 0, 0))
    d = ImageDraw.Draw(ov)

    def P(ll):
        px, py = _dlv_px(ll[0], ll[1], z)
        return ((px - x0) * S, (py - y0) * S)

    if path and len(path) > 1:
        xy = [P(p) for p in path]
        d.line(xy, fill=(255, 255, 255, 240), width=9 * S, joint="curve")
        d.line(xy, fill=(37, 99, 235, 255), width=5 * S, joint="curve")

    def pin(ll, col, r):
        cxp, cyp = P(ll)
        d.ellipse((cxp - r * S, cyp - r * S, cxp + r * S, cyp + r * S), fill=col + (255,),
                  outline=(255, 255, 255, 255), width=3 * S)
        d.ellipse((cxp - 3 * S, cyp - 3 * S, cxp + 3 * S, cyp + 3 * S), fill=(255, 255, 255, 255))

    if store:
        pin(store, (37, 99, 235), 10)
    if cust:
        pin(cust, (220, 38, 38), 11)
    ov = ov.resize((W, H), Image.LANCZOS)
    canvas.paste(ov, (0, 0), ov)
    try:
        dd = ImageDraw.Draw(canvas)
        f = ImageFont.load_default()
        txt = "© OpenStreetMap"
        tw = int(dd.textlength(txt, font=f))
        dd.rectangle((W - tw - 10, H - 15, W, H), fill=(255, 255, 255))
        dd.text((W - tw - 5, H - 13), txt, fill=(70, 70, 70), font=f)
    except Exception:
        pass
    return canvas


def _dlv_run_geo_job(sess, job, state):
    """ينفّذ مهمة موقع واحدة ويرجع dict بالنتيجة (kind: 'store' للمتجر، 'order' لطلب)."""
    kind = job['kind']
    res = {'kind': kind, 'id': job.get('id'), 'src': job.get('src')}
    store = job.get('store')
    if kind == 'store':
        ll = _dlv_valid_ll(job.get('lat'), job.get('lng'))
        link, addr = (job.get('link') or '').strip(), (job.get('address') or '').strip()
        if ll is None and link:
            try:
                got = _dlv_resolve_map_link(sess, link)
            except Exception as e:
                got = None
                res['err'] = 'link: ' + str(e)[:60]
            if got:
                if got.get('lat') is not None:
                    ll = (got['lat'], got['lng'])
                elif got.get('name'):
                    g = _dlv_geocode_address(sess, got['name'], '', '', None, state)
                    if g:
                        ll = (g[0], g[1])
        if ll is None and addr:
            g = _dlv_geocode_address(sess, addr, '', '', None, state)
            if g:
                ll = (g[0], g[1])
                res['from_address'] = True
        if ll is None:
            res['err'] = res.get('err') or 'notfound'
            return res
        res['lat'], res['lng'] = ll
        if job.get('want_hint'):
            try:
                _dlv_throttle(state)
                r = sess.get('https://nominatim.openstreetmap.org/reverse',
                             params={'lat': ll[0], 'lon': ll[1], 'format': 'jsonv2', 'zoom': 10,
                                     'accept-language': 'ar'}, timeout=12)
                a = r.json().get('address') or {}
                parts = [a.get('city') or a.get('town') or a.get('village') or a.get('suburb'),
                         a.get('state'), a.get('country')]
                res['hint'] = " ".join(p for p in parts if p)
            except Exception:
                pass
        if job.get('want_img'):
            res['img'] = _dlv_render_map(sess, ll, None, None, size=(440, 200), single_zoom=16)
        return res

    if kind == 'link':
        # تحويل رابط جوجل/اسم مكان يكتبه الكاشير إلى إحداثيات (للموقع اليدوي)
        q = (job.get('query') or '').strip()
        ll = None
        if q:
            g = _dlv_geocode_address(sess, q, '', job.get('hint'), store, state)
            if g:
                ll = (g[0], g[1])
        else:
            try:
                got = _dlv_resolve_map_link(sess, job.get('link'))
            except Exception as e:
                got = None
                res['dbg'] = 'خطأ اتصال: ' + str(e)[:70]
            res.setdefault('dbg', getattr(sess, '_dlv_dbg', ''))
            if got and got.get('lat') is not None:
                ll = (got['lat'], got['lng'])
            elif got and got.get('name'):
                g = _dlv_geocode_address(sess, got['name'], '', job.get('hint'), store, state)
                if g:
                    ll = (g[0], g[1])
        if ll is None:
            res['err'] = 'notfound'
            return res
        res['lat'], res['lng'] = ll
        return res

    # ── طلب عميل ──
    ll = _dlv_valid_ll(job.get('lat'), job.get('lng'))
    prec = job.get('prec') or 'addr'
    if ll is None:
        c = _dlv_parse_coords(job.get('address'))
        if c is None:
            url = _dlv_extract_url(job.get('address'))
            if url:
                try:
                    got = _dlv_resolve_map_link(sess, url)
                    if got and got.get('lat') is not None:
                        c = (got['lat'], got['lng'])
                except Exception:
                    pass
        if c:
            ll, prec = c, 'pin'
        else:
            g = _dlv_geocode_address(sess, job.get('address'), job.get('zone'), job.get('hint'), store, state)
            if g:
                ll, prec = (g[0], g[1]), g[2]
    if ll is None:
        res['err'] = 'notfound'
        return res
    res.update(lat=ll[0], lng=ll[1], prec=prec)
    if store:
        km, mn, path, approx = _dlv_route(sess, store, ll)
        res.update(km=km, min=mn, path=path, approx=approx)
        if job.get('want_img', True):
            res['img'] = _dlv_render_map(sess, store, ll, path)
    return res


def _dlv_geo_loop(qin, qout):
    """حلقة الخيط الخلفي: تأخذ مهمة من qin وترد النتيجة في qout."""
    sess = requests.Session()
    sess.headers.update({'User-Agent': _DLV_UA, 'Accept-Language': 'ar,en;q=0.7'})
    state = {'last': 0.0}
    while True:
        job = qin.get()
        if job is None:
            break
        try:
            res = _dlv_run_geo_job(sess, job, state)
        except Exception as e:
            res = {'kind': job.get('kind'), 'id': job.get('id'), 'src': job.get('src'), 'err': str(e)[:80]}
        qout.put(res)



class _DlvPhotoTable(tk.Frame):
    """جدول RTL خفيف يدعم صورة داخل الخلية (قبل الاسم) — يحاكي واجهة Treeview المستخدمة في النوافذ.
    cols: [(key, title, width, stretch, anchor)] بالترتيب من اليمين إلى اليسار."""
    TAG_BG = {"late": "#FEE2E2", "due": "#FFF7ED"}

    def __init__(self, parent, cols, font, bg="#F1F5F9", card="#FFFFFF", border="#E2E8F0",
                 fg="#1E293B", muted="#64748B", sel="#DBEAFE", row_h=46, multi=False, height=120):
        super().__init__(parent, bg=bg)
        self._cols = [tuple(c) + (("center",) if len(c) == 4 else ()) for c in cols]
        self._F, self._bg, self._card, self._border = font, bg, card, border
        self._fg, self._muted, self._sel_bg, self._rh, self._multi = fg, muted, sel, row_h, multi
        self._rows, self._order, self._sel, self._cb, self._anchor = {}, [], [], None, None
        self.grid_columnconfigure(1, weight=1)
        self.grid_rowconfigure(1, weight=1)
        # الرأس
        self._head = tk.Frame(self, bg=bg)
        self._head.grid(row=0, column=1, sticky="ew")
        self._cfg(self._head)
        for i, (key, title, w, st, an) in enumerate(self._cols):
            cell = tk.Frame(self._head, width=w, height=30, bg=bg)
            cell.grid(row=0, column=len(self._cols) - 1 - i, sticky="nsew")
            cell.pack_propagate(False)
            tk.Label(cell, text=title, font=(font, 10, "bold"), bg=bg, fg=muted,
                     anchor=("e" if an == "e" else "center")).pack(fill="both", expand=True, padx=8)
        tk.Frame(self, bg=border, height=1).grid(row=0, column=1, sticky="sew")
        # المحتوى + شريط التمرير (يسار)
        self._cv = tk.Canvas(self, bg=card, highlightthickness=1, highlightbackground=border, height=height)
        self._sb = ttk.Scrollbar(self, orient="vertical", command=self._cv.yview)
        self._cv.configure(yscrollcommand=self._sb.set)
        self._sb.grid(row=1, column=0, sticky="ns")
        self._cv.grid(row=1, column=1, sticky="nsew")
        self._inner = tk.Frame(self._cv, bg=card)
        self._win = self._cv.create_window((0, 0), window=self._inner, anchor="nw")
        self._inner.bind("<Configure>", lambda e: self._cv.configure(scrollregion=self._cv.bbox("all")))
        self._cv.bind("<Configure>", lambda e: self._cv.itemconfigure(self._win, width=e.width))
        self._wheel(self._cv)
        self._wheel(self._inner)

    def _cfg(self, fr):
        n = len(self._cols)
        for i, (key, title, w, st, an) in enumerate(self._cols):
            fr.grid_columnconfigure(n - 1 - i, minsize=w, weight=(1 if st else 0))

    def _wheel(self, w):
        w.bind("<MouseWheel>", lambda e: self._cv.yview_scroll(-1 if e.delta > 0 else 1, "units"), add="+")

    # ── واجهة شبيهة بـ Treeview ──
    def bind(self, seq=None, fn=None, add=None):
        if seq == "<<TreeviewSelect>>":
            self._cb = fn
            return
        return super().bind(seq, fn, add)

    def get_children(self, *_):
        return tuple(self._order)

    def exists(self, iid):
        return str(iid) in self._rows

    def selection(self):
        return tuple(self._sel)

    def selection_set(self, items):
        if isinstance(items, (str, int)):
            items = [items]
        self._sel = [str(i) for i in items if str(i) in self._rows]
        self._anchor = self._sel[0] if self._sel else None
        for i in self._order:
            self._paint(i)

    def delete(self, *iids):
        for i in iids:
            r = self._rows.pop(str(i), None)
            if r:
                r['frame'].destroy()
                self._order.remove(str(i))
                if str(i) in self._sel:
                    self._sel.remove(str(i))

    def insert(self, parent, index, iid=None, values=(), tags=(), images=None, fg=None, **_):
        iid = str(iid)
        images, fg = images or {}, fg or {}
        row = tk.Frame(self._inner, bg=self._card)
        row.pack(fill="x")
        self._cfg(row)
        widgets = [row]
        labels = []
        for i, (key, title, w, st, an) in enumerate(self._cols):
            cell = tk.Frame(row, width=w, height=self._rh, bg=self._card)
            cell.grid(row=0, column=len(self._cols) - 1 - i, sticky="nsew")
            cell.pack_propagate(False)
            txt = values[i] if i < len(values) else ""
            lb = tk.Label(cell, text=txt, font=(self._F, 10, "bold"),
                          bg=self._card, fg=fg.get(key, self._fg), anchor=("e" if an == "e" else "center"))
            if key in images and images[key] is not None:
                lb.configure(image=images[key], compound="right")
                lb.image = images[key]
            lb.pack(fill="both", expand=True, padx=8)
            widgets += [cell, lb]
            labels.append(lb)
        sep = tk.Frame(row, height=1, bg=self._border)
        sep.grid(row=1, column=0, columnspan=len(self._cols), sticky="ew")
        for w_ in widgets:
            w_.bind("<Button-1>", lambda e, k=iid: self._click(k, e))
            self._wheel(w_)
        self._rows[iid] = {'frame': row, 'cells': widgets, 'tags': tuple(tags or ()), 'labels': labels}
        self._order.append(iid)
        self._paint(iid)
        return iid

    def _paint(self, iid):
        r = self._rows.get(iid)
        if not r:
            return
        bg = self._sel_bg if iid in self._sel else next(
            (self.TAG_BG[t] for t in r['tags'] if t in self.TAG_BG), self._card)
        for w in r['cells']:
            try:
                w.configure(bg=bg)
            except Exception:
                pass

    def _click(self, iid, e):
        if self._multi and (e.state & 0x4):
            if iid in self._sel:
                self._sel.remove(iid)
            else:
                self._sel.append(iid)
            self._anchor = iid
        elif self._multi and (e.state & 0x1) and self._anchor in self._rows:
            a, b = self._order.index(self._anchor), self._order.index(iid)
            self._sel = self._order[min(a, b):max(a, b) + 1]
        else:
            self._sel = [iid]
            self._anchor = iid
        for i in self._order:
            self._paint(i)
        if self._cb:
            self._cb()


class DeliveryMixin:
    # ───────────────────────── طبقة قاعدة البيانات ─────────────────────────
    def _dlv_exec(self, sql, params=(), commit=True, want='id'):
        cur = self.conn.cursor()
        try:
            cur.execute(sql, params)
            res = cur.rowcount if want == 'rowcount' else cur.lastrowid
            if commit:
                self.conn.commit()
            return res
        except Exception:
            if commit:
                try:
                    self.conn.rollback()
                except Exception:
                    pass
            raise
        finally:
            try:
                cur.close()
            except Exception:
                pass

    def _dlv_q(self, sql, params=(), one=False, fresh=False):
        """استعلام قراءة. fresh=True يجدد لقطة القاعدة (للتحديث الدوري فقط)."""
        cur = self.conn.cursor()
        try:
            cur.execute(sql, params)
            rows = cur.fetchall()
            if fresh:
                self.conn.commit()
            if one:
                return rows[0] if rows else None
            return rows
        finally:
            try:
                cur.close()
            except Exception:
                pass

    def _dlv_add_column(self, table, col, ddl):
        try:
            row = self._dlv_q(
                "SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() "
                "AND table_name = %s AND column_name = %s", (table, col), one=True)
            if int(row[0] or 0) == 0:
                self._dlv_exec(f"ALTER TABLE `{table}` ADD COLUMN `{col}` {ddl}")
        except Exception as e:
            print(f"تنبيه الدليفري: تعذر إضافة العمود {table}.{col}: {e}")

    def _dlv_ensure_schema(self):
        if getattr(self, '_dlv_schema_ok', False):
            return
        stmts = [
            '''CREATE TABLE IF NOT EXISTS pos_order_config (
                   id INT PRIMARY KEY,
                   enabled TINYINT DEFAULT 0,
                   prep_minutes INT DEFAULT 20,
                   takeaway_minutes INT DEFAULT 10,
                   warn_minutes INT DEFAULT 5
               ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4''',
            '''CREATE TABLE IF NOT EXISTS delivery_zones (
                   id INT AUTO_INCREMENT PRIMARY KEY,
                   name VARCHAR(120) NOT NULL,
                   fee DECIMAL(10,2) NOT NULL DEFAULT 0,
                   minutes INT NOT NULL DEFAULT 20,
                   min_order DECIMAL(10,2) NOT NULL DEFAULT 0,
                   active TINYINT NOT NULL DEFAULT 1
               ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4''',
            '''CREATE TABLE IF NOT EXISTS customer_addresses (
                   id INT AUTO_INCREMENT PRIMARY KEY,
                   customer_id INT NOT NULL,
                   address TEXT NOT NULL,
                   zone_id INT NULL,
                   last_used TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                   INDEX idx_ca_customer (customer_id)
               ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4''',
            '''CREATE TABLE IF NOT EXISTS pos_orders (
                   id INT AUTO_INCREMENT PRIMARY KEY,
                   order_type VARCHAR(12) NOT NULL,
                   status VARCHAR(20) NOT NULL DEFAULT 'preparing',
                   customer_id INT NULL,
                   customer_name VARCHAR(255),
                   phone VARCHAR(30),
                   address TEXT,
                   zone_id INT NULL,
                   zone_name VARCHAR(120),
                   delivery_fee DECIMAL(10,2) NOT NULL DEFAULT 0,
                   prep_minutes INT NOT NULL DEFAULT 0,
                   travel_minutes INT NOT NULL DEFAULT 0,
                   payment_mode VARCHAR(12) NOT NULL DEFAULT 'cod',
                   notes TEXT,
                   created_at DATETIME NOT NULL,
                   promised_at DATETIME NOT NULL,
                   ready_at DATETIME NULL,
                   dispatched_at DATETIME NULL,
                   delivered_at DATETIME NULL,
                   cancelled_at DATETIME NULL,
                   cancel_reason VARCHAR(255) NULL,
                   driver_id INT NULL,
                   driver_name VARCHAR(255) NULL,
                   invoice_id INT NULL,
                   invoice_number VARCHAR(50) NULL,
                   created_by INT NULL,
                   shift_number INT NULL,
                   INDEX idx_po_status (status),
                   INDEX idx_po_created (created_at),
                   INDEX idx_po_invoice (invoice_id)
               ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4''',
        ]
        for s in stmts:
            try:
                self._dlv_exec(s)
            except Exception as e:
                print(f"تنبيه الدليفري: تعذر إنشاء جدول: {e}")
        try:
            self._dlv_exec("INSERT IGNORE INTO pos_order_config (id) VALUES (1)")
        except Exception as e:
            print(f"تنبيه الدليفري: {e}")
        for _c, _d in (('store_lat', "DECIMAL(10,7) NULL"), ('store_lng', "DECIMAL(10,7) NULL"),
                       ('store_src', "VARCHAR(500) NULL"), ('geo_hint', "VARCHAR(200) NULL"),
                       ('map_on_cards', "TINYINT NOT NULL DEFAULT 1")):
            self._dlv_add_column('pos_order_config', _c, _d)
        for _c, _d in (('lat', "DECIMAL(10,7) NULL"), ('lng', "DECIMAL(10,7) NULL"),
                       ('route_km', "DECIMAL(8,2) NULL"), ('route_min', "INT NULL"),
                       ('geo_prec', "VARCHAR(8) NULL")):
            self._dlv_add_column('pos_orders', _c, _d)
        for _c in ('lat', 'lng'):
            self._dlv_add_column('customer_addresses', _c, "DECIMAL(10,7) NULL")
        for _c in ('lat', 'lng'):
            self._dlv_add_column('delivery_zones', _c, "DECIMAL(10,7) NULL")
        self._dlv_add_column('job_types', 'job_kind', "VARCHAR(20) NULL DEFAULT NULL")
        self._dlv_add_column('invoices', 'delivery_fee', "DECIMAL(10,2) NOT NULL DEFAULT 0")
        self._dlv_add_column('invoices', 'order_type', "VARCHAR(12) NULL DEFAULT NULL")
        self._dlv_add_column('invoices', 'discount_percentage', "DECIMAL(5,2) NOT NULL DEFAULT 0")
        try:
            self._dlv_exec('''CREATE TABLE IF NOT EXISTS driver_receipts (
                   id INT AUTO_INCREMENT PRIMARY KEY,
                   driver_id INT NOT NULL,
                   driver_name VARCHAR(255) NULL,
                   cashier_name VARCHAR(255) NULL,
                   shift_number INT NULL,
                   orders_count INT NOT NULL DEFAULT 0,
                   expected_cash DECIMAL(12,2) NOT NULL DEFAULT 0,
                   noncash_total DECIMAL(12,2) NOT NULL DEFAULT 0,
                   received_cash DECIMAL(12,2) NOT NULL DEFAULT 0,
                   diff_cash DECIMAL(12,2) NOT NULL DEFAULT 0,
                   note VARCHAR(255) NULL,
                   created_at DATETIME NOT NULL,
                   INDEX idx_dr_driver (driver_id),
                   INDEX idx_dr_created (created_at)
               ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4''')
        except Exception as e:
            print(f"تنبيه الدليفري: تعذر إنشاء جدول driver_receipts: {e}")
        self._dlv_add_column('pos_orders', 'receipt_id', "INT NULL DEFAULT NULL")
        self._dlv_schema_ok = True

    def _dlv_cfg(self, force=False):
        c = getattr(self, '_dlv_cfg_cache', None)
        if c is not None and not force:
            return c
        cfg = {'enabled': 0, 'prep_minutes': 20, 'takeaway_minutes': 10, 'warn_minutes': 5,
               'store_lat': None, 'store_lng': None, 'store_src': '', 'geo_hint': '', 'map_on_cards': 1}
        try:
            self._dlv_ensure_schema()
            row = self._dlv_q("SELECT enabled, prep_minutes, takeaway_minutes, warn_minutes "
                              "FROM pos_order_config WHERE id=1", one=True, fresh=True)
            if row:
                cfg['enabled'] = int(row[0] or 0)
                cfg['prep_minutes'] = int(row[1] if row[1] is not None else 20)
                cfg['takeaway_minutes'] = int(row[2] if row[2] is not None else 10)
                cfg['warn_minutes'] = int(row[3] if row[3] is not None else 5)
        except Exception as e:
            print(f"تعذر قراءة إعدادات الدليفري: {e}")
        try:
            r2 = self._dlv_q("SELECT store_lat, store_lng, store_src, geo_hint, map_on_cards "
                             "FROM pos_order_config WHERE id=1", one=True)
            if r2:
                cfg['store_lat'] = None if r2[0] is None else float(r2[0])
                cfg['store_lng'] = None if r2[1] is None else float(r2[1])
                cfg['store_src'] = r2[2] or ''
                cfg['geo_hint'] = r2[3] or ''
                cfg['map_on_cards'] = 1 if r2[4] is None else int(r2[4])
        except Exception as e:
            print(f"تعذر قراءة إعدادات الخريطة: {e}")
        self._dlv_cfg_cache = cfg
        return cfg

    def _dlv_save_enabled(self, enabled):
        try:
            self._dlv_ensure_schema()
            self._dlv_exec("UPDATE pos_order_config SET enabled=%s WHERE id=1", (int(enabled),))
        except Exception as e:
            print(f"تعذر حفظ تفعيل الدليفري: {e}")
        self._dlv_cfg(force=True)

    # ───────────────────────── موقع المتجر والخريطة (واجهة الخيط الخلفي) ─────────────────────────
    def _dlv_gs(self):
        """يجهّز حالة الخريطة عند أول استخدام."""
        if not hasattr(self, '_dlv_geo_cache'):
            self._dlv_geo_cache = {}      # {order_id: {lat,lng,km,min,path,img,prec,approx} | {err}}
            self._dlv_map_slots = {}      # {order_id: [(column_key, fill_fn)]}
            self._dlv_map_photos = {}     # {(order_id, width): PhotoImage}
            self._dlv_geo_pending = set()
            self._dlv_store_state = None
            self._dlv_store_img = None
            self._dlv_store_cb = None
            self._dlv_store_info_c = None
            self._dlv_link_cbs = {}
            self._dlv_link_seq = 0

    def _dlv_geo_start(self):
        self._dlv_gs()
        t = getattr(self, '_dlv_geo_thread', None)
        if t is not None and t.is_alive():
            return
        self._dlv_geo_q = _queue.Queue()
        self._dlv_geo_out = _queue.Queue()
        self._dlv_geo_pending = set()
        self._dlv_geo_thread = threading.Thread(target=_dlv_geo_loop, args=(self._dlv_geo_q, self._dlv_geo_out),
                                                daemon=True)
        self._dlv_geo_thread.start()

    def _dlv_geo_submit(self, job):
        self._dlv_geo_start()
        key = (job['kind'], job.get('id'))
        if key in self._dlv_geo_pending:
            return False
        self._dlv_geo_pending.add(key)
        self._dlv_geo_q.put(job)
        self._dlv_geo_pump_arm()
        return True

    def _dlv_geo_pump_arm(self):
        if getattr(self, '_dlv_geo_pump_job', None):
            return
        try:
            self._dlv_geo_pump_job = self.root.after(350, self._dlv_geo_pump)
        except Exception:
            self._dlv_geo_pump_job = None

    def _dlv_geo_pump(self):
        """يُنفَّذ في الخيط الرئيسي: يقرأ النتائج الجاهزة ويحدّث الواجهة (بدون أي انتظار)."""
        self._dlv_geo_pump_job = None
        try:
            while True:
                res = self._dlv_geo_out.get_nowait()
                self._dlv_geo_pending.discard((res.get('kind'), res.get('id')))
                try:
                    self._dlv_geo_apply(res)
                except Exception as e:
                    print(f"تعذر تطبيق نتيجة الموقع: {e}")
        except _queue.Empty:
            pass
        except Exception as e:
            print(f"خطأ في مضخة الموقع: {e}")
        if getattr(self, '_dlv_geo_pending', None):
            self._dlv_geo_pump_arm()

    def _dlv_geo_apply(self, res):
        if res.get('kind') == 'link':
            cb = self._dlv_link_cbs.pop(res.get('id'), None)
            if cb:
                cb(res)
            return
        if res.get('kind') == 'store':
            self._dlv_store_done(res)
            return
        oid = res.get('id')
        if res.get('lat') is None:
            self._dlv_geo_cache[oid] = {'err': res.get('err') or 'notfound', 'at': time.time()}
        else:
            self._dlv_geo_cache[oid] = {k: res.get(k) for k in
                                        ('lat', 'lng', 'km', 'min', 'path', 'approx', 'img', 'prec')}
            try:
                km, mn = res.get('km'), res.get('min')
                self._dlv_exec(
                    "UPDATE pos_orders SET lat=%s, lng=%s, route_km=%s, route_min=%s, geo_prec=%s WHERE id=%s",
                    (round(res['lat'], 7), round(res['lng'], 7), None if km is None else round(km, 2),
                     None if mn is None else int(round(mn)), res.get('prec'), oid))
            except Exception as e:
                print(f"تعذر حفظ موقع الطلب {oid}: {e}")
        for k in [k for k in self._dlv_map_photos if k[0] == oid]:
            self._dlv_map_photos.pop(k, None)
        for _key, fn in list(self._dlv_map_slots.get(oid, [])):
            try:
                fn()
            except Exception:
                pass

    # ───── موقع المتجر: يُؤخذ من «رابط الموقع على جوجل» في إعدادات الفاتورة ─────
    def _dlv_store_info(self):
        """(رابط جوجل, عنوان المتجر الأول) من إعدادات الفاتورة — مع كاش 20 ثانية."""
        self._dlv_gs()
        c = self._dlv_store_info_c
        if c and time.time() - c[0] < 20:
            return c[1]
        link = addr = ''
        try:
            r = self._dlv_q("SELECT google_location, address1 FROM invoice_settings ORDER BY id LIMIT 1", one=True)
            if r:
                link, addr = (r[0] or '').strip(), (r[1] or '').strip()
        except Exception as e:
            print(f"تعذر قراءة رابط موقع المتجر: {e}")
        self._dlv_store_info_c = (time.time(), (link, addr))
        return link, addr

    def _dlv_store_point(self, resolve=True):
        """(lat, lng) لموقع المتجر، أو None لو غير محدد بعد (ويبدأ تحديده في الخلفية)."""
        self._dlv_gs()
        cfg = self._dlv_cfg()
        lat, lng = cfg.get('store_lat'), cfg.get('store_lng')
        if lat is not None and lng is not None:
            link, addr = self._dlv_store_info()
            src = cfg.get('store_src') or ''
            if src == 'manual' or src == (link or addr):
                return lat, lng
            st = self._dlv_store_state
            if st and st.get('err') and time.time() - st['at'] < 600:
                return lat, lng          # الرابط الجديد لم يُقرأ: نبقى على آخر موقع صحيح بدل إلغاء الخريطة
        if resolve:
            self._dlv_store_resolve()
        return None

    def _dlv_store_resolve(self, force=False):
        self._dlv_gs()
        link, addr = self._dlv_store_info()
        cfg = self._dlv_cfg()
        manual = (cfg.get('store_src') == 'manual' and cfg.get('store_lat') is not None)
        if not (link or addr or manual):
            return False
        src = 'manual' if manual else (link or addr)
        st = self._dlv_store_state
        if not force and st and st.get('src') == src and time.time() - st['at'] < 300:
            return False
        job = {'kind': 'store', 'id': 0, 'link': link, 'address': addr, 'src': src, 'want_img': True,
               'want_hint': not (cfg.get('geo_hint') or '').strip()}
        if manual:
            job['lat'], job['lng'] = cfg['store_lat'], cfg['store_lng']
            job['want_hint'] = False
        return self._dlv_geo_submit(job)

    def _dlv_store_done(self, res):
        self._dlv_store_state = {'at': time.time(), 'src': res.get('src'), 'err': res.get('err')}
        if res.get('lat') is not None:
            self._dlv_store_img = res.get('img')
            try:
                cfg = self._dlv_cfg()
                changed = (cfg.get('store_lat') is None or abs(cfg['store_lat'] - res['lat']) > 1e-6
                           or abs(cfg['store_lng'] - res['lng']) > 1e-6)
                self._dlv_exec("UPDATE pos_order_config SET store_lat=%s, store_lng=%s, store_src=%s WHERE id=1",
                               (round(res['lat'], 7), round(res['lng'], 7), res.get('src')))
                if res.get('hint') and not (cfg.get('geo_hint') or '').strip():
                    self._dlv_exec("UPDATE pos_order_config SET geo_hint=%s WHERE id=1", (res['hint'][:200],))
                self._dlv_cfg(force=True)
                if changed:
                    self._dlv_geo_cache.clear()       # المسارات القديمة محسوبة من نقطة بداية أخرى
                    self._dlv_map_photos.clear()
            except Exception as e:
                print(f"تعذر حفظ موقع المتجر: {e}")
        cb = getattr(self, '_dlv_store_cb', None)
        if cb:
            try:
                cb()
            except Exception:
                pass
        if getattr(self, '_dlv_win', None) is not None:
            try:
                self._dlv_on_search()
            except Exception:
                pass

    def _dlv_geo_order_job(self, o, prec=None):
        cfg = self._dlv_cfg()
        lat, lng, pr = o.get('lat'), o.get('lng'), prec or o.get('geo_prec')
        zl, zg = o.get('zlat'), o.get('zlng')
        if not (pr == 'pin' and lat is not None) and zl is not None and zg is not None:
            lat, lng, pr = zl, zg, 'zpin'          # موقع المنطقة (يُقرأ حياً من إعدادات المناطق)
        return {'kind': 'order', 'id': o['id'], 'address': o.get('address') or '', 'zone': o.get('zone_name') or '',
                'hint': cfg.get('geo_hint') or '', 'store': self._dlv_store_point(resolve=False),
                'lat': lat, 'lng': lng, 'prec': pr, 'want_img': False}

    def _dlv_geo_ensure(self, orders):
        """يطلب (في الخلفية) موقع/مسار/صورة خريطة كل طلب دليفري نشط لم يُحسب بعد."""
        self._dlv_gs()
        if not self._dlv_cfg().get('map_on_cards', 1):
            return
        active = {o['id'] for o in orders if o['order_type'] == 'delivery' and o['status'] in DLV_ACTIVE}
        for k in [k for k in self._dlv_geo_cache if k not in active]:
            self._dlv_geo_cache.pop(k, None)
        for k in [k for k in self._dlv_map_photos if k[0] not in active]:
            self._dlv_map_photos.pop(k, None)
        if self._dlv_store_point() is None:
            return
        for o in orders:
            if o['id'] in active and o['id'] not in self._dlv_geo_cache:
                self._dlv_geo_submit(self._dlv_geo_order_job(o))

    def _dlv_resolve_link_async(self, text, cb, query=False):
        """يحوّل رابط جوجل (أو اسم مكان لو query=True) إلى إحداثيات في الخلفية، ثم يستدعي cb(res)."""
        self._dlv_gs()
        self._dlv_link_seq += 1
        tok = self._dlv_link_seq
        self._dlv_link_cbs[tok] = cb
        job = {'kind': 'link', 'id': tok, 'store': self._dlv_store_point(resolve=False),
               'hint': self._dlv_cfg().get('geo_hint') or ''}
        job['query' if query else 'link'] = text
        self._dlv_geo_submit(job)

    # ───────────────────────── الوقت (توقيت السيرفر) ─────────────────────────
    def _dlv_sync_clock(self):
        try:
            row = self._dlv_q("SELECT NOW()", one=True, fresh=True)
            if row and row[0]:
                self._dlv_off = row[0] - datetime.now()
        except Exception:
            pass

    def _dlv_now(self):
        return datetime.now() + (getattr(self, '_dlv_off', None) or timedelta(0))

    @staticmethod
    def _dlv_mmss(secs):
        sign = '-' if secs < 0 else ''
        s = abs(int(secs))
        return f"{sign}{s // 60:02d}:{s % 60:02d}"

    def _dlv_timer_info(self, o, now):
        """يرجع (نص, لون) لعدّاد الطلب حسب حالته."""
        warn = self._dlv_cfg()['warn_minutes'] * 60
        st = o['status']
        if st in DLV_ACTIVE:
            rem = (o['promised_at'] - now).total_seconds()
            if rem < 0:
                return f"متأخر {self._dlv_mmss(-rem)}", "#DC2626"
            if rem <= warn:
                return f"متبقي {self._dlv_mmss(rem)}", "#D97706"
            return f"متبقي {self._dlv_mmss(rem)}", "#16A34A"
        if st == 'done' and o.get('delivered_at'):
            total = (o['delivered_at'] - o['created_at']).total_seconds()
            late = (o['delivered_at'] - o['promised_at']).total_seconds()
            if late > 0:
                return f"المدة {int(total // 60)} د (تأخر {int(late // 60)} د)", "#DC2626"
            return f"المدة {int(total // 60)} د", "#16A34A"
        return DLV_STATUS_AR.get(st, st), "#64748B"

    # ───────────────────────── ألوان وأدوات واجهة ─────────────────────────
    def _dlv_c(self, name, default):
        return getattr(self, name, default)

    def _dlv_window(self, title, w, h, modal=False):
        # لو هناك نافذة مودال مفتوحة (مثل الإعدادات) فالنافذة الجديدة تحتاج grab وإلا ستكون مجمّدة
        prev = None
        try:
            prev = self.root.grab_current()
        except Exception:
            pass
        win = tk.Toplevel(self.root)
        win.title(title)
        try:
            self._add_window_header(win)
        except Exception:
            pass
        sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
        w, h = min(w, sw - 40), min(h, sh - 80)
        win.geometry(f"{w}x{h}+{max(0, (sw - w) // 2)}+{max(0, (sh - h) // 2 - 20)}")
        win.configure(bg=self._dlv_c('bg_color', '#F1F5F9'))
        pass  # نافذة عادية: لا تجمّد النافذة الرئيسية
        return win

    def _dlv_btn(self, parent, text, command, color=None, fg="white", **kw):
        color = color or self._dlv_c('accent_color', '#3B82F6')
        return tk.Button(parent, text=text, command=command, bg=color, fg=fg, bd=0, relief="flat",
                         font=(self.font_family, kw.pop('size', 10), "bold"), cursor="hand2",
                         activebackground=color, activeforeground=fg,
                         padx=kw.pop('padx', 12), pady=kw.pop('pady', 5), **kw)

    # ───────────────────────── زر الشاشة الرئيسية ─────────────────────────
    def _dlv_init_feature(self):
        self.hub_button = getattr(self, 'hub_button', None)
        self._hub_win = None
        self._dlv_win = None
        self._dlv_cfg_cache = None
        self._dlv_gs()
        try:
            self._dlv_ensure_schema()
        except Exception as e:
            print(f"تعذر تجهيز مديول الدليفري: {e}")
        self._dlv_refresh_feature()

    def _dlv_refresh_feature(self):
        try:
            cfg = self._dlv_cfg(force=True)
            if not cfg['enabled']:
                self._dlv_close_monitor()
                self._dlv_close_drivers()
            self._dlv_refresh_hub()
        except Exception as e:
            print(f"تعذر تحديث ميزة الدليفري: {e}")

    # ═════════════════════════ زر «الخدمات» الموحّد ═════════════════════════
    def _dlv_hub_items(self):
        """بطاقات نافذة الخدمات: (العنوان, الأيقونة, اللون, الإجراء, سطر الحالة).
        لإضافة ميزة جديدة مستقبلاً: أضف عنصراً هنا، وأضف شرط ظهور الزر في _dlv_hub_any."""
        items = []
        try:
            tcfg = self._load_tables_config()
        except Exception:
            tcfg = {'enabled': 0}
        if tcfg.get('enabled'):
            occ = sum(1 for inv in (getattr(self, 'suspended_invoices', []) or [])
                      if str(inv.get('invoice_number') or '').startswith(self.TABLE_PREFIX))
            items.append(("الطاولات", "table", "#D97706", self.open_tables_window,
                          f"{occ} مشغولة" if occ else "كلها فارغة"))
        if self._dlv_cfg()['enabled']:
            n, late = 0, 0
            try:
                r = self._dlv_q("SELECT COUNT(*), COALESCE(SUM(promised_at < NOW()),0) FROM pos_orders "
                                "WHERE status IN ('preparing','ready','out')", one=True, fresh=True)
                n, late = int(r[0] or 0), int(r[1] or 0)
            except Exception:
                pass
            items.append(("طلب دليفري", "scooter", "#2563EB",
                          lambda: self._dlv_new_order_dialog('delivery'), "من الفاتورة الحالية"))
            items.append(("طلب تيك واي", "bag", "#16A34A",
                          lambda: self._dlv_new_order_dialog('takeaway'), "من الفاتورة الحالية"))
            items.append(("متابعة الطلبات", "orders", "#7C3AED", self._dlv_open_monitor,
                          (f"{n} نشط" + (f" • {late} متأخر" if late else "")) if n else "لا توجد طلبات نشطة"))
            road, due = 0, 0.0
            try:
                for o in self._dlv_fetch_orders():
                    if o['status'] == 'out':
                        road += 1
                        due += o['due']
            except Exception:
                pass
            items.append(("السائقون", "user", "#D97706", self._dlv_open_drivers,
                          f"{road} في الطريق • مطلوب {due:,.0f} ج" if road else "لا أحد في الطريق"))
        return items

    def _dlv_hub_any(self):
        try:
            if self._load_tables_config().get('enabled'):
                return True
        except Exception:
            pass
        return bool(self._dlv_cfg()['enabled'])

    def _update_suspend_bar_layout(self):
        """إذا ضاق شريط الفواتير فلا تظهر تبويبات الفواتير المعلّقة: تتحول أزرار (فاتورة جديدة / تعليق / الخدمات)
        إلى أيقونة فقط، وعند اتساع النافذة يرجع النص. القرار يعتمد على عرض الشريط فقط (بلا تذبذب)."""
        try:
            avail = self.suspend_container.winfo_width()
            if avail <= 1:                      # لم يُرسم الشريط بعد
                return
            btns = [b for b in (getattr(self, "new_invoice_button", None),
                                getattr(self, "suspend_plus_button", None),
                                getattr(self, "hub_button", None)) if b is not None]
            if not btns:
                return
            min_tabs = 260                      # أقل عرض (بالبكسل الأصلي) لمنطقة تبويبات الفواتير المعلّقة
            has_tabs = bool(self.suspend_buttons_frame.winfo_children())
            need = ui_px(4) + sum(b.full_width() + ui_px(6) for b in btns) + ui_px(13) \
                + ui_px(min_tabs if has_tabs else 180)
            compact = avail < need
            for b in btns:
                b.set_compact(compact)
        except (tk.TclError, AttributeError):
            pass

    def _dlv_refresh_hub(self):
        """يُظهر زر «الخدمات» في الشريط فقط إذا كانت إحدى الميزات (طاولات/دليفري/تيك واي) مفعّلة."""
        try:
            show = self._dlv_hub_any()
            btn = getattr(self, 'hub_button', None)
            if show and btn is None:
                self.hub_button = FlatButton(
                    self.suspend_container, text="الخدمات", command=self._dlv_open_hub,
                    bg="#FFFFFF", hover="#FFFFFF", fg="#334155", outline="#D5DCE6", hover_outline="#D5DCE6",
                    icon=self._tbl_icon("apps", 22, "#2563EB"), height=40, radius=8, padx=14, min_width=0,
                    font=(self.font_family, 10, "bold"), canvas_bg=self.bg_color)
                self.hub_button.pack(side=tk.LEFT, padx=(0, 6), pady=8, before=self.suspend_divider)
                self._update_suspend_bar_layout()
            elif not show and btn is not None:
                btn.destroy()
                self.hub_button = None
                self._update_suspend_bar_layout()
                w = getattr(self, '_hub_win', None)
                if w is not None:
                    try:
                        w.destroy()
                    except Exception:
                        pass
                    self._hub_win = None
        except Exception as e:
            print(f"تعذر تحديث زر الخدمات: {e}")

    def _dlv_open_hub(self):
        w = getattr(self, '_hub_win', None)
        try:
            if w is not None and w.winfo_exists():
                w.destroy()
        except Exception:
            pass
        items = self._dlv_hub_items()
        if not items:
            return
        cols = 2 if len(items) <= 4 else 3
        rows = (len(items) + cols - 1) // cols
        TW, TH, PAD = 190, 150, 10
        W, H = cols * (TW + 2 * PAD) + 24, rows * (TH + 2 * PAD) + 84
        win = self._dlv_window("الخدمات", W, H)
        self._hub_win = win
        tk.Label(win, text="الخدمات", font=(self.font_family, 15, "bold"), bg=win['bg'],
                 fg=self.text_dark).pack(pady=(12, 2))
        grid = tk.Frame(win, bg=win['bg'])
        grid.pack(padx=12, pady=4)

        def run(action):
            try:
                win.destroy()
            except Exception:
                pass
            self._hub_win = None
            self.root.after(60, action)

        for i, (title, icon, color, action, sub) in enumerate(items):
            r, c = divmod(i, cols)
            tile = tk.Frame(grid, bg="#FFFFFF", width=TW, height=TH, cursor="hand2",
                            highlightthickness=1, highlightbackground="#D5DCE6")
            tile.grid(row=r, column=cols - 1 - c, padx=PAD, pady=PAD)  # من اليمين لليسار
            tile.pack_propagate(False)
            inner = tk.Frame(tile, bg="#FFFFFF")
            inner.place(relx=0.5, rely=0.5, anchor="center")
            img = self._tbl_icon(icon, 46, color)
            l1 = tk.Label(inner, image=img, bg="#FFFFFF")
            l1.image = img
            l1.pack()
            l2 = tk.Label(inner, text=title, font=(self.font_family, 12, "bold"), bg="#FFFFFF", fg="#0F172A")
            l2.pack(pady=(6, 0))
            l3 = tk.Label(inner, text=sub, font=(self.font_family, 9), bg="#FFFFFF", fg=color)
            l3.pack()
            widgets = (tile, inner, l1, l2, l3)

            def paint(col, ws=widgets, t=tile, cl=color):
                for wdg in ws:
                    wdg.config(bg=col)
                t.config(highlightbackground=cl if col != "#FFFFFF" else "#D5DCE6")

            for wdg in widgets:
                wdg.bind("<Enter>", lambda e, p=paint: p("#F8FAFC"))
                wdg.bind("<Leave>", lambda e, p=paint: p("#FFFFFF"))
                wdg.bind("<Button-1>", lambda e, a=action: run(a))
        win.bind("<Escape>", lambda e: win.destroy())

    # ───────────────────────── ربط الطلب بالفاتورة المعلقة ─────────────────────────
    def _dlv_code(self, order_id, order_type):
        return f"{DLV_PREFIX if order_type == 'delivery' else TKW_PREFIX}{order_id}"

    def _dlv_find_susp_idx(self, code):
        for i, inv in enumerate(getattr(self, 'suspended_invoices', []) or []):
            if str(inv.get('invoice_number') or '') == code:
                return i
        return None

    def _dlv_current_order_id(self):
        """رقم الطلب المرتبط بالفاتورة المعلقة المفتوحة حالياً (أو None)."""
        try:
            db_id = getattr(self, 'current_suspended_db_id', None)
            if db_id is None:
                return None
            for inv in self.suspended_invoices:
                if inv.get('db_id') == db_id:
                    code = str(inv.get('invoice_number') or '')
                    for p in (DLV_PREFIX, TKW_PREFIX):
                        if code.startswith(p):
                            return int(code[len(p):])
        except Exception:
            pass
        return None

    def _dlv_effective_fee(self, legacy_fee):
        """رسم التوصيل الفعلي للفاتورة الحالية.
        المديول مفعّل: الرسم من الطلب فقط (دليفري فقط)، وأي فاتورة عادية رسمها صفر.
        المديول معطّل: يبقى السلوك القديم (رسم ثابت على العميل)."""
        try:
            if not self._dlv_cfg()['enabled']:
                return legacy_fee
            oid = self._dlv_current_order_id()
            if not oid:
                return Decimal("0")
            row = self._dlv_q("SELECT order_type, delivery_fee FROM pos_orders WHERE id=%s", (oid,), one=True)
            if row and row[0] == 'delivery':
                return Decimal(str(row[1] or 0))
            return Decimal("0")
        except Exception as e:
            print(f"تعذر حساب رسم التوصيل: {e}")
            return legacy_fee

    def _dlv_on_invoice_saved(self, invoice_id, invoice_number, delivery_fee, total_amount):
        """يُستدعى من complete_invoice بعد حفظ الفاتورة (داخل نفس المعاملة، بدون commit هنا)."""
        try:
            if not self._dlv_cfg()['enabled']:
                return
            oid = self._dlv_current_order_id()
            if not oid:
                return
            row = self._dlv_q("SELECT order_type, status FROM pos_orders WHERE id=%s", (oid,), one=True)
            if not row:
                return
            otype, status = row
            self._dlv_exec("UPDATE invoices SET delivery_fee=%s, order_type=%s WHERE id=%s",
                           (str(delivery_fee or 0), otype, invoice_id), commit=False)
            auto_done = (otype == 'delivery' and status == 'out') or (otype == 'takeaway' and status == 'ready')
            if auto_done:
                self._dlv_exec("UPDATE pos_orders SET invoice_id=%s, invoice_number=%s, status='done', "
                               "delivered_at=NOW() WHERE id=%s", (invoice_id, invoice_number, oid), commit=False)
            else:
                self._dlv_exec("UPDATE pos_orders SET invoice_id=%s, invoice_number=%s WHERE id=%s",
                               (invoice_id, invoice_number, oid), commit=False)
        except Exception as e:
            print(f"⚠️ تعذر ربط الفاتورة بطلب الدليفري: {e}")

    # ───────────────────────── مناطق/سائقون ─────────────────────────
    def _dlv_zones(self, active_only=True):
        try:
            q = "SELECT id, name, fee, minutes, min_order, active, lat, lng FROM delivery_zones"
            if active_only:
                q += " WHERE active=1"
            out = []
            for r in self._dlv_q(q + " ORDER BY name"):
                r = list(r)
                for i in (6, 7):
                    r[i] = None if r[i] is None else float(r[i])
                out.append(tuple(r))
            return out
        except Exception:
            return []

    def _dlv_drivers(self):
        """[(id, name, busy_count, done_today)] — موظفون وظيفتهم من نوع «سائق توصيل»."""
        try:
            rows = self._dlv_q(
                "SELECT e.id, e.name FROM employees e JOIN job_types jt ON e.job = jt.job_name "
                "WHERE e.left_work = 0 AND jt.job_kind = 'driver' ORDER BY e.name")
            busy = dict(self._dlv_q("SELECT driver_id, COUNT(*) FROM pos_orders WHERE status='out' "
                                    "AND driver_id IS NOT NULL GROUP BY driver_id"))
            done = dict(self._dlv_q("SELECT driver_id, COUNT(*) FROM pos_orders WHERE status='done' "
                                    "AND driver_id IS NOT NULL AND delivered_at >= CURDATE() GROUP BY driver_id"))
            return [(r[0], r[1], int(busy.get(r[0], 0)), int(done.get(r[0], 0))) for r in rows]
        except Exception as e:
            print(f"تعذر تحميل السائقين: {e}")
            return []

    # ═════════════════════════ نافذة طلب جديد ═════════════════════════
    def _dlv_new_order_dialog(self, preset='delivery'):
        cfg = self._dlv_cfg()
        if not cfg['enabled']:
            return
        if not self.product_list.get_children():
            messagebox.showwarning("طلب جديد", "أضف المنتجات إلى الفاتورة أولاً ثم اضغط «طلب توصيل / تيك واي».")
            return
        cur_idx = getattr(self, 'current_suspended_index', None)
        if cur_idx is not None:
            code = str(self.suspended_invoices[cur_idx].get('invoice_number') or '')
            if code.startswith((DLV_PREFIX, TKW_PREFIX)):
                messagebox.showinfo("طلب جديد", "هذه الفاتورة مسجّلة بالفعل كطلب توصيل/تيك واي.")
                return
            if code.startswith(self.TABLE_PREFIX):
                messagebox.showwarning("طلب جديد", "هذه الفاتورة خاصة بطاولة. افتح فاتورة جديدة للطلب.")
                return

        zones = self._dlv_zones()
        win = self._dlv_window("طلب جديد", 720, 860, modal=True)
        try:
            win.minsize(640, 560)
        except Exception:
            pass
        F = self.font_family
        BG, CARD, LINE, DARK, MUTED = "#F1F5F9", "#FFFFFF", "#E2E8F0", "#0F172A", "#64748B"
        BLUE, GREEN = "#2563EB", "#16A34A"
        win.configure(bg=BG)

        v_type = tk.StringVar(value=preset)
        v_phone, v_name, v_addr = tk.StringVar(), tk.StringVar(), tk.StringVar()
        v_zone, v_fee = tk.StringVar(), tk.StringVar(value="0")
        v_prep = tk.StringVar(value=str(cfg['prep_minutes'] if preset == 'delivery' else cfg['takeaway_minutes']))
        v_pay = tk.StringVar(value='prepaid' if preset == 'takeaway' else 'cod')
        v_note = tk.StringVar()
        v_print = tk.IntVar(value=1)
        state = {'customer_id': None, 'zone_id': None, 'travel': 0, 'min_order': Decimal(0),
                 'phone_applied': None, 'phone_job': None, 'lat': None, 'lng': None, 'loc_kind': None,
                 'loc_job': None}
        v_loc = tk.StringVar()
        addr_loc = {}          # {عنوان: (lat, lng)} المحفوظة لعناوين العميل
        zone_by_label = {f"{z[1]} — {float(z[2]):.0f} ج": z for z in zones}

        def items_total():
            """إجمالي أصناف الفاتورة الحالية: يُقرأ من جدول المنتجات المعروض (العمود 1 = إجمالي السطر)."""
            try:
                tot, n = Decimal(0), 0
                for iid in self.product_list.get_children():
                    vals = self.product_list.item(iid)['values']
                    tot += Decimal(str(vals[1]).replace(',', '').strip() or 0)
                    n += 1
                if n:
                    return tot
            except Exception as e:
                print(f"تعذر حساب إجمالي الأصناف من الجدول: {e}")
            try:
                return sum((Decimal(str(p['total_price'])) for p in (self.registered_products or [])), Decimal(0))
            except Exception:
                return None

        # ───────── تذييل ثابت (الإجماليات + الحفظ) ─────────
        footer = tk.Frame(win, bg=CARD, highlightthickness=1, highlightbackground=LINE)
        footer.pack(side="bottom", fill="x")
        # ───────── ترويسة ─────────
        hdr = tk.Frame(win, bg=CARD, highlightthickness=1, highlightbackground=LINE)
        hdr.pack(side="top", fill="x")
        tk.Label(hdr, text="طلب جديد", font=(F, 15, "bold"), bg=CARD, fg=DARK).pack(side="right", padx=18, pady=12)
        tk.Label(hdr, text="تُنشأ الفاتورة المعلقة من الأصناف الحالية وتظهر في شاشة المتابعة", font=(F, 9),
                 bg=CARD, fg=MUTED).pack(side="left", padx=18)

        # ───────── جسم قابل للتمرير ─────────
        wrap = tk.Frame(win, bg=BG)
        wrap.pack(side="top", fill="both", expand=True)
        cv = tk.Canvas(wrap, bg=BG, highlightthickness=0)
        sb = ttk.Scrollbar(wrap, orient="vertical", command=cv.yview)
        body = tk.Frame(cv, bg=BG)
        wid = cv.create_window((0, 0), window=body, anchor="nw")
        body.bind("<Configure>", lambda e: cv.configure(scrollregion=cv.bbox("all")))
        cv.bind("<Configure>", lambda e: cv.itemconfigure(wid, width=e.width))
        cv.configure(yscrollcommand=sb.set)
        sb.pack(side="left", fill="y")
        cv.pack(side="left", fill="both", expand=True)

        def on_wheel(ev):
            try:
                if body.winfo_reqheight() > cv.winfo_height():
                    cv.yview_scroll(int(-ev.delta / 120), "units")
            except Exception:
                pass

        win.bind("<MouseWheel>", on_wheel, add="+")

        def section(title, with_header=True):
            box = tk.Frame(body, bg=CARD, highlightthickness=1, highlightbackground=LINE)
            h = tk.Frame(box, bg=CARD)
            if with_header:
                h.pack(fill="x", padx=14, pady=(10, 2))
                tk.Label(h, text=title, font=(F, 11, "bold"), bg=CARD, fg=DARK).pack(side="right")
            inner = tk.Frame(box, bg=CARD)
            inner.pack(fill="x", padx=14, pady=(4, 12))
            return box, h, inner

        def cap(parent, text):
            return tk.Label(parent, text=text, font=(F, 9, "bold"), bg=CARD, fg=MUTED, anchor="e")

        def entry(parent, var, **kw):
            return tk.Entry(parent, textvariable=var, font=(F, 12), justify="right", bd=0, relief="flat",
                            bg="#F8FAFC", fg=DARK, highlightthickness=1, highlightbackground="#CBD5E1",
                            highlightcolor=BLUE, insertbackground=DARK, **kw)

        def segmented(parent, var, items):
            fr = tk.Frame(parent, bg=LINE, padx=3, pady=3)
            btns = {}

            def paint(*_):
                for val, (lb, color) in btns.items():
                    on = var.get() == val
                    lb.config(bg=color if on else LINE, fg="white" if on else MUTED)

            for val, text, color in items:
                lb = tk.Label(fr, text=text, font=(F, 11, "bold"), padx=14, pady=9, cursor="hand2")
                lb.pack(side="right", expand=True, fill="x", padx=1)
                lb.bind("<Button-1>", lambda e, v=val: var.set(v))
                btns[val] = (lb, color)
            var.trace_add("write", paint)
            paint()
            return fr

        # ───────── نوع الطلب ─────────
        tbox = tk.Frame(body, bg=BG)
        tbox.pack(fill="x", padx=16, pady=(14, 0))
        segmented(tbox, v_type, [("delivery", "🛵  توصيل (دليفري)", BLUE),
                                 ("takeaway", "🛍  استلام من المتجر (تيك واي)", GREEN)]).pack(fill="x")

        # ───────── العميل ─────────
        cbox, chead, cin = section("بيانات العميل")
        cbox.pack(fill="x", padx=16, pady=(10, 0))
        cin.columnconfigure(0, weight=1, uniform="c")
        cin.columnconfigure(1, weight=1, uniform="c")
        cap(cin, "رقم الهاتف").grid(row=0, column=1, sticky="e")
        e_phone = entry(cin, v_phone)
        e_phone.grid(row=1, column=1, sticky="ew", padx=(8, 0), ipady=7)
        cap(cin, "اسم العميل").grid(row=0, column=0, sticky="e")
        e_name = entry(cin, v_name)
        e_name.grid(row=1, column=0, sticky="ew", padx=(0, 8), ipady=7)
        lbl_cust = tk.Label(cin, text="اكتب رقم الهاتف أو الاسم — تظهر قائمة بالعملاء المطابقين للاختيار", font=(F, 9, "bold"),
                            bg="#EFF6FF", fg=BLUE, anchor="e", justify="right", padx=8, pady=4)
        lbl_cust.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(8, 0))

        # ───────── التوصيل (يظهر مع الدليفري فقط) ─────────
        dbox, dhead, din = section("بيانات التوصيل")
        din.columnconfigure(0, weight=1, uniform="d")
        din.columnconfigure(1, weight=1, uniform="d")
        cap(din, "العنوان التفصيلي").grid(row=0, column=0, columnspan=2, sticky="e")
        e_addr = entry(din, v_addr)
        e_addr.grid(row=1, column=0, columnspan=2, sticky="ew", ipady=7)
        cap(din, "المنطقة").grid(row=2, column=1, sticky="e")
        cb_zone = ttk.Combobox(din, textvariable=v_zone, font=(F, 12), state="readonly", justify="right",
                               values=list(zone_by_label.keys()))
        cb_zone.grid(row=3, column=1, sticky="ew", padx=(8, 0), ipady=4)
        cap(din, "رسم التوصيل (ج)").grid(row=2, column=0, sticky="e")
        e_fee = entry(din, v_fee)
        e_fee.config(justify="center")
        e_fee.grid(row=3, column=0, sticky="ew", padx=(0, 8), ipady=7)
        lbl_min = tk.Label(din, text="", font=(F, 9), bg=CARD, fg=MUTED, anchor="e")
        lbl_min.grid(row=4, column=0, columnspan=2, sticky="e", pady=(4, 0))
        lbl_zloc = tk.Label(din, text="", font=(F, 9), bg=CARD, fg=MUTED, anchor="e", justify="right", wraplength=620)
        lbl_zloc.grid(row=5, column=0, columnspan=2, sticky="e", pady=(2, 0))
        if not zones:
            lbl_min.config(text="لا توجد مناطق توصيل — أضفها من الإعدادات", fg="#B45309")

        # ───────── التوقيت والدفع ─────────
        pbox, phead, pin_ = section("التوقيت والدفع")
        pbox.pack(fill="x", padx=16, pady=(10, 0))
        pin_.columnconfigure(0, weight=1, uniform="p")
        pin_.columnconfigure(1, weight=1, uniform="p")
        cap(pin_, "مدة التحضير (دقيقة)").grid(row=0, column=1, sticky="e")
        stp = tk.Frame(pin_, bg=CARD)
        stp.grid(row=1, column=1, sticky="e", padx=(8, 0))

        def step(d):
            try:
                v = int(v_prep.get() or 0)
            except ValueError:
                v = 0
            v_prep.set(str(max(0, min(240, v + d))))

        for txt, d in (("＋", 5), ("", None), ("－", -5)):
            if d is None:
                tk.Entry(stp, textvariable=v_prep, font=(F, 14, "bold"), width=5, justify="center", bd=0,
                         bg="#F8FAFC", highlightthickness=1, highlightbackground="#CBD5E1",
                         highlightcolor=BLUE).pack(side="right", ipady=6, padx=3)
            else:
                tk.Button(stp, text=txt, command=lambda dd=d: step(dd), font=(F, 12, "bold"), bd=0, relief="flat",
                          bg=LINE, fg=DARK, width=3, cursor="hand2").pack(side="right", ipady=3)
        cap(pin_, "الوقت الموعود").grid(row=0, column=0, sticky="e")
        lbl_eta = tk.Label(pin_, text="", font=(F, 16, "bold"), bg=CARD, fg=GREEN, anchor="e")
        lbl_eta.grid(row=1, column=0, sticky="e", padx=(0, 8))
        lbl_eta_sub = tk.Label(pin_, text="", font=(F, 9), bg=CARD, fg=MUTED, anchor="e")
        lbl_eta_sub.grid(row=2, column=0, sticky="e", padx=(0, 8))
        cap(pin_, "طريقة الدفع").grid(row=3, column=0, columnspan=2, sticky="e", pady=(12, 0))
        segmented(pin_, v_pay, [("cod", "الدفع عند التسليم / الاستلام", "#D97706"),
                                ("prepaid", "مدفوع الآن", GREEN)]).grid(row=4, column=0, columnspan=2, sticky="ew",
                                                                         pady=(3, 0))
        cap(pin_, "ملاحظات الطلب").grid(row=5, column=0, columnspan=2, sticky="e", pady=(12, 0))
        entry(pin_, v_note).grid(row=6, column=0, columnspan=2, sticky="ew", ipady=7)

        # ───────── التذييل ─────────
        sumrow = tk.Frame(footer, bg=CARD)
        sumrow.pack(fill="x", padx=16, pady=(10, 0))
        stats = {}
        for key, title, big in (("total", "الإجمالي", True), ("fee", "رسم التوصيل", False),
                                ("items", "الأصناف", False)):
            f = tk.Frame(sumrow, bg=CARD)
            f.pack(side="right", padx=(0, 26))
            tk.Label(f, text=title, font=(F, 9), bg=CARD, fg=MUTED, anchor="e").pack(fill="x")
            stats[key] = tk.Label(f, text="—", font=(F, 17 if big else 12, "bold"), bg=CARD,
                                  fg=GREEN if big else DARK, anchor="e")
            stats[key].pack(fill="x")
        tk.Checkbutton(sumrow, text="طباعة إيصال الطلب", variable=v_print, font=(F, 10), bg=CARD,
                       activebackground=CARD).pack(side="left")
        btnrow = tk.Frame(footer, bg=CARD)
        btnrow.pack(fill="x", padx=16, pady=(8, 12))

        def refresh(*_):
            is_dlv = v_type.get() == 'delivery'
            if is_dlv:
                dbox.pack(fill="x", padx=16, pady=(10, 0), after=cbox)
            else:
                dbox.pack_forget()
            try:
                prep = max(0, int(v_prep.get() or 0))
            except ValueError:
                prep = 0
            travel = state['travel'] if is_dlv else 0
            eta = self._dlv_now() + timedelta(minutes=prep + travel)
            lbl_eta.config(text=self._dlv_fmt_clock(eta), fg=BLUE if is_dlv else GREEN)
            lbl_eta_sub.config(text=f"تحضير {prep} د" + (f" + توصيل {travel} د" if is_dlv else ""))
            it = items_total()
            try:
                fee = Decimal(str(v_fee.get() or 0)) if is_dlv else Decimal(0)
            except Exception:
                fee = Decimal(0)
            stats['items'].config(text=f"{it:,.2f} ج" if it is not None else "—")
            stats['fee'].config(text=f"{fee:,.2f} ج")
            stats['total'].config(text=f"{(it or Decimal(0)) + fee:,.2f} ج")

        def on_type_change(*_):
            v_prep.set(str(cfg['prep_minutes'] if v_type.get() == 'delivery' else cfg['takeaway_minutes']))
            # تيك واي ← «مدفوع الآن» تلقائياً، ودليفري ← «الدفع عند التسليم»
            v_pay.set('prepaid' if v_type.get() == 'takeaway' else 'cod')
            refresh()

        v_type.trace_add('write', on_type_change)
        v_prep.trace_add('write', refresh)
        v_fee.trace_add('write', refresh)

        def on_zone(*_):
            z = zone_by_label.get(v_zone.get())
            if z:
                state['zone_id'], state['travel'] = z[0], int(z[3] or 0)
                state['min_order'] = Decimal(str(z[4] or 0))
                v_fee.set(f"{float(z[2]):.2f}")
                lbl_min.config(text=(f"الحد الأدنى للطلب {float(z[4]):.0f} ج" if z[4] else ""), fg=MUTED)
                if z[6] is not None and z[7] is not None:
                    lbl_zloc.config(text="📍 موقع المنطقة محدد — منه تُحسب المسافة والمسار", fg="#047857")
                else:
                    lbl_zloc.config(text="⚠ لا يوجد موقع لهذه المنطقة — سيُبحث عن العنوان بالاسم (أقل دقة). "
                                         "حدده من الإعدادات ← مناطق التوصيل", fg="#B45309")
            refresh()

        cb_zone.bind("<<ComboboxSelected>>", on_zone)

        # ───────── الموقع: دبوس العنوان المحفوظ (إن وُجد) ← موقع المنطقة ← البحث بالاسم ─────────
        def set_loc(lat, lng, kind):
            state['lat'], state['lng'], state['loc_kind'] = lat, lng, kind

        def addr_changed(*_):
            a = v_addr.get().strip()
            if a in addr_loc and addr_loc[a][0] is not None:
                set_loc(addr_loc[a][0], addr_loc[a][1], 'saved')
            elif state['loc_kind'] == 'saved':
                set_loc(None, None, None)

        v_addr.trace_add('write', addr_changed)

        # ───────── العميل: اختيار من نافذة العملاء الموجودة + بحث بالهاتف ─────────
        def _apply_customer_inner(cid, name, phone, main_addr):
            """يعبّئ بيانات العميل المختار (الاسم/الهاتف/العناوين/آخر منطقة) + ملخص طلباته."""
            state['customer_id'] = cid
            state['phone_applied'] = phone or ""
            v_name.set(name or "")
            v_phone.set(phone or "")
            addr_loc.clear()
            addrs = []
            for ar in self._dlv_q("SELECT address, lat, lng FROM customer_addresses WHERE customer_id=%s "
                                  "ORDER BY last_used DESC", (cid,)):
                addrs.append(ar[0])
                if ar[1] is not None and ar[2] is not None:
                    addr_loc[ar[0]] = (float(ar[1]), float(ar[2]))
            if main_addr and main_addr not in addrs:
                addrs.append(main_addr)
            v_addr.set(main_addr or (addrs[0] if addrs else ""))
            last = self._dlv_q("SELECT zone_id FROM pos_orders WHERE customer_id=%s AND zone_id IS NOT NULL "
                               "ORDER BY id DESC LIMIT 1", (cid,), one=True)
            if last:
                for lbl, z in zone_by_label.items():
                    if z[0] == last[0]:
                        v_zone.set(lbl)
                        on_zone()
                        break
            # رسم التوصيل المحفوظ للعميل (آخر مبلغ استُخدم) يُعبّأ تلقائياً للدليفري
            try:
                cf = self._dlv_q("SELECT delivery_fee FROM customers WHERE id=%s", (cid,), one=True)
                if cf and cf[0] is not None and float(cf[0]) > 0 and v_type.get() == 'delivery':
                    v_fee.set(f"{float(cf[0]):.2f}")
            except Exception as e:
                print(f"تعذر قراءة رسم توصيل العميل: {e}")
            st = self._dlv_q("SELECT COUNT(*), MAX(created_at) FROM pos_orders WHERE customer_id=%s",
                             (cid,), one=True)
            n = int(st[0] or 0) if st else 0
            lbl_cust.config(text=(f"✓ عميل مسجّل — {n} طلب سابق" +
                                  (f" — آخر طلب {st[1].strftime('%Y-%m-%d')}" if n and st[1] else ""))
                            if n else "✓ عميل مسجّل — أول طلب توصيل/تيك واي له", bg="#ECFDF5", fg="#047857")
            refresh()

        def apply_customer(cid, name, phone, main_addr):
            state['quiet'] = True
            try:
                pop_hide()
                state['name_applied'] = name or ""
                _apply_customer_inner(cid, name, phone, main_addr)
            finally:
                state['quiet'] = False

        def lookup(silent=False):
            phone = v_phone.get().strip()
            if not phone:
                return
            try:
                alt = phone[1:] if phone.startswith('0') else '0' + phone
                r = self._dlv_q("SELECT id, name, phone, address FROM customers WHERE phone=%s OR phone=%s "
                                "ORDER BY id DESC LIMIT 1", (phone, alt), one=True)
                if not r:
                    state['customer_id'] = None
                    lbl_cust.config(text="رقم جديد — سيُسجَّل كعميل جديد عند حفظ الطلب", bg="#FEF3C7", fg="#92400E")
                    return
                apply_customer(r[0], r[1], phone if phone else r[2], r[3])
            except Exception as e:
                if not silent:
                    messagebox.showerror("بحث", f"تعذر البحث عن العميل: {e}", parent=win)

        def phone_changed(*_):
            ph = v_phone.get().strip()
            if state['phone_applied'] is not None and ph != state['phone_applied'] and state['customer_id']:
                state['customer_id'] = None
                lbl_cust.config(text="اكتب رقم الهاتف أو الاسم — تظهر قائمة بالعملاء المطابقين للاختيار", bg="#EFF6FF", fg=BLUE)
            if state['phone_job']:
                try:
                    win.after_cancel(state['phone_job'])
                except Exception:
                    pass
                state['phone_job'] = None
            digits = "".join(ch for ch in ph if ch.isdigit())
            if len(digits) >= 8 and ph != state['phone_applied']:
                state['phone_job'] = win.after(500, lambda: lookup(silent=True))

        v_phone.trace_add('write', phone_changed)
        e_phone.bind("<Return>", lambda e: (lookup(), "break")[1])

        def on_picked(cid, name, phone, addr):
            try:
                apply_customer(cid, name, phone, addr)
            except Exception as e:
                messagebox.showerror("العميل", f"تعذر تحميل بيانات العميل: {e}", parent=win)
            try:
                win.lift()
                (e_addr if v_type.get() == 'delivery' else e_name).focus_set()
            except Exception:
                pass

        # ───────── بحث العملاء داخل الحقول (نافذة اختيار تظهر أسفل الحقل أثناء الكتابة) ─────────
        pop = {'top': None, 'lb': None, 'rows': [], 'job': None, 'src': None}

        def pop_hide(*_):
            if pop['job']:
                try:
                    win.after_cancel(pop['job'])
                except Exception:
                    pass
                pop['job'] = None
            t = pop['top']
            if t is not None:
                try:
                    t.destroy()
                except Exception:
                    pass
            pop['top'] = pop['lb'] = pop['src'] = None
            pop['rows'] = []

        def pop_pick(idx=None):
            lb = pop['lb']
            if lb is None:
                return
            if idx is None:
                sel = lb.curselection()
                if not sel:
                    return
                idx = sel[0]
            if idx < 0 or idx >= len(pop['rows']):
                return
            cid, nm, ph, ad = pop['rows'][idx]
            pop_hide()
            on_picked(cid, nm, ph, ad)

        def pop_show(src, rows):
            pop_hide()
            if not rows:
                return
            t = tk.Toplevel(win)
            t.overrideredirect(True)
            try:
                t.attributes('-topmost', True)
            except Exception:
                pass
            lb = tk.Listbox(t, font=(F, 11), height=min(len(rows), 7), activestyle='none', bd=0,
                            highlightthickness=1, highlightbackground=BLUE, selectbackground=BLUE,
                            selectforeground='white', exportselection=False, justify='right')
            for r in rows:
                lb.insert('end', f"{r[1]}   —   {r[2] or 'بدون هاتف'}")
            lb.pack(fill='both', expand=True)
            lb.bind("<ButtonRelease-1>", lambda e: pop_pick(lb.nearest(e.y)))
            lb.bind("<Return>", lambda e: (pop_pick(), "break")[1])
            lb.bind("<Escape>", lambda e: (pop_hide(), src.focus_set(), "break")[2])
            pop.update({'top': t, 'lb': lb, 'rows': list(rows), 'src': src})
            win.update_idletasks()
            w = max(src.winfo_width(), 320)
            t.geometry(f"{w}x{lb.winfo_reqheight()}+{src.winfo_rootx()}+{src.winfo_rooty() + src.winfo_height()}")

        def do_search(src):
            pop['job'] = None
            if state.get('quiet'):
                return
            if src is e_phone:
                term = v_phone.get().strip()
                ok = len("".join(ch for ch in term if ch.isdigit())) >= 3 and term != state['phone_applied']
            else:
                term = v_name.get().strip()
                ok = len(term) >= 2 and term != state.get('name_applied')
            if not ok:
                pop_hide()
                return
            try:
                rows = self._dlv_q(
                    "SELECT id, name, phone, address FROM customers WHERE name LIKE %s OR phone LIKE %s "
                    "ORDER BY (phone=%s) DESC, (name LIKE %s) DESC, id DESC LIMIT 8",
                    (f"%{term}%", f"%{term}%", term, f"{term}%"))
            except Exception as e:
                print(f"تعذر البحث عن العملاء: {e}")
                return
            try:
                if win.focus_get() is not src:
                    return
            except Exception:
                pass
            pop_show(src, rows)

        def schedule_search(src):
            if state.get('quiet'):
                return
            if pop['job']:
                try:
                    win.after_cancel(pop['job'])
                except Exception:
                    pass
            pop['job'] = win.after(250, lambda: do_search(src))

        def focus_list(e):
            lb = pop['lb']
            if lb is not None:
                lb.focus_set()
                lb.selection_clear(0, 'end')
                lb.selection_set(0)
                lb.activate(0)
                return "break"

        def on_esc(e):
            if pop['top'] is not None:
                pop_hide()
                return "break"

        def on_focus_out(e):
            def chk():
                try:
                    f = win.focus_get()
                except Exception:
                    f = None
                if pop['lb'] is not None and f is pop['lb']:
                    return
                pop_hide()
            win.after(250, chk)

        for _w in (e_phone, e_name):
            _w.bind("<Down>", focus_list)
            _w.bind("<Escape>", on_esc)
            _w.bind("<FocusOut>", on_focus_out)
        v_phone.trace_add('write', lambda *_: schedule_search(e_phone))
        v_name.trace_add('write', lambda *_: schedule_search(e_name))
        win.bind("<Configure>", lambda e: pop_hide() if e.widget is win else None, add="+")

        # ───────── حفظ الطلب ─────────
        def confirm():
            otype = v_type.get()
            phone, name, addr = v_phone.get().strip(), v_name.get().strip(), v_addr.get().strip()
            name_in = name   # الاسم كما أدخله الكاشير (قبل الاسم الافتراضي)
            if phone:
                ok, msg, _i = validate_phone_number(phone)
                if not ok:
                    messagebox.showwarning("الهاتف", msg or "رقم الهاتف غير صحيح", parent=win)
                    return
            fee = Decimal("0")
            if otype == 'delivery':
                if not phone or not addr:
                    messagebox.showwarning("بيانات ناقصة", "رقم الهاتف والعنوان مطلوبان للدليفري.", parent=win)
                    return
                if zones and not state['zone_id']:
                    messagebox.showwarning("بيانات ناقصة", "اختر منطقة التوصيل.", parent=win)
                    return
                try:
                    fee = Decimal(str(v_fee.get() or 0))
                    if fee < 0:
                        raise ValueError
                except Exception:
                    messagebox.showwarning("الرسم", "رسم التوصيل غير صحيح.", parent=win)
                    return
                if state['min_order'] > 0:
                    it = items_total()
                    if it is not None and it < state['min_order']:
                        if not messagebox.askyesno(
                                "الحد الأدنى", f"قيمة الطلب {it:.2f} أقل من الحد الأدنى للمنطقة "
                                               f"({state['min_order']:.2f}). هل تريد المتابعة؟", parent=win):
                            return
            elif not phone and not name:
                name = "عميل تيك واي"
            try:
                prep = max(0, int(v_prep.get() or 0))
            except ValueError:
                prep = cfg['prep_minutes']
            travel = state['travel'] if otype == 'delivery' else 0
            o_lat = o_lng = o_prec = None
            if otype == 'delivery':
                zrow_ = next((z for z in zones if z[0] == state['zone_id']), None)
                if state['lat'] is not None:
                    o_lat, o_lng, o_prec = state['lat'], state['lng'], 'pin'
                elif zrow_ and zrow_[6] is not None and zrow_[7] is not None:
                    o_lat, o_lng, o_prec = zrow_[6], zrow_[7], 'zpin'
            try:
                cid = state['customer_id']
                if phone and not cid:
                    r = self._dlv_q("SELECT id FROM customers WHERE phone=%s LIMIT 1", (phone,), one=True)
                    cid = r[0] if r else None
                if phone and not cid:
                    cid = self._dlv_exec("INSERT INTO customers (name, phone, address, delivery_fee) VALUES (%s,%s,%s,%s)",
                                         (name or phone, phone, addr, str(fee) if otype == 'delivery' else '0'))
                elif cid:
                    # عميل موجود: تحديث بياناته في جدول العملاء (الاسم + العنوان + رسم التوصيل الخاص به)
                    sets, vals = [], []
                    if name_in:
                        sets.append("name=%s")
                        vals.append(name_in)
                    if otype == 'delivery':
                        if addr:
                            sets.append("address=%s")
                            vals.append(addr)
                        sets.append("delivery_fee=%s")
                        vals.append(str(fee))
                    if sets:
                        self._dlv_exec(f"UPDATE customers SET {', '.join(sets)} WHERE id=%s", tuple(vals) + (cid,))
                if cid and otype == 'delivery' and addr:
                    ex = self._dlv_q("SELECT id FROM customer_addresses WHERE customer_id=%s AND address=%s",
                                     (cid, addr), one=True)
                    if ex:
                        self._dlv_exec("UPDATE customer_addresses SET last_used=NOW(), zone_id=%s, "
                                       "lat=COALESCE(%s, lat), lng=COALESCE(%s, lng) WHERE id=%s",
                                       (state['zone_id'], state['lat'], state['lng'], ex[0]))
                    else:
                        self._dlv_exec("INSERT INTO customer_addresses (customer_id, address, zone_id, lat, lng) "
                                       "VALUES (%s,%s,%s,%s,%s)",
                                       (cid, addr, state['zone_id'], state['lat'], state['lng']))
                zone_name = next((z[1] for z in zones if z[0] == state['zone_id']), None)
                oid = self._dlv_exec(
                    "INSERT INTO pos_orders (order_type, status, customer_id, customer_name, phone, address, "
                    "zone_id, zone_name, delivery_fee, prep_minutes, travel_minutes, payment_mode, notes, "
                    "created_at, promised_at, created_by, shift_number, lat, lng, geo_prec) "
                    "VALUES (%s,'preparing',%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,NOW(),"
                    "DATE_ADD(NOW(), INTERVAL %s MINUTE),%s,%s,%s,%s,%s)",
                    (otype, cid, name or "عميل", phone, addr if otype == 'delivery' else None,
                     state['zone_id'] if otype == 'delivery' else None, zone_name if otype == 'delivery' else None,
                     str(fee), prep, travel, v_pay.get(), v_note.get().strip() or None, prep + travel,
                     getattr(self, 'employee_id', None), getattr(self, 'current_shift_number', None),
                     o_lat, o_lng, o_prec))
            except Exception as e:
                messagebox.showerror("خطأ", f"تعذر حفظ الطلب: {e}", parent=win)
                return

            # ربط الفاتورة الحالية بالطلب (نفس خطوات ربط الطاولة)
            try:
                code = self._dlv_code(oid, otype)
                disp = name or "عميل"
                self.selected_customer_id = cid
                self.customer_label.config(text=disp)
                if cur_idx is not None:
                    self._save_current_suspended_changes()
                    inv = self.suspended_invoices[cur_idx]
                    inv['invoice_number'] = code
                    inv['customer_id'] = cid
                    inv['customer_name'] = disp
                else:
                    self._save_current_to_suspended()
                    inv = self.suspended_invoices[-1]
                    inv['invoice_number'] = code
                try:
                    btn = self.suspend_buttons[cur_idx if cur_idx is not None else -1]
                    btn.config(text=self._suspend_btn_text(inv))
                except Exception:
                    pass
                self.clear_current_invoice()
                self.current_suspended_index = None
                self.current_suspended_db_id = None
                self._update_suspend_buttons_colors()
                self.save_suspended_invoices_to_db()
                self.load_suspended_invoices_from_db()
            except Exception as e:
                messagebox.showerror("خطأ", f"تم تسجيل الطلب #{oid} لكن تعذر تعليق الفاتورة: {e}", parent=win)
            win.destroy()
            if v_print.get():
                # نسختان: (1) الإيصال الكامل بالأسعار  (2) تذكرة التحضير (أصناف وكميات فقط)
                try:
                    self._dlv_print_slip(oid)
                except Exception as e:
                    print(f"تعذر طباعة إيصال الطلب: {e}")
                try:
                    self._dlv_print_kitchen_ticket(oid)
                except Exception as e:
                    print(f"تعذر طباعة تذكرة التحضير: {e}")
            if v_pay.get() == 'prepaid':
                idx = self._dlv_find_susp_idx(self._dlv_code(oid, otype))
                if idx is not None:
                    self.load_suspended_invoice(idx)
                    messagebox.showinfo("طلب مدفوع", "الطلب مسجّل. أكمل الدفع الآن من شاشة الفاتورة.")
            elif getattr(self, '_dlv_win', None) is not None:
                self._dlv_poll(force=True)

        self._dlv_btn(btnrow, "حفظ الطلب", confirm, color=GREEN, size=13, padx=34, pady=9).pack(side="right")
        self._dlv_btn(btnrow, "إلغاء", win.destroy, color=MUTED, size=11, padx=20, pady=9).pack(side="right", padx=8)
        win.bind("<Escape>", lambda e: win.destroy())
        win.bind("<Control-Return>", lambda e: confirm())
        refresh()
        e_phone.focus_set()

    # ═════════════════════════ شاشة المتابعة ═════════════════════════
    _DLV_COLS = [
        ('preparing', 'قيد التحضير', '#2563EB'),
        ('ready', 'جاهز', '#D97706'),
        ('out', 'في الطريق', '#7C3AED'),
        ('done', 'مكتمل اليوم', '#16A34A'),
    ]
    _DLV_FIELDS = ['id', 'order_type', 'status', 'customer_name', 'phone', 'address', 'zone_name', 'delivery_fee',
                   'created_at', 'promised_at', 'ready_at', 'dispatched_at', 'delivered_at', 'driver_id',
                   'driver_name', 'invoice_id', 'payment_mode', 'notes', 'inv_total', 'has_susp',
                   'susp_total', 'susp_disc', 'lat', 'lng', 'route_km', 'route_min', 'geo_prec', 'zlat', 'zlng', 'travel_minutes']

    def _dlv_close_monitor(self):
        for jn in ('_dlv_poll_job', '_dlv_tick_job'):
            j = getattr(self, jn, None)
            if j:
                try:
                    self.root.after_cancel(j)
                except Exception:
                    pass
                setattr(self, jn, None)
        w = getattr(self, '_dlv_win', None)
        if w is not None:
            try:
                w.destroy()
            except Exception:
                pass
        self._dlv_win = None

    # ───────────────────────── صور وأدوات التصميم الحديث ─────────────────────────
    def _dlv_img(self, key, builder):
        cache = self.__dict__.setdefault('_dlv_img_cache', {})
        im = cache.get(key)
        if im is None:
            im = ImageTk.PhotoImage(builder())
            cache[key] = im
        return im

    def _dlv_badge(self, kind, size, fg, tint):
        return self._dlv_img(('badge', kind, size, fg, tint), lambda: _dlv_badge_pil(kind, size, fg, tint))

    def _dlv_marker_img(self, glyph, color, size=44, flip=False):
        return self._dlv_img(('mk', glyph, color, size, flip),
                             lambda: _dlv_round_marker_pil(glyph, color, size, flip))

    def _dlv_trip(self, o, ent=None):
        """تقدّم رحلة الطلب الخارج مع سائق (حسب الوقت): (نسبة 0..1، ثواني متبقية، وقت الوصول المتوقع، دقائق الرحلة).
        مدة الرحلة = الزمن المحسوب للمسار (نفس «وصول ..» على الكارت)، وإلا مدة المنطقة، وإلا 15 دقيقة."""
        mins = None
        if ent and ent.get('min') is not None:
            mins = float(ent['min'])
        if not mins:
            mins = float(o.get('travel_minutes') or 0) or 15.0
        mins = max(mins, 1.0)
        total = mins * 60.0
        d0 = o.get('dispatched_at')
        if not d0:
            return 0.0, total, None, mins
        eta = d0 + timedelta(minutes=mins)
        el = (self._dlv_now() - d0).total_seconds()
        return min(max(el / total, 0.0), 1.0), total - el, eta, mins

    def _dlv_soft_btn(self, parent, text, command, color, solid=False, **kw):
        """زر حديث: ناعم (خلفية فاتحة ونص ملوّن) أو صلب للإجراء الأساسي، مع تأثير عند التمرير."""
        bg = color if solid else _mix(color, "#FFFFFF", 0.86)
        fg = "#FFFFFF" if solid else color
        hov = _mix(color, "#000000", 0.14) if solid else _mix(color, "#FFFFFF", 0.72)
        b = tk.Button(parent, text=text, command=command, bg=bg, fg=fg, bd=0, relief="flat",
                      font=(self.font_family, kw.pop('size', 9), "bold"), cursor="hand2",
                      activebackground=hov, activeforeground=fg,
                      padx=kw.pop('padx', 10), pady=kw.pop('pady', 4), **kw)
        b.bind("<Enter>", lambda e: b.config(bg=hov))
        b.bind("<Leave>", lambda e: b.config(bg=bg))
        return b

    def _dlv_stepper(self, parent, n, idx, accent, bg="#FFFFFF"):
        """شريط مراحل بنقاط (مكتمل • الحالية • القادمة) بدل الشرائط الرفيعة."""
        cv = tk.Canvas(parent, height=18, bg=bg, highlightthickness=0)

        def draw(_e=None):
            cv.delete("all")
            W = max(cv.winfo_width(), 80)
            pad = 12
            xs = [W - pad - i * (W - 2 * pad) / max(n - 1, 1) for i in range(n)]
            for i in range(n - 1):
                cv.create_line(xs[i], 9, xs[i + 1], 9, fill=accent if i < idx else "#E2E8F0", width=3,
                               capstyle="round")
            for i, x in enumerate(xs):
                if i < idx:
                    cv.create_oval(x - 5, 4, x + 5, 14, fill=accent, outline=accent)
                elif i == idx:
                    cv.create_oval(x - 7, 2, x + 7, 16, fill=accent, outline=accent)
                    cv.create_oval(x - 3, 6, x + 3, 12, fill="#FFFFFF", outline="#FFFFFF")
                else:
                    cv.create_oval(x - 4, 5, x + 4, 13, fill="#E2E8F0", outline="#E2E8F0")

        cv.bind("<Configure>", draw)
        return cv

    def _dlv_live_strip(self, parent, o):
        """شريط رحلة مباشر على كارت الطلب الخارج: المتجر ← دراجة تتحرك ← العميل، بحسب الوقت المتوقع للوصول.
        يتحدّث كل ثانية مع عدّاد الكروت."""
        F = self.font_family
        oid = o['id']
        cv = tk.Canvas(parent, height=46, bg="#FFFFFF", highlightthickness=0)
        cv.pack(fill="x", padx=10, pady=(0, 4))
        img = self._dlv_marker_img('scooter', '#7C3AED', 28, True)     # تتحرك من اليمين (المتجر) لليسار (العميل)

        def draw(_e=None):
            try:
                if not cv.winfo_exists():
                    return
            except Exception:
                return
            W = max(cv.winfo_width(), 140)
            ent = getattr(self, '_dlv_geo_cache', {}).get(oid)
            frac, rem, _eta, _m = self._dlv_trip(o, ent)
            cv.delete("all")
            xr, xl, y = W - 18, 18, 31
            x = xr - (xr - xl) * frac
            cv.create_line(xr, y, xl, y, fill="#E2E8F0", width=5, capstyle="round")
            if frac > 0.003:
                cv.create_line(xr, y, x, y, fill="#A78BFA", width=5, capstyle="round")
            cv.create_oval(xr - 5, y - 5, xr + 5, y + 5, fill="#2563EB", outline="#FFFFFF", width=2)
            cv.create_oval(xl - 5, y - 5, xl + 5, y + 5, fill="#DC2626", outline="#FFFFFF", width=2)
            cv.create_image(x, y - 2, image=img)
            if rem > 0:
                txt, col = f"متبقي {self._dlv_mmss(rem)}", "#6D28D9"
            else:
                txt, col = f"تجاوز الوقت {self._dlv_mmss(-rem)}", "#DC2626"
            cv.create_text(W / 2, 9, text=txt, fill=col, font=(F, 9, "bold"))
            cv.create_text(W - 4, 9, text="المتجر", anchor="e", fill="#94A3B8", font=(F, 8))
            cv.create_text(4, 9, text="العميل", anchor="w", fill="#94A3B8", font=(F, 8))

        cv.bind("<Configure>", draw)
        self.__dict__.setdefault('_dlv_live', []).append(draw)
        draw()

    def _dlv_open_monitor(self):
        """يفتح نافذة متابعة الطلبات بتصميم احترافي حديث (Light Theme)"""
        w = getattr(self, '_dlv_win', None)
        if w is not None:
            try:
                if w.winfo_exists():
                    w.deiconify()
                    w.lift()
                    w.focus_force()
                    return
            except Exception:
                pass

        win = self._dlv_window("متابعة الطلبات", 1280, 760)
        try:
            win.minsize(1000, 580)
            win.state("zoomed")
        except Exception:
            pass
        self._dlv_win = win
        self._dlv_sig = None
        self._dlv_timers = []
        self._dlv_live = []
        self._dlv_wrap_labels = {}
        self._dlv_search = tk.StringVar()
        self._dlv_filter = tk.StringVar(value='all')
        F = self.font_family

        # ════════ Palette (Light Theme) ════════
        BG = "#F4F6FA"
