        delivery_frame = tk.Frame(input_frame, bg=self.input_bg, highlightthickness=1,
                                  highlightbackground=self.border_color, highlightcolor=self.accent_color)
        delivery_frame.grid(row=2, column=2, padx=5, pady=5, sticky="ew")
