                """حقل فلتر بعنوان صغير فوق عنصر التحكم"""
                box = tk.Frame(filter_inner, bg=self.card_bg)
                box.pack(side='right', padx=(0, 20))
                tk.Label(box, text=caption, font=(ff, 9, 'bold'), bg=self.card_bg, fg=self.text_muted,
                         anchor='e').pack(anchor='e', pady=(0, 4))
